int main(){
    std::ios_base::sync_with_stdio(false); cin.tie(0);
    int n;
    cin >> n;
    vi arr(n);
    for (int i = 0; i < n; i++){
        cin >> arr[i];
        arr[i]--;
    }
    vi ans(n * n, -1);
    vi rv(n + 1);
    vi place(n + 1);
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    for (int i = 0; i < n; i++){
        ans[arr[i]] = i + 1;
        rv[i + 1] = n - 1 - i;
        place[i + 1] = arr[i];
        for (int j = 0; j < i; j++)
            pq.emplace(arr[i], i + 1);
    }
    vi left;
    bool poss = true;
    for (int i = 0; i < n*n; i++){
//        debug(ans);
        if (ans[i] != -1) {
            for (int j = 0; j < rv[ans[i]]; j++){
                left.push_back(ans[i]);
            }
        } else {
            if (!pq.empty()){
                pii p = pq.top(); pq.pop();
                if (place[p.Y] <= i) {
                    poss = false;
                    break;
                }
                ans[i] = p.Y;
            } else {
                if (left.empty()){
                    poss = false;
                    break;
                }
                ans[i] = left.back();
                left.pop_back();
            }
        }
    }
    if (!poss) cout << "No" << endl;
    else {
        cout << "Yes" << endl;
        for (int x : ans)
            cout << x << ' ';
        cout << endl;
    }



}

