        cntl[i] = i;
        cntr[i] = n - i - 1;
        std::cin >> arr[i].first;
        --arr[i].first;
        arr[i].second = i;
    }
    std::sort(arr, arr + n);

    int a = 0, b = 0;
    std::vector<int> vec;
    vec.reserve(n * n);
    for(int i = 0; i < n * n; ++i) {
//        DEB1(b)
        if(a != n && i == arr[a].first) {
            if(cntl[arr[a].second] != 0) {
                std::cout << "No" << std::endl;

                return 0;
            }

            vec.push_back(arr[a].second + 1);
            ++a;
        }else if(b < n) {
            while(cntl[arr[b].second] == 0) {
                ++b;

                if(n <= b) {
                    goto SECOND;
                }
            }

            --cntl[arr[b].second];
            vec.push_back(arr[b].second + 1);
        }else {
            SECOND:;
            if(b - n >= a) {
                std::cout << "No" << std::endl;

                return 0;
            }
            while(cntr[arr[b - n].second] == 0) ++b;

            --cntr[arr[b - n].second];
            vec.push_back(arr[b - n].second + 1);
        }
