		ans[d[i - 1].first] = i;
	}
	sort(d.begin(), d.end());
	lint count = 1;
	for (int i = 0; i < n; i++) {
		cnt = 0;
		while (cnt < d[i].second - 1) {
			if (ans[count] == 0) 
				cnt++, ans[count] = d[i].second;
			count++;
		}
		if (count - 1 >= d[i].first) {
