void show_arr(const std::vector<int>& vector);

int main() {
	int N;
	std::cin >> N;

	std::map<int, int> sorted_x; // K: xi, V: i
	for (int i = 1; i <= N; ++i) {
		int xi;
		std::cin >> xi;
		sorted_x.emplace(xi - 1, i);
	}

	std::vector<int> arr;
	arr.resize((size_t) (N * N), 0);
	int first = 0;
	for (auto& p : sorted_x) {
		int xi = p.first;
		int i = p.second;
		int needed_before = i - 1;
		for (int j = first; j < xi && needed_before > 0; ++j) {
			if (arr[j] == 0) {
				arr[j] = i;
				needed_before--;
				if (first == j) {
					first++;
				}
			} else {
				first++;
			}
		}
		if (needed_before > 0) {
			std::cout << "No" << std::flush;
			return 0;
		}
		arr[xi] = i;
	}
	int last = N * N - 1;
	for (auto it = sorted_x.rbegin(); it != sorted_x.rend(); ++it) {
		auto& p = *it;
		int xi = p.first;
		int i = p.second;
		int needed_after = N - i;
		for (int j = last; j > xi && needed_after > 0; --j) {
			printf("i=%d, j=%d, needed_after=%d\n", i, j, needed_after);
			if (arr[j] == 0) {
				arr[j] = i;
				--needed_after;
				if (last == j) {
					last--;
				}
			} else {
				last--;
			}
		}
		if (needed_after > 0) {
			std::cout << "No" << std::flush;
			return 0;
		}
	}
	std::cout << "Yes" << std::endl;
	show_arr(arr);
}

void show_arr(const std::vector<int>& arr) {
	bool is_first = true;
	for (int x : arr) {
		if (!is_first) {
			std::cout << ' ';
		} else {
			is_first = false;
		}
		std::cout << x;
	}
	std::cout << std::endl;
}

