void solve() {
  int n;
  cin >> n;
  vi32 x(n);
  cin >> x;
  rep(i, n) x[i]--;
  using T = tuple<int, int>;
  pqasc<T> pq;
  queue<int> q;
  vi32 used(n, 0);
  rep(i, n) {
    if (i != 0) {
      pq.emplace(x[i], i);
    }
  }
  vi32 a(n * n);
  rep(i, n) a[x[i]] = i + 1;
  rep(i, n * n) {
    if (a[i] != 0) {
      int id = a[i] - 1;
      if (used[id] < id) {
        no();
      }
      used[id] += 1;
      q.emplace(id);
    } else {
      if (sz(pq)) {
        int xi, id;
        tie(xi, id) = pq.top();
        a[i] = id + 1;
        used[id] += 1;
        if (used[id] == id) {
          pq.pop();
        }
      } else {
        int id = q.front();
        q.pop();
        a[i] = id + 1;
        used[id] += 1;
        if (used[id] < n) {
          q.emplace(id);
        }
      }
    }
  }
