    void run(){
        ll N;
        is >> N;
        if(!is) return;
        vector<ll> a(N*N, -1);
        vector<ll> X(N*N, -1);
        for (int i = 0; i < N; ++i) {
            int x;
            is >> x; x--;
            X[x] = i+1;
        } // end i
        int l = 0;
        for (int i = 0; i < X.size(); ++i) {
            if(X[i] != -1) {
                int t = X[i]-1;
                int k = X[i];
                a[i] = k;
                while (t > 0) {
                    if (a[l] == -1) {
                        a[l] = k; t--;
                    }
                    l++;
                    if(l >= i){
                        os << "No\n"; return;
                    }
                }
            }
        } // end i
        map<ll, ll> rem;
        for (int i = 0; i < a.size(); ++i) {
            if(X[i] != -1){
                if(X[i] != N) rem[X[i]] = N-X[i];
            }
            else if(a[i] == -1){
                if(rem.empty()){ os << "No\n"; return; }
                a[i] = rem.begin()->first;
                rem.begin()->second--;
                if(rem.begin()->second == 0) rem.erase(rem.begin());
            }
        } // end i

        os << "Yes\n";
        for (auto &&ai : a) {
            assert(ai != -1);
            os << ai << ' ' ;
        } // end ai
