void solve(){
	int N;
	cin >> N;
	vector< vector<int> > X(N,vector<int>(2));
	for(int i=0;i<N;++i){
		cin >> X[i][0];
		X[i][1] = i+1;
	}
	sort(X.begin(), X.end());
	vector<int> ans(N*N,-1);
	vector<int> at(N+1,N);
	int pos = 0;
	for(int i=0;i<N;++i){
		int No = X[i][1];//対象の数
		int ter = X[i][0];//[ter-1]まででNo個置く
		if( ans[ter-1] != -1 ){
			cout << "No" << endl;return;
		}
		ans[ter-1] = No;
		int nokori = No-1;
		for(;nokori && pos<ter-1;++pos){
			if( ans[pos] == -1 ){
				ans[pos] = No;
				--nokori;
			}
		}
		if( nokori ){
			cout << "No" << endl;return;
		}
		at[No] -= No;//設置した数引く
	}
	//余ってる数を設置する。
	for(int i=0;i<N;++i){
		int No = X[i][1];//対象の数
		int ter = X[i][0];//[ter-1]まででNo個置く
		if( pos < ter-1 ){//ter-1より前には置けない
			cout << "No" << endl;return;
		}
		for(;at[No] && pos<N*N;++pos){
			if( ans[pos] == -1 ){
				ans[pos] = No;
				at[No]--;
			}
		}
		if( at[No] ){//
			cout << "No" << endl;return;
		}
	}
	cout << "Yes" << endl;
	for(int i=0;i<N*N;++i){
		if(i)cout << ' ';
		cout << ans[i];
	}cout << endl;
}
