struct yes_no : numpunct<char> {
  string_type do_truename()  const { return "Yes"; }
  string_type do_falsename() const { return "No"; }
};

void solve(ll N, vector<ll> x) {
  vector<int> res(N * N);
  vector<pair<int,int>> vec;
  REP(i,N) vec.emplace_back(x[i] - 1, i + 1);
  sort(ALL(vec));
  set<int> s;
  REP(i,N*N) s.insert(i);

  for (auto p: vec) {
    res[p.first] = p.second;
    s.erase(p.first);
  }
  for (auto p: vec) {
    REP(i,p.second - 1) {
      int num = *s.begin();
      s.erase(s.begin());
      if (num > p.first) { cout << false << endl; return; }
      res[num] = p.second;
    }
  }
  reverse(ALL(vec));
  for (auto p: vec) {
    REP(i,N-p.second) {
      int num = *prev(s.end());
      s.erase(prev(s.end()));
      if (num < p.first) { cout << false << endl; return; }
      res[num] = p.second;
    }
  }
  cout << true << endl;
  REP(i,N*N) cout << res[i] << " \n"[i == N * N - 1];
}

int main() {
  locale loc(locale(), new yes_no);
  cout << boolalpha << setprecision(12) << fixed;
  cout.imbue(loc);
	ll N;
	scanf("%lld", &N);
	vector<ll> x(N-1+1);
	for (int i = 0 ; i <= N-1 ; i++) {
	  scanf("%lld", &x[i]);
	}
	solve(N, x);
	return 0;
}

