#define RI register int
#define Cannot puts("No"), exit(0);
typedef long long LL;

#define FILEIO(name) freopen(name".in", "r", stdin), freopen(name".out", "w", stdout);

using namespace std;

char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && ch != '-') ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 505;
struct Node { int pos, id; } t[MAXN];
int ans[MAXN * MAXN];
int pre[MAXN], nxt[MAXN];

inline bool cmp(Node x, Node y) { return x.pos < y.pos; }

inline void Make(int pos) {
  int now = pos;
  while (ans[pos]) pos = pre[pos];
  if (!pos) Cannot;
  while (pos != now) ans[pos] = ans[nxt[pos]], pos = nxt[pos];
}

inline void Put(int pos, int num, int cnt) {
  for (RI i = nxt[0]; i <= pos && i; i = nxt[i])
    if (!ans[i] && cnt)
      ans[i] = num, --cnt;
  if (cnt) Cannot;
}

inline void End(int pos, int num, int cnt) {
  int i = nxt[0];
  while (nxt[i]) i = nxt[i];
  for (; i && i > pos; i = pre[i])
    if (!ans[i] && cnt)
      ans[i] = num, --cnt;
  if (cnt) Cannot;
}

int main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n; cin >> n;
  for (RI i = 1; i <= n; ++i)
    scanf("%d", &t[i].pos), t[i].id = i;
  sort(t + 1, t + 1 + n, cmp);
  for (RI i = 1; i <= n * n; ++i)
    nxt[i - 1] = i, pre[i] = i - 1;
  for (RI i = 1; i <= n; ++i) {
    Make(t[i].pos);
    ans[t[i].pos] = t[i].id;
    nxt[pre[t[i].pos]] = nxt[t[i].pos];
    pre[nxt[t[i].pos]] = pre[t[i].pos];
    Put(t[i].pos, t[i].id, t[i].id - 1);
    End(t[i].pos, t[i].id, n - t[i].id);
  }
  puts("Yes");
  for (RI i = 1; i <= n * n; ++i)
    printf("%d ", ans[i]);

  return 0;
}

