int N;

int main()
{
	scanf("%d",&N);
	vector< pair<int,int> > P(N);
	vector<int> ans(N * N,-1);
	for(int i = 0;i < N;i++){
		scanf("%d",&P [i].first);
		P [i].first--;
		ans [P [i].first] = i;
		P [i].second = i;
	}
	sort(P.begin(),P.end());

	vector< queue<int> > q1(N,queue<int>());
	queue<int> q2;
	for(int i = 0;i < N;i++){
		for(int j = 0;j < P [i].second;j++){
			q1 [P [i].second].push(P [i].second);
		}
	}
	int idx = 0;
	for(int i = 0;i < N * N;i++){
		if(ans [i] != -1){
			if(q1 [ans [i]].empty() == false){
				printf("No\n");
				return 0;
			}
			else{
				for(int j = 0;j < N - ans [i] - 1;j++){
					q2.push(ans [i]);
				}
			}
		}
		else{
			while(idx < N && q1 [P [idx].second].empty() == true) idx++;
			if(q1 [P [idx].second].empty() == false){
				ans [i] = q1 [P [idx].second].front();
				q1 [P [idx].second].pop();
			}
			else if(q2.empty() == false){
				ans [i] = q2.front();
				q2.pop();
			}
			else{
				printf("No\n");
				return 0;
			}
		}
	}

	printf("Yes\n");
	for(int i = 0;i < N * N;i++){
		printf("%d%s",ans [i] + 1,i == N * N - 1 ? "\n" : " ");
	}

	return 0;
}

