int main(){
	scanf("%d",&n);
	for (int i=1;i<=n;i++)
		scanf("%d",&x[i].x),x[i].i=i;
	sort(x+1,x+n+1);
	for (int i=1;i<n;i++)
		if (x[i].x==x[i+1].x)
			return puts("No"),0;
	int L=1,R=n*n;
	memset(a,0,sizeof a);
	for (int i=1;i<=n;i++)
		a[x[i].x]=x[i].i;
	for (int i=1;i<=n;i++){
