int N;
int x[510];

void _main() {
    cin >> N;
    REP(i, N) cin >> x[i];
    using P = tuple<int, int, int>;
    priority_queue<P, vector<P>, greater<P>> q;
    vector<int> ans(N * N, 0), rem(N, N - 1);
    REP(i, N) {
        ans[x[i] - 1] = i + 1;
        if (i) q.emplace(x[i] - i - 1, i, i + 1);
    }
    int last = 0;
    while (!q.empty()) {
        int lim, cnt, val;
        tie(lim, cnt, val) = q.top();
        q.pop();
        if (ans[last]) {
            q.emplace(lim, cnt, val);
            last++;
            continue;
        }
        if (last <= lim) {
            ans[last] = val;
            if (cnt > 1) {
                q.emplace(lim + 1, cnt - 1, val);
                last++;
                rem[val - 1]--;
            }
        } else {
            cout << "No" << endl;
            return;
        }
    }
    REP(i, N) {
        while (rem[i]) {
            while (last < N * N && ans[last]) last++;
            ans[last] = i + 1;
            rem[i]--;
        }
    }
    cout << ans << endl;
}

