const double PI = acos(-1.0);
const LL INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL)INF;

struct Q
{
	int pos;
	int left;
	int ind;

	Q(int pos, int left, int ind)
	{
		this->pos = pos;
		this->left = left;
		this->ind = ind;
	}

	bool operator <(const Q& q) const
	{
		if (pos == q.pos) return ind < q.ind;
		return pos < q.pos;
	}
};

const int MAX = 555;

int A[MAX];
int RES[MAX * MAX];
int P[MAX * MAX];

set<Q> S, T;
int n;

void NO()
{
	cout<<"No"<<endl;
	/*FOR (i, 0, n*n)
	{
		cout<<RES[i] + 1<<' ';
	}
	cout<<endl;*/
	exit(0);
}


int main()
{
	//freopen("in.txt", "r", stdin);
	//ios::sync_with_Stdio(false); cin.tie(0);

	FILL(P, -1);
	FILL(RES, -1);

	scanf("%d", &n);
	FOR (i, 0, n)
	{
		int x;
		scanf("%d", &x);
		x--;

		if (i) S.insert(Q(x-1, i, i));
		A[i] = x;

		if (P[x] != -1) NO();
		P[x] = i;
	}

	FOR (i, 0, n*n)
	{
		if (P[i] != -1)
		{
			RES[i] = P[i];
			if (n - P[i] - 1) T.insert(Q(i+1, n - P[i] - 1, P[i]));
			continue;
		}

		if (SZ(S))
		{
			Q a = *S.begin();
			S.erase(S.begin());
			if (a.pos < i) NO();

			RES[i] = a.ind;
			a.left--;
			if (a.left) S.insert(a);
		}
		else
		{
			if (T.empty()) NO();

			Q a = *T.begin();
			T.erase(T.begin());

			RES[i] = a.ind;
			a.left--;
			if (a.left) T.insert(a);
		}
	}

	if (SZ(S) || SZ(T)) NO();

	printf("Yes\n");
	FOR (i, 0, n*n)
	{
		printf("%d ", RES[i] + 1);
	}
	printf("\n");


}

