class dsu {
 public:
  int n;
  vector<int> parent;

  dsu(int _n) : n(_n) {
    parent.resize(n);
    iota(parent.begin(), parent.end(), 0);
  }

  int find(int x) {
    if (x == -1 || x == parent[x]) {
      return x;
    }
    return parent[x] = find(parent[x]);
  }

};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  vector<int> ans(n * n, -1);
  dsu d(n * n);
  vector<int> x(n);
  for (int i = 0; i < n; i++) {
    cin >> x[i];
  }
  for (int i = 0; i < n; i++) {
    int t = i;
    for (int j = x[i] - 1; j >= 0 && t >= 0; t--, j = d.find(j)) {
      ans[j] = i;
      d.parent[j] = j - 1;
    }
    if (t > 0) {
      cout << "No\n";
      return 0;
    }
  }
  vector<int> pending(n);
  for (int i = 0; i < n; i++) {
    pending[i] = n - i - 1;
  }
  int ptr = 0;
  for (int i = 0; i < n * n; i++) {
    if (ans[i] == -1) {
      if (pending[ptr] == 0) {
        ptr++;
      }
