const int N = 505;
struct Edge {int to, flow;};
template < int MXN > struct Dinic
{
    int s, t, P[MXN], D[MXN], qu[MXN];
    vector < int > Adj[MXN];
    vector < Edge > E;
    inline void Add(int v, int u, int w)
    {
        Adj[v].pb(E.size());
        E.pb({u, w});
        Adj[u].pb(E.size());
        E.pb({v, 0});
    }
    inline bool BFS()
    {
        int l = 0, r = 0;
        memset(P, 0, sizeof(P));
        memset(D, -1, sizeof(D));
        D[s] = 0; qu[r ++] = s;
        while (r - l)
        {
            int v = qu[l ++];
            if (v == t) return 1;
            for (int &id : Adj[v])
                if (E[id].flow && D[E[id].to] == -1)
                    D[E[id].to] = D[v] + 1, qu[r ++] = E[id].to;
        }
        return 0;
    }
    int DFS(int v, int flow)
    {
        if (v == t)
            return (flow);
        int Flow = 0;
        for (int i = P[v]; i < (int)Adj[v].size(); i++)
        {
            int id = Adj[v][i];
            if (E[id].flow && D[E[id].to] == D[v] + 1)
            {
                int flw = DFS(E[id].to, min(E[id].flow, flow));
                if (!flw)
                    swap(Adj[v][i], Adj[v][P[v]]), P[v] ++;
                Flow += flw; flow -= flw;
                E[id].flow -= flw;
                E[id^1].flow += flw;
                if (!flow) return Flow;
            }
            else
                swap(Adj[v][i], Adj[v][P[v]]), P[v] ++;
        }
        return Flow;
    }
    inline int MaxFlow()
    {
        int Flow = 0;
        while (BFS())
            Flow += DFS(s, INT_MAX);
        return Flow;
    }
};
int n, A[N * N], B[N];
bool M[N * N];
int main()
{
    scanf("%d", &n);
    Dinic < N * N + N * 2 + 2 > G;
    G.s = 0; G.t = n * n + 2 * n + 1;
    for (int i = 1; i <= n; i++)
        scanf("%d", &B[i]), M[B[i]] = 1;
    for (int i = 1; i <= n; i++)
    {
        int a = B[i];
        if (A[a])
            return !printf("No\n");
        A[a] = i;
        G.Add(G.s, n * n + i, i - 1);
        G.Add(G.s, n * n + n + i, n - i);
        for (int j = 1; j < a; j++)
            if (!M[j])
                G.Add(n * n + i, j, 1);
        for (int j = a + 1; j <= n * n; j++)
            if (!M[j])
                G.Add(n * n + n + i, j, 1);
    }
    for (int i = 1; i <= n * n; i++)
        if (!M[i])
            G.Add(i, G.t, 1);
    if (G.MaxFlow() < n * n - n)
        return !printf("No\n");
    printf("Yes\n");
    for (int i = 1; i <= n * n; i++)
    {
        if (!A[i])
            for (int &id : G.Adj[i])
                if (G.E[id].to != G.t && G.E[id].flow)
                    A[i] = (G.E[id].to - 1) % n + 1;
        printf("%d ", A[i]);
    }
    return 0;
}

