{
	int n;
	cin >> n;
	vector<pair<int, int> > v;
	for(int i = 1; i <= n; i++){
		int x;
		cin >> x;
		v.push_back(make_pair(x, i));
	}
	sort(v.begin(), v.end());
	if(v[0].first != v[0].second){
		cout << "No" << endl;
		return 0;
	}
	queue<pair<int, int> > qu;
	// rest : (i, 残りiをいれることができる数)のペアのキュー
	vector<int> ans;
	for(int i = 0; i < v[0].second; i++){
		ans.push_back(v[0].second);
	}
	if(v[0].second != n) qu.push(make_pair(v[0].second, n - v[0].second));
	for(int i = 1; i < v.size(); i++){
		int x = v[i].first;
		int num = v[i].second;
		if(ans.size() > x - num){
			cout << "No" << endl;
			return 0;
		}
		if(ans.size() == x - num){
			for(int j = 0; j < num; j++){
				ans.push_back(num);
			}
			if(num != n) qu.push(make_pair(num, n - num));
			continue;
		}
		while(!qu.empty()){
			int pushnum = (qu.front()).first;
			int cnt = (qu.front()).second;
			qu.pop();
			while(ans.size() < x - num && cnt > 0){
				ans.push_back(pushnum);
				cnt--;
			}
			if(cnt > 0){
				qu.push(make_pair(pushnum, cnt));
				break;
			}
		}
		if(ans.size() == x - num){
			for(int j = 0; j < num; j++){
				ans.push_back(num);
			}
		} else {
			cout << "No" << endl;
			return 0;
		}
		// cout << ans.size() << endl;
		if(num != n) qu.push(make_pair(num, n - num));
	}
	while(ans.size() < n * n){
		while(!qu.empty()){
			int pushnum = (qu.front()).first;
			int cnt = (qu.front()).second;
			qu.pop();
			for(int i = 0; i < cnt; i++){
				ans.push_back(pushnum);
			}
		}
	}
	cout << "Yes" << endl;
	for(int i = 0; i < n * n; i++){
		cout << ans[i];
		if(i == n * n - 1) cout << endl;
		else cout << " ";
	}
}

