const int N_ = 505;

int N;
int P[N_*N_];
int A[N_*N_];

priority_queue<int, vector<int>, greater<int> > pq;
bool used[N_*N_];

int get() {
	while(!pq.empty()) {
		int t = pq.top();
		if(!used[t]) {
			used[t] = true;
			return t;
		}
		pq.pop();
	}
	return N*N+1;
}

int C[N_];

int main() {
	scanf("%d", &N);
	for(int i = 1; i <= N; i++) {
		int x; scanf("%d", &x);
		P[x] = i;
	}

	for(int i = 1; i <= N*N; i++)
		pq.push(i);

	for(int x = 1; x <= N*N; x++) if(P[x] > 0) {
		int i = P[x]; // (i, x)
		for(int k = 1; k < i; k++) A[get()] = i;
		used[x] = true;
		A[x] = i;
	}

	for(int i = 1; i <= N; i++) {
		for(int k = i+1; k <= N; k++) A[get()] = i;
	}

	for(int x = 1; x <= N*N; x++) {
		int v = A[x];
		if(v == 0) return 0 & puts("No");
		if(++C[v] == v) {
			if(P[x] != v) return 0 & puts("No");
		}
	}
	for(int i = 1; i <= N; i++) {
		if(C[i] != N) return 0 & puts("No");
	}

	puts("Yes");
	for(int x = 1; x <= N*N; x++) printf("%d%c", A[x], (x+1 <= N*N) ? ' ' : '\n');

	return 0;
}

