		while(b[head].sum==0)head++;
		b[head].sum--;
		ans[i]=b[head].id;
	}
	for(int i=1;i<=n*n;i++){
		p[ans[i]]++;
		if(ans[i]==p[ans[i]]){
			if(a[ans[i]]!=i){
				printf("No\n");
				exit(0);
			}
		}
	}
	printf("Yes\n");
	for(int i=1;i<=n*n;i++)printf("%d ",ans[i]);
}

