signed main() {
	INIT;
	VAR(int, n);
	VEC(int, x, n);
	std::vector<PAIR> pv(n);
	REP(i, n) {
		pv[i] = PAIR(x[i], i);
	}
	std::sort(ALL(pv));
	std::vector<int> v(n*n, -1);
	std::vector<int> cnt(n, n);
	int pos = 0;
	REP(i, n) {
		auto p(pv[i]);
		if (v[p.first-1] != -1) NO;
		int rest = p.second;
		while (rest) {
			if (v[pos] == -1) {
				--rest;
				--cnt[i];
				v[pos] = p.second + 1;
			}
			++pos;
		}
