		v[p.first-1] = p.second + 1;
		--cnt[i];
	}
	pos = 0;
	REP(i, n) {
		while (cnt[i]) {
			while (v[pos] != -1) ++pos;
			v[pos] = i + 1;
			--cnt[i];
		}
	}
	OUT("Yes")BR;
	REP(i, n*n) {
		OUT(v[i])SP;
	}
	BR;
