template<class T, class U> void unique_min(vector<pair<T, U>> &a) {    vector<pair<T, U>> res;    if (sz(a))res.push_back(a[0]);    rep(i, 1, sz(a)) {        if (res.back().fi == a[i].fi) {            chmi(res.back().se, a[i].se);        }else {            res.push_back(a[i]);        }    }   swap(a, res);}
