	vector<int> ans(N*N,-1);
	vector<int> at(N+1,N);
	int pos = 0;
	for(int i=0;i<N;++i){
		int No = X[i][1];//対称の数
		int ter = X[i][0];//[ter-1]まででter個置く
		if( ans[ter-1] != -1 ){
			cout << "No" << endl;return;
		}
		ans[ter-1] = No;
		int nokori = No-1;
		for(;nokori && pos<ter-1;++pos){
			if( ans[pos] == -1 ){
				ans[pos] = No;
				--nokori;
				if( nokori == 0 ) break;
			}
		}
		if( nokori ){
			cout << "No" << endl;return;
		}
		at[No] -= No;//設置した数引く
	}
	//余ってる数を設置する。
	for(int i=0;i<N;++i){
		int No = X[i][1];//対称の数
