		if( pos < ter-1 ){//ter-1より前には置けない
			cout << "No" << endl;return;
		}
		for(;pos<N*N;++pos){
			if( at[No] == 0 ) break;
			if( ans[pos] == -1 ){
				ans[pos] = No;
				at[No]--;
			}
		}
		if( at[No] ){//
			cout << "No" << endl;return;
		}
	}
	cout << "Yes" << endl;
	for(int i=0;i<N*N;++i){
		if(i)cout << ' ';
		cout << ans[i];
	}cout << endl;
}
