            if (answer[cur] != -1) {
                cur++;
                cnt++;
                continue;
            }
            answer[cur] = pr.second;
            counts[pr.second]--;
            cur++;
        }

        if (cur > pr.first) {
            No();
        }
    }

    for (int i = 1; i <= n; i++) {
        while (counts[i]-->0) {
            if (answer[cur] == -1) {
                answer[cur] = i;
            } else {
                counts[i]++;
            }
            cur++;
        }
    }
    assert(cur = n * n + 1);

    Yes(answer);
}

