int n, x[500], a[500 * 500];
bool flag[501];
// int b[501];

bool solve() {
	inc(i, n) {
		if(a[ x[i] ] != 0) { return false; }
		a[ x[i] ] = i + 1;
	}

	inc(i, n * n) {
		if(a[i] != 0) {
			int j = 0, c = 0;
			while(j < i && c < a[i] - 1) {
				if(a[j] == 0) { a[j] = a[i]; c++; }
				j++;
			}
			if(c < a[i] - 1) { return false; }
		}
	}

	dec(i, n * n) {
		if(a[i] != 0 && ! flag[ a[i] ]) {
			int j = n * n - 1, c = 0;
			while(i < j && c < n - a[i]) {
				if(a[j] == 0) { a[j] = a[i]; c++; }
				j--;
			}
			if(c < n - a[i]) { return false; }

			flag[ a[i] ] = true;
		}
	}

	return true;
}

