#include <bits/stdc++.h>
using namespace std;
const int N = 505;
int n, sum, pt, num[N], p[N], ans[N * N], ex[N];
struct pr {
   	int x, i;
} a[N];
bool cmp (pr u, pr v) {return u.x < v.x;} 
struct pri {
	int i, x;
	pri () {}
	pri (int _i, int _x) :
		i(_i), x(_x) {}
	bool operator < (const pri &o) const {
		return p[i] - (i - num[i]) > p[o.i] - (o.i - num[o.i]);
	}
};
priority_queue <pri> q;
int main () {
	cin >> n, sum = 0;
	for (int i = 1; i <= n; ++i)
		cin >> a[i].x, p[i] = a[i].x, a[i].i = i, ans[a[i].x] = i;
	sort(a + 1, a + 1 + n, cmp);
	pt = n * n + 1;
	for (int i = 1; i <= n; ++i) q.push(pri(a[i].i, a[i].x));
	for (int i = 1; i <= n * n; ++i) {
		if (!ans[i]) {
			if (q.empty()) {pt = i; break;}
			pri t = q.top(); q.pop();
			while (p[t.i] < i && !q.empty()) t = q.top(), q.pop();
			if (p[t.i] < i && q.empty()) break;
			ans[i] = t.i, ++num[t.i];
			if (p[t.i] < i || num[t.i] == t.i - 1) continue;
			q.push(t);
		} else ++num[ans[i]];
	}
	for (int i = pt; i <= n * n; ++i) {
		if (ans[i]) {++num[ans[i]]; continue;}
		for (int j = 1; j <= n; ++j) {
			if (num[j] < n && p[j] < i) {ans[i] = j; ++num[j]; break;}
			if (num[j] < n - 1) {ans[i] = j; ++num[j]; break;}
		}
	}
	for (int i = 1; i <= n * n; ++i) ++ex[ans[i]];
	for (int i = 1; i <= n * n; ++i) if (ex[i] != n) return puts("No"), 0;
	for (int i = 1; i <= n; ++i) if (ans[p[i]] != i) return puts("No"), 0;
	puts("Yes");
	for (int i = 1; i <= n * n; ++i)
		printf("%d%c", ans[i], i < n * n ? ' ' : '\n');
	return 0;
}

