int N;
vector<int> solve() {
    vector<int> X(N);
    REP(i, N) cin >> X[i];
    REP(i, N) X[i]--;

    map<int, int> event;
    REP(i, N) event[ X[i] ] = i;

    REP(i, N) if (event[ X[i] ] != i) {
        return vector<int>(); // NG
    }

    typedef pair<int, int> P;
    priority_queue<P, vector<P>, greater<P>> before;
    REP(i, N) {
        if(i != 0) {
            before.push(P(X[i], i));
        }
    }

    queue<int> after;
    vector<int> count(N);

    vector<int> answer;
    auto insert = [&](int x) {
        //cout << "insert " << x+1 << endl;
        answer.push_back(x+1);
        count[x]++;
    };

    REP(i, N * N) {
        //cout << i << endl;
        if(event.count(i)) {
            //cout << "event" << event[i] << endl;
            const int x = event[i];
            if(count[x] != x) {
                //cout << "count " << x << " " << count[x] << " is not " << x << endl;
                return vector<int>(); // NG
            }
            insert(x);
            REP(_, N - count[x]) {
                after.push(x);
            }
        } else {
            if(before.empty()) {
                if(after.empty()) {
                    cout << "before and after" << endl;
                    return vector<int>(); // NG
                } else {
                    int x = after.front(); after.pop();
                    insert(x);
                }
            } else {
                auto p = before.top();
                int x = p.second;
                insert(x);
                if(count[x] < x) {
                    // remain
                } else {
                    before.pop();
                }
            }
        }
    }

    return answer;
}

