inline void next_t() {
    while (timer < n * n && ans[timer])
        timer++;
}

inline void prev_t() {
    while (timer >= 0 && ans[timer])
        timer--;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
