        for (int j = 0; j < i; j++) {
            next_t();
            if (timer > A[i])
                assert(0);
            ans[timer] = i + 1;
        }
    }
    timer = n * n - 1;
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n - 1; j++) {
            prev_t();
            if (timer < A[i])
                assert(0);
            ans[timer] = i + 1;
        }
    }
    cout << "Yes" << endl;
    for (int i = 0; i < n * n; i++) {
        cout << ans[i] << sep;
    }
    cout << endl;
