const int N = 505;

int ret[N*N];
int x[N],cc[N];
void solve() {
    int n;
    scanf("%d",&n);
    vector<pair<int,int> > in;
    queue<pair<int,int> >q;
    for(int i=1;i<=n;++i) {
        scanf("%d",&x[i]);
        ret[x[i]] = i;
        cc[i] = i-1;
        in.push_back(make_pair(x[i],i));
        q.push(make_pair(cc[i],i));
    }
    sort(in.begin(),in.end());
    int pos = 1;
    for(int i=0;i<in.size();++i) {
        int lim = in[i].first, id = in[i].second;
        int rem = id-1;
        while(pos<lim && rem>0) {
            if(ret[pos]!=0) {
                ++pos;
            }
            ret[pos] = id;
            --rem;
        }
        if(rem!=0) {
            printf("No\n");
            return;
        }
    }
    printf("Yes\n");
    for(int i=1;i<=n*n;++i) {
        if(ret[i]==0) {
            while(!q.empty()) {
                if(q.front().first==0) {
                    q.pop();
                } else {
                    break;
                }
            }
            pair<int,int> tmp = q.front();
            ret[i] = tmp.second;
            tmp.first--;
            if(tmp.first!=0) {
                q.push(tmp);
            }
        }
        printf("%d ",ret[i]);
    }
}

