int main(void) {
	int N, x;
	int ans[500*500+1] = {0};
	vector <pair <int, int> > pairs;

	cin >> N;
	int min = 0, max = 0;

	for (int i = 1; i <= N; i++) {
		cin >> x;
		ans[x] = i;
		pairs.push_back(make_pair(i, x));
	}
	std::sort(pairs.begin(), pairs.end(), vecsort);

	int pos = 1;
	for (int i = 0; i < pairs.size(); i++) {
		int num = pairs.at(i).first;
		int left = num - 1;
		while (left > 0) {
			if (ans[pos] == 0) {
				ans[pos] = num;
				left--;
			}
			pos++;
		}
	}
	pos = N*N;
	for (int i = pairs.size()-1; i >= 0; i--) {
		int num = pairs.at(i).first;
		int left = N - num;
		while (left > 0) {
			if (ans[pos] == 0) {
				ans[pos] = num;
				left--;
			}
			pos--;
		}
	}

	// check
	vector <int> numpos[501];
	for (int num = 1; num <= N; num++) numpos[num].push_back(0);
	for (int i = 1; i <= N*N; i++) numpos[ans[i]].push_back(i);

	bool good = true;
	for (int i = 0; i < N; i++) {
		int num = pairs.at(i).first;
		if (numpos[num].at(num) != pairs.at(i).second) good = false;
	}
	if (good) {
		cout << "Yes" << endl;
		for (int i = 1; i <= N*N; i++) {
			if (1 < i) cout << " ";
			cout << ans[i];
		}
	} else {
		cout << "No" << endl;
	}

	return 0;
}

