void solve() {
	int n; cin >> n;
    vector<int> x(n);
    vector<P> ins(n);
    set<int> se;
    rep(i, n) {
        cin >> x[i];
        se.insert(x[i] - 1);
        ins[i] = make_pair(x[i], i + 1);
    }
    sort(all(ins));
    vector<int> ans(n * n, -1);
    int j = 0;
    rep(i, n) {
        int p = ins[i].fr;
        --p;
        int num = ins[i].sc;
        for(int k = j, cnt = 0; cnt < num - 1;) {
            if(k >= n * n) {
                cout << "No" << endl;
                return;
            }
            if(ans[k] != -1 || se.find(k) != se.end()) {
                ++k;
                continue;
            } else {
                ans[k] = num;
                ++k; ++cnt;
                if(cnt == num - 1) {
                    j = k;
                }
            }
        }
        if(ans[p] != -1) {
            cout << "No" << endl;
            return;
        }
        ans[p] = num;
    }
    j = 0;
    for(int i = 1; i <= n; ++i) {
        for(int k = j, cnt = 0; cnt < n - i;) {
            if(k >= n * n) {
                cout << "No" << endl;
                return;
            }
            if(ans[k] != -1 || k < x[i - 1] - 1) {
                ++k;
                continue;
            } else {
                ans[k] = i;
                ++k; ++cnt;
                if(cnt == n - i) j = k;
            }
        }
    }
    cout << "Yes" << endl;
    rep(i, n * n) {
        cout << ans[i] << " ";
    }
    cout << endl;
}

