#define REP(i,n) for(auto i = 0 * (n), i##_len = (n); i < i##_len; ++i)
#define ALL(c) (c).begin(), (c).end()
#define FOR(i,s,n) for(ll i=s, i##_len=(ll)(n); i<i##_len; ++i)
#define TEN(x) ((ll)1e##x)
const ll mod = TEN(9) + 7;

int main() {
#ifdef INPUT_FROM_FILE
	ifstream cin("sample.in");
	ofstream cout("sample.out");
#endif
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(50);
	ll n; cin >> n;
	vl x(n); REP(i, n) cin >> x[i];

	vl add(n * n + 1, 0);
	REP(i, n) add[x[i]] += i + 1;
	FOR(i, 1, n * n + 1) add[i] += add[i - 1];
	REP(i, n * n + 1) if (i < add[i]) {
		cout << "No" << endl;
		return 0;
	}

	vl add_rev(n * n + 1, 0);
	REP(i, n) add_rev[x[i]] += n - (i + 1);
	for (ll i = n * n - 1; i > 0; --i) add_rev[i] += add_rev[i + 1];
	FOR(i, 1, n * n + 1) if (n * n - i + 1 < add_rev[i]) {
		cout << "No!!" << endl;
		return 0;
	}

	vl y(n * n + 1, -1); REP(i, n) y[x[i]] = i + 1;
	using P = tuple<ll, ll, ll>;
	priority_queue<P, vector<P>, greater<P>> que;
	FOR(i, 1, n) que.push(P{ x[i] - (i + 1), i + 1, i }); // x[i] までに i 個消費する必要がある
	FOR(i, 1, n * n + 1) {
		if (y[i] != -1) {
			if ((n * n - i) - (n - y[i]) != 0) {
				// n * n以内にn - y[i]個消費する必要がある
				que.push(P{ (n * n - i) - (n - y[i]), y[i], n - y[i] });
			}
		} else if (!que.empty()) {
			auto p = que.top(); que.pop();
			y[i] = get<1>(p);
			get<2>(p)--;
			get<0>(p)++;
			if (get<2>(p) != 0) que.push(p);
		} else {
			cout << "No!" << endl;
			return 0;
		}
	}

	cout << "Yes" << endl;
	FOR(i, 1, n * n + 1) cout << y[i] << " ";
	cout << endl;

	return 0;
}

