	for (int i = 0; i < n; i++) cin >> x[i], x[i]--;
	vector<pair<int, int> > z(n);
	for (int i = 0; i < n; i++) z[i] = make_pair(x[i], i + 1);
	sort(z.begin(), z.end());
	vector<int> xinv(n);
	for (int i = 0; i < n; i++) xinv[i] = z[i].second;
	vector<int> a(n * n, -1);
	for (int i = 0; i < n; i++) a[x[i]] = i + 1;
	int pos = 0;
	for (int i = 0; i < n; i++) {
		for (int cnt = 0; cnt < xinv[i] - 1 && pos < n * n;) {
			if (a[pos] == -1) a[pos] = xinv[i], cnt++;
			pos++;
		}
	}
	int revpos = n * n - 1;
	for (int i = n - 1; i >= 0; i--) {
		for (int cnt = n - 1; cnt > xinv[i] - 1 && revpos >= 0;) {
			if (a[revpos] == -1) a[revpos] = xinv[i], cnt--;
			revpos--;
		}
	}
	vector<vector<int> > v(n);
