typedef priority_queue<P, vector<P>, greater<P> > PQ_ASK;

struct E {
    int i, place, count;

    E(int i, int place, int count) : i(i), place(place), count(count) {};
};


int main() {
    int n;
    cin >> n;

    vector<int> v(n);
    rep(i, n) cin >> v[i];
    for (int &i : v) i--;

    vector<int> tmp(n * n, -1);
    rep(i, n) tmp[v[i]] = i;


    auto st = [](E &e1, E &e2) {
        return e1.place < e2.place;
    };
    auto gt = [&](E &e1, E &e2) {
        return e1.place > e2.place;
    };

    priority_queue<E, vector<E>, decltype(gt)> l(gt);
    rep(i, n) if (i > 0) l.emplace(i, v[i], i);

    priority_queue<E, vector<E>, decltype(st)> r(st);
    rep(i, n - 1) r.emplace(i, v[i], n - 1 - i);


    rep(i, n * n) {
        if (tmp[i] != -1) continue;
        if (l.empty()) continue;

        E t = l.top();
        l.pop();
        tmp[i] = t.i;
        int count = t.count - 1;
        if (count == 0) continue;
        l.emplace(t.i, t.place, count);
    }


    for (int i = n * n - 1; i >= 0; i--) {
        if (tmp[i] != -1) continue;
        if (r.empty()) continue;

        E t = r.top();
        r.pop();
        tmp[i] = t.i;
        int count = t.count - 1;
        if (count == 0) continue;
        r.emplace(t.i, t.place, count);
    }


    vector<int> s(n, -1), ct(n * n, -1);
    rep(i, n * n) {
        s[tmp[i]]++;
        ct[i] = s[tmp[i]];
    }

    rep(i, n) {
        int j = v[i];
        if (ct[j] != i) {
            cout << "No" << endl;
            ret();
        }
    }

    cout << "Yes" << endl;
    rep(i, n * n) cout << tmp[i] + 1 << endl;

}

