			for(int j = 0; j < num; j++){
				ans.push_back(num);
			}
			if(num != n) qu.push(make_pair(num, n - num));
			continue;
		}
		while(!qu.empty()){
			int pushnum = (qu.front()).first;
			int cnt = (qu.front()).second;
			qu.pop();
			while(ans.size() < x - num && cnt > 0){
				ans.push_back(pushnum);
				cnt--;
			}
			if(cnt > 0){
				qu.push(make_pair(pushnum, cnt));
