	}
	while(ans.size() < n * n){
		while(!qu.empty()){
			int pushnum = (qu.front()).first;
			int cnt = (qu.front()).second;
			qu.pop();
			for(int i = 0; i < cnt; i++){
				ans.push_back(pushnum);
			}
		}
	}
	cout << "Yes" << endl;
	for(int i = 0; i < n * n; i++){
		cout << ans[i];
		if(i == n * n - 1) cout << endl;
		else cout << " ";
	}
}

