		for(int j = 0; j < i; ++j){ pq.emplace(x[i], i); }
	}
	bool accept = true;
	for(int i = 0; i < n * n; ++i){
		if(b[i] >= 0){
			if(done[b[i]] != b[i]){
				accept = false;
				break;
			}
			a[i] = b[i];
			for(int j = b[i] + 1; j < n; ++j){
				pq.emplace(n * n, b[i]);
			}
		}else{
			if(pq.empty()){
				accept = false;
				break;
			}
			const auto t = pq.top();
			pq.pop();
			a[i] = t.second;
			++done[t.second];
		}
	}
	if(!accept){
		cout << "No" << endl;
	}else{
		cout << "Yes" << endl;
		for(int i = 0; i < n * n; ++i){
			cout << a[i] + 1 << " ";
		}
		cout << endl;
	}
	return 0;
}

