bool build(vector<int> &vec, vector<queue<int> > & l, vector<queue<int> > & r){
  int li=0, ri=0;
  while(li<l.size() && l[li].size()==0) li++;
  while(ri<r.size() && r[ri].size()==0) ri++;

  int blk=0;
  rep(i,vec.size()){
    if(vec[i]!=-INF){
      if(l[blk].size()>0) return false;
      blk++;
    } else {
      if(li == l.size()){
        // rからとる
        if(ri > blk) return false;
        vec[i] = r[ri].front(); r[ri].pop();
        while(ri<r.size() && r[ri].size()==0) ri++;
      } else {
        // lからとる
        vec[i] = l[li].front(); l[li].pop();
        while(li<l.size() && l[li].size()==0) li++;
      }
    }
  }
  return true;
}

int main(){
  int n;
  cin>>n;
  vector<int> vec(n);
  vector<int> res(n*n, -INF);
  rep(i,n) scanf("%d", &vec[i]);
  rep(i,n){ vec[i]--; res[vec[i]]=i+1;}

  vector<int> sorted(vec);
  sort(all(sorted));

  vector<queue<int> > l(n+1, queue<int>()); // これよりも左にならいける集合
  vector<queue<int> > r(n+1, queue<int>()); // 右にならいける集合

  rep(i,n){
    int idx = lower_bound(all(sorted), vec[i]) - sorted.begin();
    rep(j,i) l[idx].push(i+1);
    repl(j,i+1,n) r[idx+1].push(i+1);
  }

  if(build(res, l, r)){
    cout << "Yes" << endl;
    rep(i,n*n) printf("%d%c", res[i], " \n"[i==n*n-1]);
  } else {
    cout << "No" << endl;
  }


  return 0;
}

