    int N;
    cin >> N;
    vector<int> x(N);
    vector<int> ans(N * N, -1);
    bool ok = true;
    for (int i = 0; i < N; i++) {
        cin >> x[i];
        x[i]--;
        ans[x[i]] = i;
    }
    for (int i = 0; i < N; i++) {
        int left = i;
        for (int j = x[i] - 1; j >= 0 and left > 0; j--) {
            if (ans[j] == -1) {
                ans[j] = i;
                left--;
            }
        }
        if (left > 0) {
            ok = false;
            break;
        }
        left = N - 1 - i;
        for (int j = N * N - 1; j > x[i] and left > 0; j--) {
            if (ans[j] == -1) {
                ans[j] = i;
                left--;
            }
        }
        if (left > 0) {
            ok = false;
            break;
        }
    }
    if (ok) {
        cout << "Yes" << endl;
        for (int i = 0; i < N * N; i++) {
            if (i != 0) {
                cout << " ";
            }
            cout << ans[i] + 1;
        }
        cout << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

