	for (int i = 1, t; i <= n; ++i) {
		std::cin >> t;
		for (int j = 1; j < i; ++j) add[1].emplace_back(t - 1, i);
		add[t].emplace_back(t, i);
		for (int j = i + 1; j <= n; ++j) add[j].emplace_back(n * n, i);
	}
	for (int i = 1; i <= n * n; ++i) {
		for (auto t : add[i]) q.push(t);
		if (q.empty() || q.top().first < i)
			return std::cout << "No" << std::endl, 0;
