				if (cnt == a[i].se - 1) break;
			}
			++pos;
		}

		if (cnt < a[i].se - 1) Exit();
	}

	pos = n * n;
	for (int i = n; i; --i) {
		cnt = 0;
		if (a[i].se == n) continue;
		while (pos >= a[i].fi) {
			if (!num[pos]) {
				num[pos] = a[i].se, ++cnt;
				if (cnt == n - a[i].se) break;
			}
			--pos;
		}

		if (cnt < n - a[i].se) Exit();
	}

	puts("Yes");
	for (int i = 1; i < n * n; ++i)
		printf("%d ", num[i]);
	printf("%d\n", num[n * n]);
	return 0;
}

