		A[X[i]] = i;
		REP(k, 0, i) QL.push(make_pair(-(X[i] - 1), i));
		REP(k, 0, N - i - 1) QR.push(make_pair(X[i] + 1, i));
	}
	REP(i, 0, N * N) {
		if (A[i] == -1) {
			if (QL.empty()) break;
			auto p = QL.top(); QL.pop();
			if (i > -(p.first)) return -1;
