    }
};

int main() {
    int N; cin >> N;
    vector<int> X(N+1);
    for(int i=1; i<=N; i++) cin >> X[i];
    vector<int> pool;

    // black, blue
    priority_queue<Elem> que;
    for(int i=1; i<=N; i++) {
        int black = X[i], blue = i;
        que.emplace(black, blue, i);
    }

    vector<int> ans;
    for(int t=0; que.size(); t++) {
        Elem cur = que.top(); que.pop();
        int black = cur.black - t, blue = cur.blue, id = cur.id;
