                que.emplace(cur.black, blue - 1, id);
            }
            else {
                for(int i=0; i<N-id; i++) pool.emplace_back(id);
            }
        }
        else {
            if(pool.empty()) break;
            ans.emplace_back(pool.back());
            pool.pop_back();

