int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;cin >> n;
	vector<pii> x(n);
	rep(i,n){
		cin >> x.at(i).first;
		x.at(i).second=i;
	}
	vector<int> ans(n*n),a(n),b(n);
	vector<bool> c(n);
	rep(i,n){
		a.at(i)=n-1-i;
		b.at(i)=n-1;
	}
	rep(i,n) ans.at(x.at(i).first-1)=i+1;
	sort(x.rbegin(),x.rend());
	int j=0,k=0;
	bool flg=true,flg1=false;
	for(int i=n*n-1;i>=0;--i){
		if(ans.at(i)){
			c.at(ans.at(i)-1)=true;
			if(a.at(ans.at(i)-1)>0){
				flg=false;
				break;
			}
			continue;
		}
		if(flg1){
			bool flg2=true;
			rep(i,n){
				if(c.at(i) && b.at(i)){
					k=i;
					flg2=false;
					break;
				}
			}
			if(flg2){
				flg=false;
				break;
			}
			ans.at(i)=k+1;
			b.at(k)--;
		}
		else{
			while(a.at(x.at(j).second)==0){
				j++;
				if(j==n) break;
			}
			if(j==n){
				flg1=true;
				while(b.at(k)==0) k++;
