			}
			ans.at(i)=x.at(j).second+1;
			a.at(x.at(j).second)--;
			b.at(x.at(j).second)--;
		}
	}
	if(flg){
		cout << "Yes" << endl;
		rep(i,n*n){
			if(i==n*n-1) cout << ans.at(i) << endl;
			else cout << ans.at(i) << " ";
		}
