int main()
{
    int n;
    cin >> n;
    vector<P> x(n);
    for(int i = 0; i < n; i++)
    {
        int a;
        cin >> a;
        x[i] = P(a, i+1);
    }
    sort(x.begin(), x.end());

    int pos = 0;
    set<int> s;
    for(int i = 1; i <= n*n; i++)
    {
        s.insert(i);
    }

    vector<int> ans(n*n+1);
    for(int i = 0; i < n; i++)
    {
        P p = x[i];
        int now = p.first;
        int num = p.second;
        if(pos >= now)
        {
            cout << "No" << endl;
            return 0;
        }
        int l = num-1;
        int r = n-num;
        pos = now + r;
        while(l--)
        {
            int tmp = *s.begin();
            if(tmp >= now)
            {
                cout << "No" << endl;
                return 0;
            }
            ans[tmp] = num;
            s.erase(tmp);
        }
        r++;
        while(r--)
        {
            if(now+r > n*n)
            {
                cout << "No" << endl;
                return 0;
            }
            ans[now+r] = num;
            s.erase(now+r);
        }
    }
    cout << "Yes" << endl;
    for(int i = 1; i <= n*n; i++)
    {
        cout << ans[i] << " ";
    }
