        x--;
        if (i == 0) wait_que.push(Query{0, i, x, i});
        else que.push(Query{0, i, x, i});
        a[x] = i;
    }

    const int INF = 10000000;

    rep(i, n * n) {
        if (a[i] != -1) continue;

        while (!wait_que.empty() && wait_que.top().limit < i) {
            Query q = wait_que.top(); wait_que.pop();
            q.limit = INF;
            q.max_cnt = n - 1;
            que.push(q);
        }

        while (!que.empty() && (que.top().limit < i || que.top().max_cnt == que.top().cnt)) {
            wait_que.push(que.top());
            que.pop();
        }

        if (que.empty()) {
            cout << "No" << endl;
            return 0;
        }

        Query q = que.top(); que.pop();
        assert(q.cnt < q.max_cnt);
        //cout << q.cnt << " " << q.max_cnt << " " << q.num << endl;
        a[i] = q.num;
        q.cnt++;
        if (q.cnt < q.max_cnt) que.push(q);
        else if (q.max_cnt == q.cnt && q.max_cnt != n - 1) wait_que.push(q);
    }

    cout << "Yes" << endl;
    rep(i, n * n) cout << a[i] + 1 << " ";
    cout << endl;
}

