int read() {
  if (scanf("%d", &n) < 1) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%d", &x[i]);
    x[i]--;
  }
  return true;
}

pair<int, int> ev[maxn];

void solve() {
  for (int i = 0; i < n * n; i++) {
    a[i] = -1;
  }
  for (int i = 0; i < n; i++) {
    ev[i] = make_pair(x[i], i);
  }
  sort(ev, ev + n);
  for (int i = 0, pos = 0; i < n; i++) {
    int p = ev[i].first, id = ev[i].second;
    a[p] = id;
    int cnt = id;
    while (cnt) {
      while (pos < p && a[pos] != -1) {
        pos++;
      }
      if (pos == p) {
        printf("No\n");
        return;
      }
      a[pos] = id;
      cnt--;
    }
  }
  for (int i = n - 1, pos = n * n - 1; i >= 0; i--) {
    int p = ev[i].first, id = ev[i].second;
    int cnt = n - id - 1;
    while (cnt) {
      while (pos > p && a[pos] != -1) {
        pos--;
      }
      if (pos == p) {
        printf("No\n");
        return;
      }
      a[pos] = id;
      cnt--;
    }
  }
  printf("Yes\n");
  for (int i = 0; i < n * n; i++) {
    printf("%d ", a[i] + 1);
  }
  printf("\n");
}

