#include <bits/stdc++.h>
using namespace std;

const int N = 505;

const int M = N*N;
int x[N];

int rem[N];

int color[N];

int ret[N];

void solve(){
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;++i){
		scanf("%d",&x[i]);
		rem[i] = i-1;
		color[x[i]] = i;
	}
	queue<int> free;
	set<pair<int,int> > s;
	for(int i=1;i<=n;++i){
		s.insert(make_pair(x[i]- rem[i],i));
	}
	for(int i=1;i<=n*n;++i){
		while(!s.empty()){
			int ind = (*s.begin()).second;
			if(rem[ind]==0){
				s.erase(s.begin());
				continue;
			} else {
				break;
			}
		}

		bool canDoit = false;
		int curColor;
		if(color[i]!=0){
			int c = color[i];
			if(rem[c]!=0){
				printf("No\n");
				return;
			}
			for(int j=0;j<n-c;++j){
				free.push(c);
			}
			ret[i] = c;
			continue;
		}
		if(!s.empty()){
			int ind = (*s.begin()).second;
			--rem[ind];
			s.insert(make_pair(x[ind]-rem[ind],ind));
			canDoit = true;
			curColor = ind;
		} else if(!free.empty()){
			int c = free.front();
			free.pop();
			canDoit = true;
			curColor = c;
		}
		if(canDoit){
			ret[i]  = curColor;
		} else {
			printf("No\n");
			return;
		}
	}
	printf("Yes\n");
	for(int i=1;i<=n*n;++i){
		printf("%d ",ret[i]);
	}
	putchar('\n');
}
int main(){
	//freopen("input.txt","r",stdin);
	solve();
}

