int n;
int pos[505];;
int ans[250004];

struct Num {
	int num, pos, left;
	Num(int _num, int _pos, int _left) {
		num = _num;
		pos = _pos;
		left = _left;
	}
	Num() {}
};

bool operator<(Num A, Num B) {
	return  (A.pos > B.pos);
}

priority_queue<Num> PQ;
queue<Num> Q;
int remaining[505];

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &pos[i]);
		ans[pos[i]] = i;
		PQ.push(Num(i, pos[i], i - 1));
		remaining[i] = i - 1;
	}

	for (int i = 1; i <= n * n; i++) {
		if (ans[i] != 0) {
			if (remaining[ans[i]]) {
				printf("No\n");
				return 0;
			}
			Q.push(Num(ans[i], 0, n - ans[i]));
			continue;
		}

		while (!PQ.empty()) {
			if (PQ.top().left == 0) PQ.pop();
			else break;
		}

		if (PQ.empty()) {
			while (!Q.empty()) {
				Num u = Q.front();
				Q.pop();
				if (u.left == 0) {
					continue;
				}
				ans[i] = u.num;
				u.left--;
				Q.push(u);
				break;

			}
			if (ans[i] == 0) {
				printf("No\n");
				return 0;
			}
			continue;
		}

		while (!PQ.empty()) {
			Num u = PQ.top();
			PQ.pop();
			if (u.left == 0) {
				continue;
			}
			ans[i] = u.num;
			remaining[u.num]--;
			u.left--;
			PQ.push(u);
			break;
		}
		if (ans[i] == 0) {
			printf("No\n");
			return 0;
		}
	}

	printf("Yes\n");
	for (int i = 1; i <= n * n; i++) {
		if (i > 1) printf(" ");
		printf("%d", ans[i]);
	}
	printf("\n");
	return 0;
}

