const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(2e5) + 17;

int n;
int p[MAXN], ans[MAXN];

bool read() {
    if (!(cin >> n))
        return false;

    forn (i, n)
        cin >> p[i + 1];

    return true;
}

void solve() {
    forn (i, n)
        forn (j, n)
            if (i != j && p[i + 1] == p[j + 1]) {
                cout << "No\n";
                return ;
            }

    vector< pair<int, int> > vec;

    forn (i, n)
        vec.pb(mp(p[i + 1], i + 1));

    sort(vec.begin(), vec.end());
    set<int> f, vac;

    forn (i, n * n)
        f.insert(i + 1);

    for (auto x : vec) {
        f.erase(x.f);
        ans[x.f] = x.s;
    }

    for (auto x : vec) {
        int cnt = x.s - 1;

        for (; cnt > 0 && !f.empty() && *f.begin() < x.f; --cnt, f.erase(f.begin()))
            ans[*f.begin()] = x.s;

        for (; cnt > 0 && !vac.empty() && *vac.begin() < x.f; --cnt) {
            ans[*f.begin()] = ans[*vac.begin()];
            ans[*vac.begin()] = x.s;
            vac.erase(vac.begin());
            vac.insert(*f.begin());
            f.erase(f.begin());
        }

        if (cnt > 0) {
            cout << "No\n";
            return ;
        }

        cnt = n - x.s;

        for (; cnt > 0 && f.upper_bound(x.f) != f.end(); --cnt) {
            auto it = f.upper_bound(x.f);
            vac.insert(*it);
            ans[*it] = x.s;
            f.erase(it);
        }

        if (cnt > 0) {
            cout << "No\n";
            return ;
        }
    }

    cout << "Yes\n";

    forn (i, n * n)
        cout << ans[i + 1] << ' ';

    cout << endl;
}

