	int N, x;
	int ans[500*500+1] = {0};
	int used[500+1] = {0};

	cin >> N;
	int min = 0, max = 0;

	for (int i = 1; i <= N; i++) {
		cin >> x;
		min += i, max += i;
		if (x < min || max < x) {
			cout << "No" << endl;  // error
			return 0;
		}
		max += (N-i);
		ans[x] = i;
		used[i]++;
	}

	int n = 1;
	for (int i = 1; i <= N*N; i++) {
		while (ans[i] == 0) {
			if (used[n] < N) {
				ans[i] = n;
				used[n]++;
			} else {
				n++;
			}
		}
		cout << ans[i];
		if (i < N*N) cout << " ";
	}
	cout << endl;
	return 0;
}

