  int result[N*N];
  int count[N] = {};
  rep(i,pow(N,2)) {
    if (pos[ipos].second==i) {
      if (pos[ipos].first==count[pos[ipos].first]) {
        result[i] = pos[ipos].first+1;
        count[pos[ipos].first]++;
        ipos++;
      }
      else {
        cout << "No" << endl;
        return 0;
      }
    }
    else {
      result[i] = part.front()+1;
      count[part.front()]++;
      part.pop();
    }
  }
  cout << "Yes" << endl;
  rep(i,pow(N,2)) cout << result[i] << " "; cout << endl;
  return 0;
}

