typedef long long ll;
typedef pair<int, int> Pii;

const int N_MAX = 500;

vector<Pii> v(N_MAX+1, Pii(0, 0));

vector<int> construct(int n) {
    vector<int> ret(n*n+1, 0);
    sort(v.begin(), v.begin()+n+1);
    int i = 1;
    for(int j=1;j<=n;++j) {
        int idx = v[j].first;
        int num = v[j].second;
        ret[idx] = num;
        for(int k=1;k<num;++k) {
            while(i <= idx && ret[i]) ++i;
            if(i > idx) return ret;
            ret[i] = num;
        }
        for(int k=1;k<=n*n;++k) {
            cerr << ret[k] << " ";
        }
        cerr << endl;
    }

    for(int j=1;j<=n;++j) {
        int num = v[j].second;
        int i = v[j].first + 1;
        for(int k=0;k<n-num;++k) {
            while(i <= n*n && ret[i]) ++i;
            if(i > n*n) return ret;
            ret[i] = num;
        }
    }
    ret[0] = 1;
    return ret;
}

int main() {
    int n, x;
    cin >> n;
    for(int i=1;i<=n;++i){
        cin >> x;
        v[i] = {x, i};
    }

    vector<int> ans = construct(n);

    if(ans[0]) {
        cout << "Yes" << endl;
        for(int i=1;i<=n*n;++i) {
            cout << ans[i] << " ";
        }
        cout << endl;
    } else {
        cout << "No" << endl;
    }

}

