  vector<int> xs(n + 1);
  for(int i = 1; i <= n; i++)
  {
	cin >> xs[i];
	xs[i]--;
  }

  vector<int> stack;
  for(int i = 2; i <= n; i++)
  {
	for(int j = 0; j < i - 1; j++)
	{
	  stack.push_back(i);
	}
  }

  vector<int> ans;
  bool success = true;
  for(int i = 1; i <= n; i++)
  {
	if(ans.size() > xs[i])
	{
	  success = false;
	  break;
	}
	for(int j = ans.size(); j < xs[i]; j++)
	{
	  if(stack.empty())
	  {
		success = false;
		break;
	  }
	  ans.push_back(stack.back());
	  stack.pop_back();
	}
	ans.push_back(i);
	for(int j = 0; j < n - i; j++)
	{
	  stack.push_back(i);
	}
  }

  if(success)
  {
	for(auto v : stack)
	{
	  ans.push_back(v);
	}
  }

  if(success)
  {
	cout << "Yes" << endl;
	for(int i = 0; i < n * n; i++)
	{
