int n;
int x[500];
vector<int> limits_upper;	//limits_upper[i]かそれより後に置く条件
vector<P> limits;			//limits[i].firstかそれより前に置く条件

int main() {
	int i, j;

	cin >> n;
	for (i = 0; i < n; i++) { cin >> x[i]; x[i]--; }

	for (i = 0; i < n; i++) {
		for (j = 0; j <= i; j++) {
			limits_upper.push_back(x[i] - i + j);
		}
	}
	sort(limits_upper.begin(), limits_upper.end(), greater<int>());

	int puyo = n * n - 1;
	for (i = 0; i < limits_upper.size(); i++) {
		if (puyo < limits_upper[i]) { cout << "No" << endl; return 0; }
		puyo--;
	}

	for (i = 0; i < n; i++) {
		for (j = 0; j <= i; j++) {
			limits.push_back(P(x[i] - j, i));
		}
	}
	sort(limits.begin(), limits.end());

	int poyo = 0;
	for (i = 0; i < limits.size(); i++) {
		if (limits[i].first < poyo) { cout << "No" << endl; return 0; }
		poyo++;
	}

	cout << "Yes" << endl;

	static int ans[250000] = {0};
	static int cnt[500];
	for (i = 0; i < n; i++) {
		cnt[i] = n;
	}
	for (i = 0; i < limits.size(); i++) {
		ans[limits[i].first] = limits[i].second + 1;
		cnt[limits[i].second]--;
	}

	for (i = 0; i < n * n; i++) {
		if (ans[i] != 0) continue;
		for (j = 0; j < n; j++) {
			if (cnt[j] > 0) {
				cnt[j]--;
				ans[i] = j + 1;
				break;
			}
		}
	}

	for (i = 0; i < n * n; i++) {
		cout << ans[i];
		if (i + 1 < n * n) cout << " ";
	}
	cout << endl;
	return 0;
}

