int main() {
    int N;
    cin >> N;
    vector<int> X(N);
    rep(i, N) cin >> X[i];

    vector<pair<int, int>> xn(N);
    rep(i, N) xn[i] = { X[i], i };
    sort(all(xn));

    vector<pair<int, int>> task(N);
    rep(i, N) task[i] = { xn[i].second + 1, xn[i].second };

    int k = 0;
    queue<pair<int, int>> res, free;
    vector<int> ans;
    for (int i = 0; i < N * N; ) {
        if (!res.empty() && res.front().second == i + 1) {
            ans.push_back(res.front().first);
            i++;
            free.emplace(res.front().first, N - res.front().first);
            res.pop();
        }
        else if (!res.empty() && res.front().second < i + 1) {
            break;
        }
        else if (k < N) {
            if (task[k].second == 0) {
                res.emplace(task[k].first, X[task[k].first - 1]);
                k++;
                continue;
            }
            else {
                ans.push_back(task[k].first);
                i++;
                task[k].second--;
            }
        }
        else if (!free.empty()) {
            while (free.front().second == 0) free.pop();
            ans.push_back(free.front().first);
            i++;
            free.front().second--;
        }
        else {
            break;
        }
    }

    if (ans.size() == N * N) {
        write("Yes");
        rep(i, N * N) cout << ans[i] << (i == N * N - 1 ? '\n' : ' ');
    }
    else write("No");
}

