bool solve() {
	inc(i, n) {
		if(a[ x[i] ] != 0) { return false; }
		a[ x[i] ] = i + 1;
	}

	inc(i, n * n) {
		if(a[i] != 0) {
			int j = 0, c = 0;
			while(j < i && c < a[i] - 1) {
				if(a[j] == 0) { a[j] = a[i]; c++; }
				j++;
			}
			if(c < a[i] - 1) { return false; }
		}
	}

	inc(i, n * n) { b[ a[i] ]++; }

	int i = 0, j = 1;
	while(true) {
		while(a[i] != 0) { i++; }
		while(b[j] == n) { j++; }
		if(i == n * n) { break; }

		a[i] = j; b[j]++;
		i++;
	}

	return true;
}

