#define MAXN 500
int a[MAXN*MAXN+10],d[MAXN+10];
void solve(long long N, vector<long long> x){
	for(int i=0; i<N; ++i) {
		a[x[i]]=i+1;
		d[i+1]=i;
	}	
	sort(d+1,d+1+N,[&](int a,int b){return x[a]<x[b];});
	int p=1;
	for(int i=1; i<=N; ++i) {
		int now=d[i];
		for(int j=1; j<=now; ++j) {
			while(a[p]>0) ++p;
			if (p>x[now]) throw now;
			a[p]=now+1;
		}
	}
	//puts("Yes");
	while(a[p]>0) ++p;
	for(int i=1; i<=N; ++i) {
		int now=d[i];
		if (p<x[now]) throw -now;
		for(int j=now+1; j<N; ++j) {
			a[p]=now+1;
			while(a[p]>0) ++p;
		}
	}
	puts("Yes");
	for(int i=1; i<=N*N; ++i) {
		printf("%d ",a[i]);
	}
	puts("");
}

