	for(int j = ans.size(); j < xs[index]; j++)
	{
	  if(stack.empty())
	  {
		success = false;
		break;
	  }
	  ans.push_back(stack.back());
	  stack.pop_back();
	}
	ans.push_back(index);
	for(int j = 0; j < n - index; j++)
	{
	  stack.push_back(index);
	}
  }

  if(success)
  {
	for(auto v : stack)
	{
	  ans.push_back(v);
	}
  }

  if(success)
  {
	cout << "Yes" << endl;
	for(int i = 0; i < n * n; i++)
	{
	  if(i > 0) cout << " ";
	  cout << ans[i];
	}
	cout << endl;
  }
  else
  {
	cout << "No" << endl;
  }  
}

