			if (!Ans[j])
				Ans[j] = i, ++cnt;
		if (cnt < i)
		{
			puts("No");
			return 0;
		}
	}
	for (int i = 1;i <= N * N;++i)
	{
		if (!Ans[i])
		{
			if (S.empty())
			{
				puts("No");
				return 0;
			}
			Ans[i] = S.begin() -> first;
			if ((--S[S.begin() -> first]) == 0)
				S.erase(S.begin() -> first);
		}
		if (X.count(i) && X[i] < N)
			S[X[i]] = N - X[i];
	}
