void solve() {
    int n;
    scanf("%d",&n);
    priority_queue<pair<int,int>,vector<pair<int,int> >,greater<pair<int,int> > >pq;
    for(int i=1;i<=n;++i) {
        scanf("%d",&x[i]);
        ret[x[i]] = i;
        cc[i] = i-1;
        pq.push(make_pair(x[i]-cc[i],i));
    }
    int lim = n*n;
    for(int i=1;i<=lim;++i) {
        if(ret[i]!=0) {
            continue;
        }
        while(!pq.empty()) {
            int id = pq.top().second;
            if(cc[id]==0) {
                pq.pop();
                continue;
            } else {
                break;
            }
        }
        if(pq.size()>0) {
            int id = pq.top().second;
            if(x[id]<i) {
                printf("No\n");
                return;
            }
            ret[i] = id;
            pq.pop();
            --cc[id];
            if(cc[id]>0) {
                pq.push(make_pair(x[id]-cc[id],id));
            }
        }
    }
    queue<pair<int,int> >q;
    printf("Yes\n");
    int gg = 0;
    for(int i=1;i<=n;++i) {
        gg += n-i;
        q.push(make_pair(n-i,i));
    }
    for(int i=1;i<=lim;++i) {
        if(ret[i]==0) {
            while(!q.empty()) {
                if(q.front().first==0) {
                    q.pop();
                } else {
                    break;
                }
            }
            int id = q.front().second;
            int rem = q.front().first -1;
            q.pop();
            ret[i] = id;
            if(rem>0) {
                q.push(make_pair(rem,id));
            }
        }
        printf("%d ",ret[i]);
    }
    putchar('\n');
}

