	for (int i = 2; i <= n; ++i) if (a[i].first == a[i - 1].first) {
		printf("No\n"); return 0;
	}

	deque <int> dq;
	int ptr = 1;

	for (int pos = 1; pos <= n * n; ++pos) {
		if (a[ptr].first == pos) {
