	// cout << ans << endl;

	vector<pii> rv;
	rrep(i,N) rv.emplace_back(N*N - v[i].X - 1, v[i].Y);
	vector<int> rans;
	rep(i,N){
		int num = rans.size() + i;
		int right = N - rv[i].Y - 1;
		if( rv[i].X - num < right ){
			able = false;
			break;
		}else{
			rep(j, right) rans.push_back(rv[i].Y);
		}
	}
	// cout << able << endl;
	// cout << rans << endl;

	if( !able ){
		cout << "No" << endl;
		return 0;
	}

	cout << "Yes" << endl;
	int pos = 0;
	reverse(all(ans));
	//cout << v << endl;
	rep(i,N*N){
		if( i == v[pos].X ){
			cout << v[pos].Y+1 << " ";
			pos++;
		}else{
			if( ans.size() ){
				cout << ans.back()+1 << " ";
				ans.pop_back();
			}else{
				cout << rans.back()+1 << " ";
				rans.pop_back();
			}
		}
	}
	cout << endl;

	return 0;
}

