int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n;
	cin>>n;
	vector<P> x(n);
	REP(i,n) {
		cin>>x[i].first;
		x[i].first--;
		x[i].second=i+1;
	}
	sort(ALL(x));
	vector<ll> ans(n*n,-1);
	ll pos=0;
	REP(i,n) {
		ans[x[i].first]=x[i].second;
