{
  int n; cin >> n;
  vector<int> x(n); cin >> x;
  rep(i, n)x[i]--;

  vector<int> res(n * n, - 1);

  vector<int> e(n); rep(i, n)e[i] = i;
  sort(all(e), [&](int a, int b){
    return x[a] < x[b];
  });

  rep(i, n - 1)if(x[e[i]] == x[e[i+1]]){
    cout << "No" << endl;
    return 0;
  }

  rep(i, n){
    res[x[e[i]]] = e[i];
    int curr = 0;
    for(int j = 0; j < e[i]; j++){
      if(curr == n * n){
        cout << "No" << endl;
        return 0;
      }
      for(int k = curr; k < n * n; k++){
        if(res[k] == -1 && x[e[i]] > k){
          res[k] = e[i];
          curr = k + 1;
          break;
        }
        if(k + 1 == n * n){
          cout << "No" << endl;
          return 0;
        }
      }
    }
  }
  rrep(i, n){
    int curr = n * n - 1;
    rep(j, n - e[i] - 1){
      if(curr < 0){
        cout << "No" << endl;
        return 0;
      }
      for(int k = curr; k >= 0; k--){
        if(res[k] == -1 && x[e[i]] < k){
