          curr = k - 1;
          break;
        }
        if(k == 0){
          cout << "No" << endl;
          return 0;
        }
      }
    }
  }
  cout << "Yes" << endl;
  rep(i, sz(res))res[i] += 1;
  cout << res << endl;
  return 0;
}

