struct position_number{
    int position, number;
};

bool compare(position_number position1, position_number position2){
    return position1.position < position2.position;
}

int main(){
    int N;
    cin >> N;
    int ans[N * N];
    int positions_not_sorted[N];
    position_number positions[N];
    for(int i = 0; i < N; i++){
        cin >> positions_not_sorted[i];
        positions[i].position = positions_not_sorted[i];
        positions[i].number = i;
    }
    sort(positions, positions + N, &compare);
    int ans_look = 0;
    fill(ans, ans + N * N, -1);
    for(int i = 0; i < N; i++){
        ans[positions[i].position - 1] = positions[i].number;
        for(int j = 0; j < positions[i].number;){
            if(ans[ans_look] == -1){
                ans[ans_look] = positions[i].number;
                j++;
            }else{
                ans_look++;
            }
            if(ans_look >= positions[i].position - 1){
                cout << "No" << endl;
                return 0;
            }
        }
    }
    int space_filler_number = 0;
    int space_filler_count = 0;
    for(int i = 0; i < N * N; i++){
        if(ans[i] == -1){
            ans[i] = space_filler_number;
            space_filler_count++;
            if(space_filler_count == N - space_filler_number - 1){
                space_filler_count = 0;
                space_filler_number++;
            }
        }
    }
    int number_count[N];
    fill(number_count, number_count + N, 0);
    string ans_string = "";
    for(int i = 0; i < N * N; i++){
        ans_string += to_string(ans[i] + 1) + " ";
        number_count[ans[i]]++;
        if(number_count[ans[i]] == ans[i] + 1 && positions_not_sorted[ans[i]] - 1 != i){
            cout << "No" << endl;
            return 0;
        }
    }
    ans_string.pop_back();
    cout << "Yes" << endl << ans_string << endl;
}

