#define FILE_NAME "a"

const int MAXN = 500 + 10;

int n;
int x[MAXN];
int a[MAXN * MAXN];

bool read() {
	if  (scanf("%d", &n) < 1) {
		return 0;
	}
	forn(i, n) {
		scanf("%d", &x[i]);
		--x[i];
	}
	memset (a, -1, sizeof a);
	forn(i, n) {
		a[x[i]] = i;
	}
	return 1;
}

int ans[MAXN * MAXN];
int was[MAXN];

bool solve() {
	memcpy(ans, a, sizeof a);

	int i = 0;
	int j = 0;
	while (j < n * n && a[j] == -1) {
		++j;
	}
	assert(j < n * n);

	vi order;
	while (i < n * n && j < n * n) {
		int num = a[j];
		order.pb(num);

		int ready = 0;
		while (ready < num && i < n * n) {
			if  (ans[i] == -1) {
				ans[i] = num;
				++ready;
			}
			++i;
		}

		if (ready < num) {
			return 0;
		}

		++j;
		while (j < n * n && a[j] == -1) {
			++j;
		}
	}

	j = 0;
	i = 0;
	while (i < n * n && j < sz(order)) {
		int num = order[j];
		++j;
		int cnt = n - num - 1;

		int ready = 0;
		while (i < n * n && ready < cnt) {
			if  (ans[i] == -1) {
				ans[i] = num;
				++ready;
			}
			++i;
		}

		if (ready < cnt) {
			return 0;
		}
	}

	memset (was, 0, sizeof was);
	forn(i, n * n) {
		if  (ans[i] == was[ans[i]]) {
			if  (i != x[ans[i]]) {
				return 0;
			}
		}
		++was[ans[i]];
	}

	puts("Yes");
	forn(i, n * n) {
		printf("%d ", ans[i] + 1);
	}
	puts("");
	return 1;
}

