int main()
{
    ios::sync_with_stdio(false);

    int N; cin >> N;
    vector<PII> X(N);
    int NN = N*N;
    vector<int> ans(NN);
    rep(i, N) {
        int tmp; cin >> tmp;
        X[i] = PII(tmp-1, i+1);
    }
    sort(ALL(X));

    bool ok = true;

    for (auto x : X) {
        ans[x.first] = x.second;
        if (x.second == 1) continue;

        int cnt = 0;
        for (int i=0; i<x.first; i++) {
            if (ans[i] == 0) {
                ans[i] = x.second;
                cnt++;
            }

            if (cnt == x.second - 1) break;
        }

        if (cnt < x.second-1) {
            ok = false;
            break;
        }
    }

    for (int j=N-1; j>=0; j--) {
        PII x = X[j];
        if (x.second == N) continue;

        int cnt = 0;
        for (int i=NN-1; i>x.first; i--) {
            if (ans[i] == 0) {
                ans[i] = x.second;
                cnt++;
            }

            if (cnt == N - x.second) break;
        }

        if (cnt < N - x.second) {
            ok = false;
            break;
        }
    }

