using namespace std;

class TaskD {
public:
	void solve(std::istream& in, std::ostream& out) {
		int n;
		in >> n;
		vector<int> v(n);
		vector<int> back_map(n * n, -1);
		for (int i: range(n)) {
			in >> v[i];
			--v[i];
			back_map[v[i]] = i;
		}

		deque<int> small_to_use;
		deque<int> big_to_use;

		for (int i: back_map) {
			if (i != -1) {
				for (int j: range(i)) {
					small_to_use.push_back(i);
				}
			}
		}

		vector<int> ans(n * n);

		vector<int> used(n);
		for (int i: range(n * n)) {
			if (back_map[i] != -1) {
				ans[i] = back_map[i];
				for (int j: range(n - 1 - ans[i])) {
					big_to_use.push_back(ans[i]);
				}
				used[ans[i]] = true;
			} else if (!small_to_use.empty()) {
				ans[i] = small_to_use.front();
				small_to_use.pop_front();
				if (used[ans[i]]) {
					out << "No\n";
					return;
				}
			} else if (!big_to_use.empty()) {
				ans[i] = big_to_use.front();
				big_to_use.pop_front();
			} else {
				out << "No\n";
				return;
			}
		}

		out << "Yes\n";
		for (int x: ans) {
			out << x + 1 << " ";
		}
	}
};


int main() {
	std::ios_base::sync_with_stdio(false);
	TaskD solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
	out << std::fixed;
	out.precision(20);
	solver.solve(in, out);
	return 0;
}

