void Work(){
	int now=1;
	REP(i,1,n){
		int x=A[i].se,y=A[i].fi;
		Ans[y]=x;
		REP(j,1,x-1){
			while(Ans[now])now++;
			Ans[now++]=x;
		}
		if(now>y){
			puts("No");return;
		}
	}
	while(Ans[now])now++;
	REP(i,1,n){
		int x=A[i].se;
		REP(j,1,n-x)has.PB(i);
	}
	int now2=0;
	while(now<=n*n){
		if(A[has[now2]].fi>now){
			puts("No");
			return;
		}
		Ans[now]=A[has[now2]].se;
		now2++;
		while(Ans[now])now++;
	}
	puts("Yes");
	REP(i,1,n*n)printf("%d ",Ans[i]);
}

