signed main() {
	INIT;
	VAR(int, n);
	VEC(int, x, n);
	std::vector<PAIR> pv(n);
	REP(i, n) {
		pv[i] = PAIR(x[i], i);
	}
	std::sort(ALL(pv));
	std::vector<int> v(n*n, -1);
	std::vector<int> cnt(n, n);
	int pos = 0;
	REP(i, n) {
		auto p(pv[i]);
		if (v[p.first - 1] != -1) NO;
		int rest = p.second;
		while (rest) {
			if (v[pos] == -1) {
				--rest;
				--cnt[p.second];
				v[pos] = p.second + 1;
			}
			++pos;
		}
		if (pos > p.first) NO;
		v[p.first - 1] = p.second + 1;
		--cnt[p.second];
	}
	pos = n*n - 1;
	std::reverse(ALL(pv));
	REP(i, n) {
		auto p(pv[i]);
		if (cnt[p.second] == 0) continue;
		int rest = n-p.second;
		while (rest) {
			if (v[pos] == -1) {
				--rest;
				--cnt[p.second];
				v[pos] = p.second + 1;
			}
			--pos;
			if (cnt[p.second] == 0) break;
		}
		if (cnt[p.second] == 0) continue;
		if (pos < p.first) NO;
		v[p.first - 1] = p.second + 1;
		--cnt[p.second];
	}
	REP(i, n*n) {
		if (v[i] == -1) NO;
	}
	OUT("Yes")BR;
	REP(i, n*n) {
		OUT(v[i])SP;
	}
	BR;
	return 0;
}

