constexpr int INF=1e9;
constexpr int MOD=1e9+7;
constexpr double EPS=1e-9;

void solve(vi xs)
{
	int n=xs.size();

	vector<tuple<int,int>> ts(n);
	rep(i,n) ts[i]=mt(xs[i],i+1);
	sort(all(ts));

	deque<int> q;
	for(auto t:ts){
		int x=get<1>(t);
		rep(_,x-1) q.push_back(x);
	}

	vi occ(n+1),res;
	int p=0;
	for(auto t:ts){
		int i,x; tie(i,x)=t;
		for(;p<i;p++){
			if(q.empty()){
				cout<<"No"<<endl;
				return;
			}
			occ[q.front()]++;
			res.push_back(q.front());
			q.pop_front();
		}
		p=i+1;
		if(occ[x]<x-1){
			cout<<"No"<<endl;
			return;
		}
		res.push_back(x);
		rep(_,n-x) q.push_back(x);
	}

	while(q.size()){
		res.push_back(q.front());
		q.pop_front();
	}

	cout<<"Yes"<<endl;
	rep(i,res.size())
		cout<<res[i]<<" \n"[i+1==res.size()];
}

int main()
{
	for(int n;cin>>n&&n;){
		vi xs(n);
		rep(i,n) cin>>xs[i],xs[i]--;
		solve(xs);
	}
}

