const int N = 505, M = 250005;
int n, sum, b[N], ans[M], ssum[N];
struct node{
    int pl, num;
}a[N];
bool cmp(node x, node y){
	return x.num < y.num || x.num == y.num && x.pl < y.pl;
    //return x.num == y.num ? x.num < y.num : x.pl < y.pl;
}
int main(){
    scanf("%d", &n);
    rep(i, 1, n){
        scanf("%d", &b[i]);
        a[i].pl = i, a[i].num = b[i];
    }
    sort(a + 1, a + n + 1, cmp);
    rep(i, 1, n){
        sum += a[i].pl;
        if(a[i].num < sum || a[i].num == a[i-1].num) {
            printf("No\n");
            return 0;
        }
    }
    sum = 0;
    per(i, n, 1){
        sum += n - a[i].pl;
        if(n * n - a[i].num < sum) {
            printf("No\n");
            return 0;
        } 
    }
    rep(i, 1, n){
        int num = a[i].pl - 1;
        ans[a[i].num] = a[i].pl, ssum[a[i].pl]++;
        rep(j, 1, a[i].num - 1) {
            if(!num) break;
            if(!ans[j]) ans[j] = a[i].pl, num--, ssum[a[i].pl]++;
        }
    }
	rep(i, 1, n) rep(j, a[i].num + 1, n * n) {
        if(ssum[a[i].pl] == n) break;
        if(!ans[j]) ans[j] = a[i].pl, ssum[a[i].pl]++;
    }
    printf("Yes\n");
    rep(i, 1, n * n) printf("%d ", ans[i]);
    return 0;
}

