const int MAX_N = 507;

int x[MAX_N], a[MAX_N * MAX_N], t[MAX_N], n, head;

void solve() {
	cin >> n;

	for(int i = 0; i < n; ++i) {
		cin >> x[i];
		--x[i];
	}

	head = 0;

	for(int epoch = 0; epoch < n; ++epoch) {
