		for(int i = 0; i < n; ++i) {
			a[head++] = t[i];
		}
	}

	cout << "Yes\n";

	for(int i = 0; i < head; ++i) {
		cout << a[i] + 1 << ' ';
	}

	cout << '\n';
}

