			add_edge(i,n+i,i);
			for(int j=0;j<x[i];j++){
				add_edge(n+i,4*n+j,1);
			}
		}
		add_edge(i,n*2+i,1);
		add_edge(n*2+i,n*4+x[i],1);
		if(i<n-1){
			add_edge(i,3*n+i,n-i-1);
			for(int j=x[i]+1;j<n*n;j++){
				add_edge(3*n+i,4*n+j,1);
			}
		}
	}
	for(int i=0;i<n*n;i++){
		add_edge(4*n+i,t,1);
	}
