VI solve() {
    int n; scanf("%d", &n);
    VPI xs(n);
    repn(i, n) { scanf("%d", &xs[i].fi); --xs[i].fi; xs[i].se=i; }
    sort(all(xs));

    VI r(n*n, -1);
    for(const auto& x: xs) {
        if(r[x.fi]>=0) return VI();
        r[x.fi]=x.se;
    }
    int i=0;
    for(const auto& x: xs) {
        int pos=x.fi, val=x.se, num=x.se;
        while(num--) {
            while(i<pos && r[i]>=0) ++i;
            if(i>=pos) return VI();
            r[i]=val;
        }
    }
    i=n*n-1;
    reverse(all(xs));
    for(const auto& x: xs) {
        int pos=x.fi, val=x.se, num=n-x.se-1;
        while(num--) {
            while(i>pos && r[i]>=0) --i;
            if(i<=pos) return VI();
            r[i]=val;
        }
    }
    return r;
}

int main() {
    VI r=solve();
    if(r.empty()) {
        printf("No\n");
    } else {
        printf("Yes\n");
        for(int x: r) printf("%d ", x+1);
        printf("\n");
    }
    return 0;
}

