class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        ll N;
        is >> N;
        if(!is) return;
        vector<ll> a(N*N, -1);
        vector<ll> X(N);
        for (int i = 0; i < N; ++i) {
            int x;
            is >> x; x--;
            a[x] = i+1;
        } // end i
        map<ll, int> rem;
        for (int i = 0; i < a.size(); ++i) {
            if(a[i] != -1){
                if(a[i] != N) rem.insert({a[i], N - a[i]});
            }
            else{
                if(!rem.empty()){
                    auto&& ps = rem.begin();
                    a[i] = ps->first;
                    ps->second--;
                    if(ps->second == 0){
                        rem.erase(ps);
                    }
                }
            }
        } // end i
        if(!rem.empty()){
            os << "No\n"; return;
        }
        map<ll, int> add;
        for (int i = a.size() - 1; i >= 0; --i) {
            if(a[i] != -1){
                rem[a[i]]++;
                if(rem[a[i]] == N - a[i] + 1){
                    add[a[i]] = a[i] - 1;
                }
            }
            else{
                while(!add.empty() and add.begin()->second == 0) add.erase(add.begin());
                if(add.empty()) {
                    os << "No\n"; return;
                }
                a[i] = add.begin()->first;
                add.begin()->second--;
            }
        } // end i

        os << "Yes\n";
        for (auto &&ai : a) {
            os << ai << ' ' ;
        } // end ai
        os << endl;

    }
};

