const double EPS = 1e-10;
const int64_t INF = 1e9;

const int MAX_N = 500;

int N;
int x[MAX_N];

void solve()
{
	vector<tuple<int,int,int>> v;
	for (int i = 0; i < N; ++i) {
		v.push_back(make_tuple(x[i], i, i));
	}
	sort(v.begin(), v.end());

	int pos = 1;
	int index = 0;
	stack<int> f;
	vector<int> ans(N * N);
	int ans_i = 0;
	for (int i = 0; i < N; ++i) {
		int t = get<0>(v[i]) - pos;
		while (t > 0 && index < N) {
			int s = min(t, get<1>(v[index]));
			t -= s;
			get<1>(v[index]) -= s;
			for (int j = 0; j < s; ++j) {
				ans[ans_i++] = get<2>(v[index]);
			}
			if (t > 0) ++index;
		}
		if (t > 0) {
			int s = min(t, (int)(f.size()));
			t -= s;
			for (int i = 0; i < s; ++i) {
				int a = f.top(); f.pop();
				ans[ans_i++] = a;
			}
		}
		if (t > 0) {
			printf("No\n");
			return;
		}

		if (get<1>(v[i]) > 0) {
			printf("No\n");
			return;
		}
		pos = get<0>(v[i]) + 1;
		ans[ans_i++] = get<2>(v[i]);
		for (int j = 0; j < N - 1 - get<2>(v[i]); ++j) {
			f.push(get<2>(v[i]));
		}
	}

	printf("Yes\n");
	while (!f.empty()) {
		int a = f.top(); f.pop();
		ans[ans_i++] = a;
	}

	for (int i = 0; i < N * N; ++i) {
		printf("%d%c", ans[i] + 1, i == N * N - 1 ? '\n' : ' ');
	}


}

int main()
{
	scanf("%d", &N);
	for (int i = 0; i < N; ++i) {
		scanf("%d", &x[i]);
	}
	solve();

	return 0;
}

