using namespace std;
int main() {
    int n; cin >> n;
    vector<pair<int, int> > x;
    for (int i = 0; i < n; i++) {
        int a; cin >> a;
        x.push_back({a, i+1});
    }
    sort(x.begin(), x.end());
    vector<int> ans(n*n,0);
    for (int i = 0, s = 0; i < n; i++) {
        int j = x[i].second;
        s += j;
        if (s > x[i].first) { cout << "No\n"; return 0; }
        ans[x[i].first-1] = j;
        for (int k = 0, jj = j-1; jj > 0; jj--) {
            while (ans[k] > 0) k++;
            ans[k] = j;
        }
    }
    for (int i = n-1, s = 0; i >= 0; i--) {
        int j = x[i].second;
        s += n-j+1;
        if (s > n*n-x[i].first+1) { cout << "No\n"; return 0; }
    }
    for (int i = 1, j = 0; i < n; i++) {
        int k = n-i;
        while (k > 0) {
            while (ans[j] > 0) j++;
            ans[j] = i;
            k--;
        }
    }

    cout << "Yes\n";
    for (int a : ans) cout << a << ' ';
    cout << endl;
}

