int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<int> x(n + 1);
	x[0] = -1;
	for (int i = 1; i <= n; i++) {
		cin >> x[i];
		x[i]--;
	}

	bool ans = true;
	vector<int> a;
	deque<int> b;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < i; j++) {
			b.push_back(i + 1);
		}
	}

	for (int i = 1; i <= n; i++) {
		for (int j = x[i - 1] + 1; j < x[i]; j++) {
			if (b.empty()) {
				ans = false;
				break;
			}
			a.push_back(b.front());
			b.pop_front();
		}
		if (!ans) break;
		a.push_back(i);
		for (int j = 0; j < n - i; j++) {
			b.push_back(i);
		}
	}

	if (ans) {
		while (!b.empty()) {
			a.push_back(b.front());
			b.pop_front();
		}
		cout << "Yes" << endl;
		cout << a[0];
		for (int i = 1; i < n * n; i++) {
			cout << " " << a[i];
		}
		cout << endl;
	} else {
		cout << "No" << endl;
	}
	return 0;
}

