void solve() {
  int n;
  cin >> n;
  vector<int> x(n);
  vector<int> a(n * n);
  set<int> free_places;
  for (int i = 0; i < n * n; i++) {
    free_places.insert(i);
  }
  for (int i = 0; i < n; i++) {
    cin >> x[i];
    --x[i];
    a[x[i]] = i;
    free_places.erase(x[i]);
  }
  auto no = []() {
    cout << "No" << endl;
    exit(0);
  };
  for (int i = 0; i < n; i++) {
    int on_left = i;
    while (on_left--) {
      auto it = free_places.lower_bound(x[i]);
      if (it == free_places.begin()) {
        no();
      }
      --it;
      a[*it] = i;
      free_places.erase(it);
    }
  }
  for (int i = 0; i < n; i++) {
    int on_right = n - i - 1;
    while (on_right--) {
      auto it = free_places.lower_bound(x[i]);
      if (it == free_places.end()) {
        no();
      }
      a[*it] = i;
      free_places.erase(it);
    }
  }
  cout << "Yes\n";
  for (auto x : a) {
    cout << x + 1 << " ";
  }
  cout << "\n";
}

