    int upd_cnt = 0;
    for (int j = 0; j < N; j++){
      if (cnt[j] < lb[j]){
        cnt[j]++;
        ans[i] = j + 1;
        upd_cnt++;
      }
    }
    if (upd_cnt >= 2){
      ok = false;
      break;
    }
    if (upd_cnt == 1){
      continue;
    }
    for (int j = 0; j < N; j++){
      if (cnt[j] + 1 <= ub[j]){
        cnt[j]++;
        ans[i] = j + 1;
        break;
      }
    }
    if (ans[i] == 0){
      ok = false;
      break;
    }
  }
  if (!ok){
    cout << "No" << endl;
  } else {
    return 1;
    cout << "Yes" << endl;
    for (int i = 0; i < N * N; i++){
      cout << ans[i];
      if (i < N * N - 1){
        cout << ' ';
      }
    }
    cout << endl;
  }
}

