struct node {
	int x;
	int t;
};

bool operator < (node a, node b) {
	return a.t < b.t;
}

int main() {
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<node> R;
    for (int i = 1;i <= N;i++) {
    	int m;
    	cin >> m;
    	node p;
    	p.x = i;
    	p.t = m - 1;
    	R.push_back(p);
    }
    sort(R.begin(), R.end());
    vector<int> T(N * N, 0);
    vector<int> G(N * N, 0);
    int pos = 0;
    queue<int> M;
    for (int i = 0;i < R.size();i++) {
    	int x = R[i].x;
    	int y = R[i].t;
    	int rem = x - 1;
    	T[y] = x;
    	G[y] = x;
    	while (rem > 0 && pos < y) {
    		if (T[pos] == 0) {
    			T[pos] = x;
    			rem--;
    		}
    		pos++;
    	}
    	if (rem > 0) {
    		cout << "No" << endl;
    		return 0;
    	}
    }
    for (int i = 0;i < N * N;i++) {
    	if (T[i] == 0) {
    		if (M.size() == 0) {
    			cout << "No" << endl;
    			return 0;
    		}
    		else {
    			T[i] = M.front();
    			M.pop();
    		}
    	}
    	if (G[i] != 0) {
    		for (int j = 0;j < N - G[i];j++) {
    			M.push(G[i]);
    		}
    	}
    }
    cout << "Yes" << endl;
    for (int i = 0;i < N * N;i++) {
    	if (i != 0) cout << ' ';
    	cout << T[i];
    }
    cout << endl;
    return 0;
}

