inline void solve () {
    int M = N * N;
    rep (i, 1, M) {
        if (a[i]) {
            s[a[i]]++;
            if (s[a[i]] != a[i]) { puts("No"); exit(0); }
        } else {
            bool flag = false;
            rep (j, 1, N) if (s[b[j]] < b[j] - 1) {
                s[a[i] = b[j]]++;
                flag = true;
                break;
            }
            if (!flag) {
                rep (j, 1, N) if (s[j] >= j && s[j] < N) {
                    s[a[i] = j]++;
                    break;
                }
            }
        }
    }
    puts("Yes");
