using namespace std;

const LL MOD = 1000000007;// 10^9+7
const int INF = (1 << 30);

struct cell {
	int id; //識別番号
	int left;//残っている数
	int p;   //xの値
};


//変数
int N;
vector<int> ans;
vector<cell> x, any;



//サブ関数
//入力
void input()
{
	cin >> N;
	vector<cell> data_array;

	REP(i, N) {
		int tmp;
		cin >> tmp;

		cell tmpc;
		tmpc.id = i + 1;
		tmpc.left = i;
		tmpc.p = tmp - 1;
		data_array.push_back(tmpc);
	}

	// 並び替えの方法をラムダ関数で記述
	sort(data_array.begin(),
		data_array.end(),
		[](const cell& a, const cell& b) {return a.p < b.p; }
	);

	x = data_array;
}


//計算
void calc()
{
	while (!x.empty()) 
	{
		auto itr = x.begin();
		//x_i の場合
		if (itr->p == ans.size()) {
			//丁度id個目であることは、既にid-1個使っている場合
			if (itr->left == 0) {
				ans.push_back(itr->id);
				itr->left = N - (itr->id);
				any.push_back(*itr);
				x.erase(itr);
			}
			//使ってない場合は強制終了(生成不可能なので)
			else {
				return;
			}
		}
		//何もなければ、x_iの一番小さいやつを使いましょう
		else {
			while (itr != x.end() && itr->left == 0)itr++;
			if (itr != x.end()) {
				ans.push_back(itr->id);
				itr->left--;
			}
			//全部使われちゃってたら、既に通り越したやつを使いましょう
			else {
				itr = any.begin();
				while (itr != any.end() && itr->left == 0)itr++;
				if (itr != any.end()) {
					ans.push_back(itr->id);
					itr->left--;
				}
				else {
					//ここに来ることある？
					return;
				}
			}
		}
	}

}


//出力
void output()
{
	if (ans.size() == N * N) {
		cout << "Yes" << endl;
		for (auto num : ans) {
			cout << num << " ";
		}
		cout << endl;
	}
	else {
		cout << "No" << endl;
	}
}


//デバッグ
void debug()
{
	int N;
	cin>>N;
}


//メイン関数
int main()
{
	input();
	calc();
	output();
	debug();

	return 0;
}

