struct Elem {
    int black, blue, id;
    Elem() {}
    Elem(int a, int b, int c) : black(a), blue(b), id(c) {}
    bool operator<(const Elem &e) const {
        int vl = black - blue;
        int vr = e.black - e.blue;
        if(vl != vr) return vl > vr;
        else return blue < e.blue;
    }
};

int main() {
    int N; cin >> N;
