            for(int i=1; i<=N-ans[t]; i++) pool.emplace_back(ans[t]);
            continue;
        }

        if(que.size()) {
            Elem cur = que.top(); que.pop();
            int black = cur.black - t, blue = cur.blue, id = cur.id;
