	for(int i=1;i<=n*n;i++){
		for(int j=1;j<=n;j++) if(x[j]==i){
			if(++c[j]<j) return 0;
			a[i]=j; break;
		}
		if(a[i]) continue;
		int k=0;
		for(int j=1;j<=n;j++) if(x[j]>i&&c[j]<j-1&&x[j]<x[k]) k=j;
