int n;
int a[500 * 500 + 1];
int x[501];
int now[501];
void solve() {
	int n;
	getint(n);
	memset(a + 1, -1, 4 * n * n);
	memset(now, 0, sizeof now);
	int p = 1;
	for (int i = 1; i <= n; i++) {
		getint(x[i]);
		a[x[i]] = i;
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j < i; j++) {
			while (a[p] != -1) {
				p++;
			}
			a[p] = i;
		}
	}
	p = n * n;
	for (int i = n; i >= 1; i--) {
		for (int j = 0; j < n - i; j++) {
			while (a[p] != -1) {
				p--;
			}
			a[p] = i;
		}
	}
	for (int i = 1; i <= n * n; i++) {
		if (a[i] == -1)
			while (1);
		if (now[a[i]] < a[i]) {
			now[a[i]]++;
			if (now[a[i]] == a[i]) {
				if (i != x[a[i]]) {
					puts("No");
					return;
				}
			}
		}
	}
	puts("Yes");
	for (int i = 1; i <= n * n; i++) {
		printf("%d%c", a[i], i == n * n ? '\n' : ' ');
	}
}

int main() {
	for (int t = 50; t--; )
		solve();
	return 0;
}

