int main()
{
  int N, X[500];
  int Z[250000], ev[250000];
  memset(Z, -1, sizeof(Z));
  memset(ev, -1, sizeof(ev));

  cin >> N;
  for(int i = 0; i < N; i++) {
    cin >> X[i];
    --X[i];
    ev[X[i]] = i + 1;
  }

  queue< int > unhappy, happy;

  for(int i = 0; i < N * N; i++) {
    if(~ev[i]) {
      if(ev[i] - 1 > unhappy.size()) fail();
      for(int j = 0; j < ev[i] - 1; j++) {
        Z[unhappy.front()] = ev[i];
        unhappy.pop();
      }
      Z[i] = ev[i];
    } else unhappy.push(i);
  }

  for(int i = N * N - 1; i >= 0; i--) {
    if(~ev[i]) {
      if(N - ev[i] > happy.size()) fail();
      for(int j = 0; j < N - ev[i]; j++) {
        Z[happy.front()] = ev[i];
        happy.pop();
      }
    } else if(Z[i] == -1) happy.push(i);
  }

  cout << "Yes" << endl;
  for(int i = 0; i < N * N; i++) {
    cout << Z[i] << " ";
  }
  cout << endl;

}

