void mainmain(){
	int n;
	cin>>n;
	vint x(n);
	rep(i,n) cin>>x[i],x[i]--;
	vint v(n*n,-1);
	priority_queue<pii,vector<pii>, greater<pii> > pq;
	vint cnt(n);
	rep(i,n){
		v[x[i]]=i;
		if(i) pq.push(pii(x[i], i));
		if(n-1-i) pq.push(pii(x[i]+INF, n-1-i));
	}
	bool ok = true;
	rep(i,n*n){
		if(v[i]!=-1){
			// cout<<v[i]<<" "<<cnt[v[i]]<<endl;
			ok &= cnt[v[i]]==v[i];
		}
		else{
			pii top = pq.top();
			pq.pop();
			top.S--;
			if(top.F<INF) v[i]=v[top.F];
			else v[i]=v[top.F-INF];
			cnt[v[i]]++;
			if(top.S) pq.push(top);
		}
		// cout<<v[i]<<" "<<ok<<endl;
	}
	if(ok){
		cout<<"Yes"<<endl;
		rep(i,n*n){
			if(i) cout<<" ";
			cout<<v[i]+1;
		}
		cout<<endl;
	}
	else{
		cout<<"No"<<endl;
	}
}


