#define MAXN 300000
int n, m, k, ans[MAXN], pos[MAXN], sum[MAXN];
std::set<int> l, r;
int main() {
	scanf("%d", &n);
	m = n * n;
	for (int i = 1, x; i <= n; i++) {
		scanf("%d", &x);
		pos[x] = i;
		if (i != x) r.insert(x);
	}
	for (int i = 1; i <= m; i++) {
		if (pos[i]) {
			if (++sum[pos[i]] != pos[i]) return puts("No"), 0;
			ans[i] = pos[i];
			l.insert(i);
		} else {
			if (r.size()) {
				int x = *r.begin();
				ans[i] = pos[x];
				if (++sum[pos[x]] == pos[x] - 1) r.erase(x);
			} else if (l.size()) {
