int main()
{
  int n;
  scanf("%d",&n);
  int x[500];
  for(int i=0;i<n;i++){
    scanf("%d",x+i);
    x[i]--;
  }
  priority_queue<pair<int,int> > Q;
  for(int i=0;i<n;i++){
    for(int k=0;k<i;k++){
      Q.push(make_pair(-x[i],i));
    }
  }
  static int A[500000];
  for(int i=0;i<n*n;i++){
    A[i]=-1;
  }
  for(int i=0;i<n;i++){
    A[x[i]]=i;
  }
  int T[500];
  for(int i=0;i<n;i++){
    T[i]=i;
  }
  bool F=0;
  for(int i=0;i<n*n;i++){
    if(A[i]!=-1){
      int j=A[i];
      if(T[j]!=0){
	F=1;
	break;
      }
      for(int k=0;k<n-j-1;k++){
	Q.push(make_pair(-n*n-1,j));
      }
    }
    else{
      if(Q.empty()){
	F=1;
	break;
      }
      A[i]=Q.top().second;
      T[A[i]]--;
      Q.pop();
    }
  }
  if(F){
    puts("No ");
  }
  else{
    puts("Yes ");
    for(int i=0;i<n*n;i++){
      printf("%d ",A[i]+1);
    }
    putchar('\n');
  }
  return 0;
}

