bool fillWith(vector<int> &rr, int &caret, int what, int how_many, int end_index) {
    for (; caret < end_index; ++caret) {
        if (rr[caret] != 0)
            continue;
        if (how_many == 0)
            break;
        rr[caret] = what;
        --how_many;
    }
    if (how_many)
        return false;
    return true;
}


