inline void del(int x) {
  nxt[pre[x]] = nxt[x];
  pre[nxt[x]] = pre[x];
}
int main() {
  scanf("%d", &n);
  m = n * n;
  nxt[0] = 1, pre[m + 1] = m;
  for (int i = 1; i <= m; ++i) {
    pre[i] = i - 1;
    nxt[i] = i + 1;
  }
  for (int i = 1; i <= n; ++i) {
    scanf("%d", &pos[i]);
    for (int j = 1; j < i; ++j) {
      if (pos[i] == pos[j]) {
        puts("No");
