      }
    }
    id[pos[i]] = i;
    a[pos[i]] = i;
    del(pos[i]);
  }
  sort(pos + 1, pos + n + 1);
  for (int i = 1; i <= n; ++i) {
    int rev = id[pos[i]];
    for (int j = 1, cur = 0; j < rev; ++j) {
      cur = nxt[cur];
      if (cur >= pos[i]) {
        puts("No");
        return 0;
      }
      a[cur] = rev;
      del(cur);
    } 
