    cout << "No" << endl;
  } else {
    vector<vector<int>> lb_add(N * N + 1);
    for (int i = 0; i < N; i++){
      for (int j = x[i] - i; j <= x[i]; j++){
        lb_add[j].push_back(i);
      }
      for (int j = N * N - N + i + 2; j <= N * N; j++){
        lb_add[j].push_back(i);
      }
    }
    /*
    for (int i = 0; i <= N * N; i++){
      cout << i << ": ";
      for (int j : lb_add[i]){
        cout << j;
      }
      cout << endl;
    }
    */
    vector<vector<int>> ub_add(N * N + 1);
    for (int i = 0; i < N; i++){
      for (int j = 1; j <= i; j++){
        ub_add[j].push_back(i);
      }
      for (int j = x[i]; j < x[i] + N - i; j++){
        ub_add[j].push_back(i);
      }
    }
    /*
    for (int i = 0; i <= N * N; i++){
      cout << i << ": ";
      for (int j : ub_add[i]){
        cout << j;
      }
      cout << endl;
    }
    */
    vector<int> ans(N * N, 0);
    vector<int> lb(N, 0);
    vector<int> ub(N, 0);
    vector<int> cnt(N, 0);
    for (int i = 0; i < N * N; i++){
      for (int j : lb_add[i + 1]){
        lb[j]++;
      }
      for (int j : ub_add[i + 1]){
        ub[j]++;
      }
      bool update = false;
      for (int j = 0; j < N; j++){
        if (cnt[j] < lb[j]){
          cnt[j]++;
          ans[i] = j + 1;
          update = true;
          break;
        }
      }
      if (update){
        continue;
      }
      for (int j = 0; j < N; j++){
        if (cnt[j] + 1 <= ub[j]){
          cnt[j]++;
          ans[i] = j + 1;
          break;
        }
      }
    }
    for (int i = 0; i < N * N; i++){
      if (ans[i] <= 0 || ans[i] > N){
        ok = false;
      }
    }
    if (!ok){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
      for (int i = 0; i < N * N; i++){
        cout << ans[i];
        if (i < N * N - 1){
          cout << ' ';
        }
      }
      cout << endl;
    }
  }
}

