int main()
{
	int n;
	scanf("%d", &n);
	FOR(i, n)
	{
		amount[i+1] = i;
		left[i+1] = n;
		int tmp;
		scanf("%d", &tmp);
		pos[i] = Int(tmp, i+1);
	}
	sort(pos, pos + n);
	int cur = 0;
	int next = 0;
	int fin = 1;
	FOR(i, n*n)
	{
		assert(cur < n);
		if(cur < n)
		{
			if(pos[cur].v == i+1)
			{
				if(amount[pos[cur].i])
				{
					printf("No\n");
					return 0;
				}
				seq[i] = pos[cur].i;
				++cur;
			}
			else
			{
				while(next < n && amount[pos[next].i] <= 0)
					++next;
				if(next < n)
					seq[i] = pos[next].i;
				else
				{
					while(fin < n && left[fin] == 0)
						++fin;
					assert(left[fin] > 0);
					seq[i] = fin;
				}
			}
		}
		--left[seq[i]];
		--amount[seq[i]];
		//printf("%d %d %d\n", seq[i], cur, next);
	}
	printf("Yes\n");
	FOR(i, n*n)
		printf("%d ", seq[i]);
