void solve() {
  ini(N);
  vl x(N);
  in(x);
  each(n, x) n--;
  vl ans(N * N);
  rep(i, N) { ans[x[i]] = i + 1; }
  auto ord =
      mkord(N, [&](int a, int b) { return x[a] - (a + 1) < x[b] - (b + 1); });
  int idx = 0;
  each(i, ord) {
    // i+1をi個左から埋める
    rep(_, i) {
      while (ans[idx] != 0) idx++;
      ans[idx++] = i + 1;
    }
    if (idx > x[i]) die("No");
    ans[x[i]] = i + 1;
  }

  ord = mkord(N, [&](int a, int b) { return x[a] + N - a > x[b] + N - b; });
  idx = N * N - 1;
  // 逆から
  each(i, ord) {
    // i+1をN-i-1個左から埋める
    rep(__, N - i - 1) {
      while (ans[idx] != 0) idx--;
      ans[idx--] = i + 1;
    }
    if (idx < x[i]) die("No");  
  }

  rep(i, N * N) if (ans[i] == 0) die("No");
  out("Yes");
  out(ans);
}

