#include <cstdio>
#include <cstdlib>
using namespace std;

const int MAXN = 505;

int N;
int x[MAXN];
int down[MAXN], up[MAXN];
bool bio[MAXN * MAXN];
int sol[MAXN * MAXN];
int occ[MAXN];

void load() {
	scanf("%d", &N);
	for (int i = 1; i <= N; i++)
		scanf("%d", x + i);	
}

void bye() {
	puts("No");
	exit(0);
}

bool check() {
	for (int i = 1; i <= N * N; i++) 
		if (++occ[sol[i]] == sol[i] && i != x[sol[i]])
			return false;

	for (int i = 1; i <= N; i++)
		if (occ[i] != N)
			return false;

	return true;
}

void solve() {
	for (int i = 1; i <= N; i++) {
		down[i] = i - 1;
		up[i] = N - i;
		bio[x[i]] = true;
		sol[x[i]] = i;
	}

	for (int i = 1; i <= N * N; i++) {
		if (bio[i]) 
			continue;
		int mini = MAXN * MAXN, who = 0;
		for (int j = 1; j <= N; j++)
			if (down[j] && x[j] < mini) {
				mini = x[j];
				who = j;
			}
		if (!who)
			break;
		if (i >= x[who])
			bye();
		sol[i] = who;
		bio[i] = true;
		down[who]--;
	}

	for (int i = N * N; i; i--) {
		if (bio[i])
			continue;
		int maks = 0, who = 0;
		for (int j = 1; j <= N; j++)	
			if (up[j] && x[j] > maks) {
				maks = x[j];
				who = j;
			}
		if (!who)
			break;
		if (i <= x[who])
			bye();
		sol[i] = who;
		bio[i] = true;
		up[who]--;
	}

	if (!check())
		bye();

	puts("Yes");
	for (int i = 1; i <= N * N; i++)
		printf("%d ", sol[i]);
	puts("");
}

int main() {
	load();
	solve();
	return 0;
}

