	vector<int> ans(N*N);
	bool ok = true;
	vector<pair<int,int>> a;
	for (int i = 0; i < N; ++ i) a.push_back({X[i], i+1});
	for (auto p : a) {
		int xi = p.first;
		int i = p.second;
		ans[xi-1] = i;
		int k = 0;
		for (int j = 1; j < i; ++ j) {
			for (;;) {
				if (k >= xi-1) {
					ok = false;
					goto out;
				}
				if (ans[k] == 0) break;
				++ k;
			}
			ans[k] = i;
		}
	}
	for (auto p : a) {
		int xi = p.first;
		int i = p.second;
		int k = xi;
		for (int j = i; j < N; ++ j) {
			for (;;) {
				if (k >= ans.size()) {
					ok = false;
					goto out;
				}
				if (ans[k] == 0) break;
				++ k;
			}
			ans[k] = i;
		}
