int main() {
	int n;
	cin >> n;
	vector<pair<int, int>> X;
	for (int i = 1; i <= n; i++) {
		int a;
		cin >> a;
		X.push_back(pair<int, int>(a, i));
	}
	sort(X.begin(), X.end());
	int t = 0;
	for (int i = 0; i < X.size(); i++) {
		int a = X[i].first;
		int j = X[i].second;
		t += j;
//		cout << a << " " << t << endl;
		if (a < t) {
			cout << "No" << endl;
			return 0;
		}
	}
	vector<int> ans(n*n, -1); 
	stack<int> amari;
	int pans = 0;
	for (int i = 0; i < X.size(); i++) {
		int a = X[i].first; a--;
		int j = X[i].second;
		ans[a] = j;
		for (int k = 0; k < j - 1; k++) {
			while (ans[pans] != -1) {
				pans++;
			}
			ans[pans] = j;
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j < n - i; j++) {
			amari.push(i);
		}
	}
	pans = 0;
	while (pans < n*n) {
		if (ans[pans] != -1) {
			pans++;
			continue;
		}
		int x = amari.top(); amari.pop();
		ans[pans] = x;
	}
	cout << "Yes" << endl;
	for (int i = 0; i < ans.size(); i++) {
		if (i > 0)cout << " ";
		cout << ans[i];
	}
	cout << endl;
	return 0;
}

