struct S {
	int pos, i, num;
	bool operator < (const S& s) const {
		return pos < s.pos;
	}
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	memset(a, -1, sizeof a);
	vector<S> l, r;
	for(int i = 0; i < N; i++) {
		cin >> x[i];
		x[i]--;
		a[x[i]] = i;
		r.push_back(S{ x[i], i, N - i - 1 });
		l.push_back(S{ x[i], i, i });
	}
	sort(r.rbegin(), r.rend());
	sort(l.begin(), l.end());
	int left = 0, right = N * N - 1;
	for(int i = 0; i < N; i++) {
		{
			S ls = l[i];
			int rem = ls.num;
			while(rem) {
				if(left == ls.pos) {
					cout << "No" << endl;
					return 0;
				}
				if(a[left] != -1) {
					left++;
					continue;
				}
				a[left] = ls.i;
				left++;
				rem--;
			}
		}
		{
			S rs = r[i];
			int rem = rs.num;
			while(rem) {
				if(right == rs.pos) {
					cout << "No" << endl;
					return 0;
				}
				if(a[right] != -1) {
					right--;
					continue;
				}
				a[right] = rs.i;
				right--;
				rem--;
			}
		}

	}

	cout << "Yes" << endl;
	for(int i = 0; i < N * N; i++) {
		cout << a[i] + 1;
		if(i == N * N - 1) cout << endl;
