class dsu {
 public:
  int n;
  vector<int> parent;

  dsu(int _n) : n(_n) {
    parent.resize(n);
    iota(parent.begin(), parent.end(), 0);
  }

  int find(int x) {
    if (x == -1 || x == n || x == parent[x]) {
      return x;
    }
    return parent[x] = find(parent[x]);
  }

};

