const int MAXN = 505, SIZE = MAXN * MAXN;

int N;
Pii X[MAXN];

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(X[i].x);
        X[i].y = i;
    }
}

void solve()
{
    std::sort(X + 1, X + N + 1);

    static int A[SIZE];

    for (int i = 1; i <= N; ++i) {
        A[X[i].x] = X[i].y;
    }
    for (int i = 1, j = 1; i <= N; ++i) {
        for (int k = 1; k < X[i].y; ++k) {
            while (A[j]) {
                ++j;
            }
            A[j] = X[i].y;
        }
        if (j > X[i].x) {
            puts("No");
            return;
        }
    }
    for (int i = N, j = N * N; i >= 1; --i) {
        for (int k = N; k > X[i].y; --k) {
            while (A[j]) {
                --j;
            }
            A[j] = X[i].y;
        }
        if (j < X[i].x) {
            puts("No");
            return;
        }
    }

    puts("Yes");
    for (int i = 1; i <= N * N; ++i) {
        printf("%d ", A[i]);
    }
    puts("");
}

