using namespace std;

typedef long long ll;
typedef pair<int, int> Pii;

const int N_MAX = 500;

vector<Pii> v(N_MAX+1, Pii(0, 0));

vector<int> construct(int n) {
    vector<int> ret(n*n+1, 0);
    sort(v.begin(), v.begin()+n+1);
    int i = 1;
    for(int j=1;j<=n;++j) {
        int idx = v[j].first;
        int num = v[j].second;
        ret[idx] = num;
        for(int k=1;k<num;++k) {
            while(i <= idx && ret[i]) ++i;
            if(i > idx) return ret;
            ret[i] = num;
        }
        // for(int k=1;k<=n*n;++k) {
        //     cerr << ret[k] << " ";
        // }
        // cerr << endl;
    }

    int j = n;
    int num = v[j].second;
    int num_cnt = n - num;
    for(int i=1;i<=n*n;++i) {
        if(!num_cnt) {
            --j;
            num = v[j].second;
            num_cnt = n - num;
        }
        if(ret[i]) continue;
        if(i < v[j].first) return ret;
        ret[i] = num;
        --num_cnt;
    }
    ret[0] = 1;
    return ret;
}

