bool check(int n) {
    for(int i=1;i<=n*n;++i) {
        if(i < cnt_l[i] || n*n-i+1 < cnt_r[i]) {
            return false;
        }
    }
    return true;
}

vector<int> construct(int n) {
    vector<int> ret(n*n+1, 0);
    sort(v.begin(), v.begin()+n+1);
    int i = 1;
    for(int j=1;j<=n;++j) {
        int idx = v[j].first;
        int num = v[j].second;
        ret[idx] = num;
        for(int k=1;k<num;++k) {
            while(ret[i]) ++i;
            ret[i] = num;
        }
    }

    i = 1;
    for(int num=1;num<n;++num) {
        for(int k=0;k<n-num;++k) {
            while(ret[i]) ++i;
            ret[i] = num;
        }
    }

    return ret;
}

