using namespace std;

int n,i,j,ans[1000005],cnt[505];
pair <int, int> a[505];
queue <int> ok;

int main(){
	scanf("%d", &n);
	for(i = 1; i <= n; i++){
		scanf("%d", &a[i].first);
		a[i].second = i;
		ans[a[i].first] = i;
		cnt[i]++;
	}
	sort(a + 1, a + 1 + n);

	int p = 1;

	for(i = 1; i <= n * n; i++){

		while(p <= n && cnt[a[p].second] == a[p].second)
		p++;


		if(p <= n && i == a[p].first) return 0 * printf("No\n");

		if(p <= n && ans[i] == 0){
			int id = a[p].second;
			ans[i] = id;
			cnt[id]++;
		}
	}

	p = 1;

	for(i = 1; i <= n * n; i++){
		int id = a[p].second;
		if(a[p].first == i){
			ok.push(id);
			p++;
		}

		if(ans[i] != 0) continue;

		while(ok.size() && cnt[ok.front()] == n)
		ok.pop();

		if(ok.empty())
		return 0 * printf("No\n");

		ans[i] = ok.front();
		cnt[ok.front()]++;
	}

	printf("Yes\n");
	for(i = 1; i <= n * n; i++){
		if(i == 1)
		printf("%d", ans[i]);
		else
