#define F(i, a, b) for (int i = (a), _b = (b); i <= _b; i++)
int rd() {
	int f = 1; char c = getchar(); for (; !isdigit(c); c = getchar()) if (c == '-') f = -1;
	int x = 0; for (; isdigit(c); c = getchar()) x = x*10+c-'0'; return x*f;
}

const int N = 300000;

int n;
struct R {
	int i, x;
	friend int operator < (R a, R b) { return a.x < b.x; }
}r[N];
int a[N], m;

void run() { for (m++; a[m] > 0; m++); }

int main() {
	n = rd();
	F(i, 1, n) {
		int x = rd();
		r[i] = (R){i, x};
		a[x] = i;
	}
	sort(r+1, r+n+1);

	F(c, 1, n) {
		int i = r[c].i, x = r[c].x;
		F(j, 1, i-1)
			run(), a[m] = i;
		if (m > x) return puts("No"), 0;
	}

	run();
	F(c, 1, n) {
		int i = r[c].i, x = r[c].x;
		if (m < x) return puts("No"), 0;
		F(j, i+1, n)
			a[m] = i, run();
	}
	m--;

	puts("Yes");
	F(i, 1, m) printf("%d ", a[i]); puts("");

	return 0;
}

