using namespace std;

const int N = 555;

int n, x[N], a[N * N];
int ptr = 1;

int go(int times, int who) {
	int first = -1;
	for (int i = 0; i < times; i++) {
		while (a[ptr] != -1) ptr++;
		a[ptr] = who;
		if (first == -1) first = ptr;
	}
	return first;
}

int main() {
	scanf("%d", &n);
	vector<pair<int, int> > pos;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &x[i]);
		pos.push_back({x[i], i});
	}
	fill(a + 1, a + n * n + 1, -1);
	sort(pos.begin(), pos.end());
	for (auto p : pos) {
		int where = p.first, who = p.second;
		go(who - 1, who);
		if (a[where] != -1) {
			// printf("%d %d\n", where, who);
			puts("No");
			return 0;
		}
		a[where] = who;
	}
	for (auto p : pos) {
		int where = p.first, who = p.second;
		if (n - who && go(n - who, who) < where) {
			puts("No");
			return 0;
		}
	}
	puts("Yes");
	for (int i = 1; i <= n * n; i++) {
		printf("%d%c", a[i], "\n "[i < n * n]);
	}
	return 0;
}

