const int N=505;
struct data{
	int x,id,now;
}a[N],b[N];
bool cmp(data a,data b){
	return a.x==b.x?a.id>b.id:a.x<b.x;
}
int n,tot,now,x[N*N];
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d",&a[i].x);
		a[i].id=i;
	}
	sort(a+1,a+n+1,cmp);
	for(int i=1;i<=n;i++){
		while(a[i].now<a[i].id-1){
			now++;
			if(x[now]){
				continue;
			}
			tot++;
			x[now]=a[i].id;
			a[i].now++;
		}
		if(now>=a[i].x){
			puts("No");
			return 0;
		}
		tot++;
		x[a[i].x]=a[i].id;
		a[i].now++;
	}
	int now=n*n+1;
	while(tot!=n*n){
		int tmp=tot;
		for(int i=1;i<=n;i++){
			if(a[i].x<now&&a[i].now<n){
				while(a[i].now<n){
					now--;
					if(x[now]){
						continue;
					}
					tot++;
					x[now]=a[i].id;
					a[i].now++;
				}
			}
		}
		if(tmp==tot){
			puts("No");
			return 0;
		}
	}
	puts("Yes");
	for(int i=1;i<=n*n;i++){
		printf("%d ",x[i]);
	}
	puts("");
	return 0;
}

#include <algorithm>
#include <iostream>
#include <map>
#include <vector>

using namespace std;

constexpr static int MAXN = 500;
int n;
int x[MAXN];
int a[MAXN * MAXN];
int cnt[MAXN];

bool solve() {
    for (int k = 0; k < n * n; k++)
        a[k] = -1;

    vector <pair <int, int>> c;
    for (int i = 0; i < n; i++) {
        a[x[i] - 1] = i;
        c.push_back({x[i] - 1, i});
    }
    sort(c.begin(), c.end());

    vector <int> use;
    for (auto p : c) {
        int i = p.second;
        for (int j = 0; j < i; j++)
            use.push_back(i);
    }

    int idx = 0;
    for (int k = 0; k < n * n; k++) {
        if (a[k] != -1) {
            int i = a[k];
            if (cnt[i] < i)
                return false;
            for (int j = 0; j < n - i - 1; j++)
                use.push_back(i);
            continue;
        }

        if (idx == use.size())
            return false;

        a[k] = use[idx++];
        cnt[a[k]]++;
    }
    return true;
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> x[i];

    if (solve()) {
        cout << "Yes" << endl;
        for (int k = 0; k < n * n; k++)
            cout << a[k] + 1 << " ";
        cout << endl;
    }
    else {
        cout << "No" << endl;
    }
}

