auto soln() {
    int n = scan<int>();
    auto x = scan<int>(n, 1);
    vector<pair<int, int> > y(n + 1);
    for (int i = 1; i <= (int)(n); ++i) y[i] = {x[i], i};
    vector<int> order(n + 1);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int i, int j) {return x[i] < x[j];});
    int m = n*n;
    vector<int> res(m + 1);
    int left=1, right=m;
    for(int i = 1; i <= n; ++i) { res[x[i]] = i; }
    for(int p = 1; p <= n; ++p) {
        int i = order[p];
        int cntl = i-1;
        while(cntl) {
            if(left >= x[i]) { ;; return cout << "No" << "\n", 0;}
            if(!res[left]) res[left++] = i, cntl--;
            else left++;
        }
    }
    for(int p = n; p >= 1; --p) {
        int i = order[p];
        int cntr = n - i;
        while(cntr) {
            if(right <= x[i]) { ;; return cout << "No" << "\n", 0; }
            if(!res[right]) res[right--] = i, cntr--;
            else right--;
        }
    }
    cout << "Yes" << "\n";
    for(int i = 1; i <= m; ++i) {
        cout << res[i] << " \n"[i == m];
    }
    return 0;
}
signed main() {
    int t = 1;
    ios_base::sync_with_stdio(false), cin.tie(NULL), cout.tie(NULL);
    while (t--)
        soln();
    return 0;
}

