      return 0;
    }
  }
  vector<vector<int>> m(N, vector<int>(N * N + 1, -1));
  for (int i = 0; i < N; i++){
    m[i][0] = 0;
    m[i][N * N] = N;
  }
  for (int i = 0; i < N; i++){
    m[i][x[i] - 1] = i;
    m[i][x[i]] = i + 1;
  }
  for (int i = 0; i < N; i++){
    for (int j = 1; j < N * N; j++){
      if (m[i][j] == -1){
        m[i][j] = m[i][j - 1];
      }
    }
  }
  for (int i = 0; i < N; i++){
    for (int j = N * N; j >= 1; j--){
      if (m[i][j - 1] < m[i][j] - 1){
        m[i][j - 1] = m[i][j] - 1;
      }
    }
  }
  vector<vector<int>> M(N, vector<int>(N * N + 1, -1));
  for (int i = 0; i < N; i++){
    M[i][0] = 0;
    M[i][N * N] = N;
  }
  for (int i = 0; i < N; i++){
    M[i][x[i] - 1] = i;
    M[i][x[i]] = i + 1;
  }
  for (int i = 0; i < N; i++){
    for (int j = N * N - 1; j >= 1; j--){
      if (M[i][j] == -1){
        M[i][j] = M[i][j + 1];
      }
    }
  }
  for (int i = 0; i < N; i++){
    for (int j = 0; j < N * N; j++){
      if (M[i][j + 1] > M[i][j] + 1){
        M[i][j + 1] = M[i][j] + 1;
      }
    }
  }
