  for (int i = 0; i < N; i++){
    for (int j = 0; j <= N * N; j++){
      cout << m[i][j] << ' ';
    }
    cout << endl;
  }
  cout << endl;
  for (int i = 0; i < N; i++){
    for (int j = 0; j <= N * N; j++){
      cout << M[i][j] << ' ';
    }
    cout << endl;
  }
  cout << endl;
  */
  vector<int> ms(N * N + 1, 0);
  for (int i = 0; i < N; i++){
    for (int j = 0; j <= N * N; j++){
      ms[j] += m[i][j];
    }
  }
  vector<int> Ms(N * N + 1, 0);
  for (int i = 0; i < N; i++){
    for (int j = 0; j <= N * N; j++){
      Ms[j] += M[i][j];
    }
  }
  /*
  for (int i = 0; i <= N * N; i++){
    cout << ms[i] << ' ';
  }
  cout << endl;
  for (int i = 0; i <= N * N; i++){
    cout << Ms[i] << ' ';
  }
  cout << endl;
  */
  bool ok = true;
  for (int i = 0; i <= N * N; i++){
    if (ms[i] > i || Ms[i] < i){
      ok = false;
    }
  }
  if (!ok){
    cout << "No" << endl;
  } else {
    cout << "Yes" << endl;
    vector<int> ans(N * N);
    vector<int> cnt(N, 0);
    for (int i = 0; i < N * N; i++){
      bool update = false;
      for (int j = 0; j < N; j++){
        if (cnt[j] < m[j][i + 1]){
          cnt[j]++;
          ans[i] = j + 1;
          update = true;
          break;
