    for(int i=n;i>=1;i--){
        int id=q[i].id;
        for(int j=n*n;j>q[i].x;j--){
            if(cnt[id]>=n)break;
            if(!a[j])a[j]=id,++cnt[id];
        }
        if(cnt[id]<n)flag=1;
    }
    if(flag){puts("No");return 0;}
    puts("Yes");
