bool solve() {
    int idx = 0;
    REP (i, N) {
        int num = X[i].second, pos = X[i].first-1;
        REP (n, num-1) {
            while (idx < N*N && ans[idx] != 0) idx++;
            if (idx > pos) return false;
            ans[idx] = num;
        }
    }

    idx = N*N-1;
    REPR (i, N) {
        int num = X[i].second, pos = X[i].first-1;
        REP (n, N-num) {
            while (idx >= 0 && ans[idx] != 0) idx--;
            if (idx < pos) return false;
            ans[idx] = num;
        }
    }

    return true;
}

