        cin>>S[i].first;
        S[i].first--;
        S[i].second=i;
        A[S[i].first]=i+1;
    }

    sort(all(S));

    bool ok=true;
    int right=0;

    for(int i=0;i<N;i++){
        int a=S[i].first,b=S[i].second,cnt=0;
        int start=right;
        for(int j=start;j<a;j++){
