using namespace std;

typedef pair<int,int>P;

const int MAX_N = 500;

P x[MAX_N];
int a[250000];

int main()
{
	int n,xx;
	bool flag = false;
	scanf("%d",&n);
	for(int i=0;i<n;i++){
		scanf("%d",&xx);
		x[i].first = xx-1;
		x[i].second = i;
	}
	sort(x,x+n);
	int fir,sec,cur=0;
	fill(a,a+n*n,0);
	for(int i=0;i<n;i++){
		fir = x[i].first;
		sec = x[i].second;
		if(a[fir] == 0){
			a[fir] = sec+1;
		}else{
			flag = true;
			break;
		}
		int m = 0;
		while(m < sec){
			if(cur > fir){
				flag = true;
				break;
			}
			if(a[cur] == 0){
				a[cur] = sec+1;
				cur++;
				m++;
			}else{
				cur++;
			}
		}
		if(flag == true){
			break;
		}
	}
	if(flag == false){
		cur = n*n-1;
		for(int i=n-1;i>=0;i--){
			fir = x[i].first;
			sec = x[i].second;
			int m = 0;
			while(m < n-1-sec){
				if(cur < fir){
					flag = true;
					break;
				}
				if(a[cur] == 0){
					a[cur] = sec+1;
					cur--;
					m++;
				}else{
					cur--;
				}
			}
			if(flag == true){
				break;
			}
		}
	}
	if(flag == true){
		cout << "No";
	}else{
		cout << "Yes" << "\n";
		for(int i=0;i<n*n-1;i++){
			cout << a[i] << " ";
		}
		cout << a[n*n-1];
	}
}

