		int p, i; tie(p, i) = q.top();
		if(k < p) NOSOL;
		w[k] = i;
		if(--cnt[i] == 0) q.pop();
		if(q.empty()) break;
	}
	if(!q.empty()) NOSOL;
	puts("Yes");
	for(int i = 1; i <= n * n; ++i) 
		printf("%d%c", w[i], " \n"[i==n*n]);
	return 0;
}

