using namespace std;

class flow_graph {
 public:
  int n, s, t;
  struct edge {
    int to;
    int f;
    int c;
    int rev;
  };
  vector<vector<edge>> g;
  vector<int> d;
  vector<int> ptr;
  int flow;

  flow_graph(int _n, int _s, int _t) : n(_n), s(_s), t(_t) {
    g.resize(n);
    d.resize(n);
    ptr.resize(n);
    flow = 0;
  }

  void add_edge(int from, int to, int fw_cap, int bw_cap = 0) { 
    int from_size = (int) g[from].size();
    int to_size = (int) g[to].size();
    g[from].push_back({to, 0, fw_cap, to_size});
    g[to].push_back({from, 0, bw_cap, from_size});
  }

  bool found_path() {
    fill(d.begin(), d.end(), -1);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for (edge& e : g[v]) {
        if (d[e.to] == -1 && e.c - e.f > 0) {
          d[e.to] = d[v] + 1;
          if (e.to == t) {
            return true;
          }
          q.push(e.to);
        }
      }
    }
    return false;
  }

  int dfs(int v, int w) {
    if (v == t) {
      return w;
    }
    int& j = ptr[v];
    while (j >= 0) {
      edge& e = g[v][j];
      if (e.c - e.f > 0 && d[e.to] == d[v] + 1) {
        int ret = dfs(e.to, min(w, e.c - e.f));
        if (ret > 0) {
          e.f += ret;
          g[e.to][e.rev].f -= ret;
          return ret;
        }
      }
      j--;
    }
    return 0;
  }

  int max_flow() {
    while (found_path()) {
      for (int i = 0; i < n; i++) {
        ptr[i] = (int) g[i].size() - 1;
      }
      int big_add = 0;
      while (true) {
        int add = dfs(s, numeric_limits<int>::max());
        if (add == 0) {
          break;
        }
        big_add += add;
      }
      if (big_add == 0) {
        break;
      }
      flow += big_add;
    }
    return flow;
  }
};

