struct Coord
{
	int x, y;
	Coord(int x = 0, int y = 0) : x(x), y(y) {}
	Coord operator + (const Coord& droite) const
	{
		return Coord(x + droite.x, y + droite.y);
	}
};

struct AB
{
	int k;
	vector<lli> arbre;
	AB(int _k = 20, lli def = 0)
	{
		k = _k;
		FOR(i, 1 << k)
			arbre.push_back(i < (1 << (k-1)) ? 0LL : def);
		FORD(i, ((1 << (k-1)) - 1), 1)
			arbre[i] = arbre[i << 1] + arbre[(i << 1) ^ 1];
	}
	void set(int i, lli x)
	{
		int feuille = i + (1 << (k-1));
		arbre[feuille] = x;
		iset(feuille >> 1);
	}
	void iset(int noeud)
	{
		if(noeud)
		{
			arbre[noeud] = arbre[noeud << 1] + arbre[(noeud << 1)  ^ 1];
			iset(noeud >> 1);
		}
	}
	lli sum(int deb, int fin, int noeud = 1, int p = 0, int q = -1)
	{
		if(q < p)
			q = 1 << (k-1);
		if(deb <= p && q <= fin)
			return arbre[noeud];
		if(deb >= q || fin <= p)
			return 0LL;
		int mil = (p + q) / 2;
		return sum(deb, fin, noeud << 1, p, mil) + sum(deb, fin, (noeud << 1) ^ 1, mil, q);
	}
};

struct Int
{
	int v;
	int i;
	Int(int v = 0, int i = 0) : v(v), i(i) {}
	bool operator < (const Int& droite) const
	{
		if(v != droite.v)
			return v < droite.v;
		return i < droite.i;
	}
};

const int MAX_N = 500+42;

Int pos[MAX_N];
int amount[MAX_N];
int seq[MAX_N * MAX_N];
int left[MAX_N];

int main()
{
	int n;
	scanf("%d", &n);
	FOR(i, n)
	{
		amount[i+1] = i;
		left[i+1] = n;
		int tmp;
		scanf("%d", &tmp);
		pos[i] = Int(tmp, i+1);
	}
	sort(pos, pos + n);
	int cur = 0;
	int next = 0;
	int fin = 1;
	FOR(i, n*n)
	{
		assert(cur < n);
		if(cur < n)
		{
			if(pos[cur].v == i+1)
			{
				if(amount[pos[cur].i])
				{
					printf("No\n");
					return 0;
				}
				seq[i] = pos[cur].i;
				++cur;
			}
			else
			{
				while(next < n && amount[pos[next].i] <= 0)
					++next;
				if(next < n)
					seq[i] = pos[next].i;
				else
				{
					while(fin < n && left[fin] == 0)
						++fin;
					assert(left[fin] > 0);
					seq[i] = fin;
				}
			}
		}
		--left[seq[i]];
		--amount[seq[i]];
		//printf("%d %d %d\n", seq[i], cur, next);
	}
	FOR(i, n*n)
		printf("%d ", seq[i]);
	printf("\n");
	return 0;
}

