  for (int i = 0; i < N * N; i++){
    for (int j : lb_add[i + 1]){
      lb[j]++;
    }
    for (int j : ub_add[i + 1]){
      ub[j]++;
    }
    int upd_cnt = 0;
    for (int j = 0; j < N; j++){
      if (cnt[j] < lb[j]){
        cnt[j]++;
        ans[i] = j + 1;
        upd_cnt++;
      }
    }
    if (upd_cnt >= 2){
      ok = false;
      break;
    }
    if (upd_cnt == 1){
      continue;
    }
    for (int j = 0; j < N; j++){
      if (cnt[j] + 1 <= ub[j]){
        cnt[j]++;
        ans[i] = j + 1;
        break;
      }
    }
    if (ans[i] == 0){
      ok = false;
      break;
    }
  }
