        ok = false;
      }
      int cnt = 0;
      for (int j = 0; j < x[i]; j++){
        if (ans[j] == i + 1){
          cnt++;
        }
      }
      if (cnt != i + 1){
        ok = false;
      }
    }
    if (!ok){
      cout << "No" << endl;
      return 0;
    }
    cout << "Yes" << endl;
    for (int i = 0; i < N * N; i++){
      cout << ans[i];
      if (i < N * N - 1){
        cout << ' ';
      }
    }
    cout << endl;
  }
}

