char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && ch != '-') ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 505;
struct Node { int pos, id; } t[MAXN];
int ans[MAXN * MAXN];
int pre[MAXN * MAXN], nxt[MAXN * MAXN];

inline bool cmp(Node x, Node y) { return x.pos < y.pos; }

inline void Put(int pos, int num, int cnt) {
  for (RI i = nxt[0]; i <= pos && i && cnt; i = nxt[i]) {
    ans[i] = num, --cnt;
    nxt[pre[i]] = nxt[i];
    pre[nxt[i]] = pre[i];
  }
  if (cnt) Cannot;
}

int main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n; cin >> n;
  for (RI i = 1; i <= n; ++i)
    scanf("%d", &t[i].pos), t[i].id = i;
  sort(t + 1, t + 1 + n, cmp);
  for (RI i = 1; i <= n * n; ++i)
    nxt[i - 1] = i, pre[i] = i - 1;
  pre[0] = n * n;
  for (RI i = 1; i <= n; ++i) {
    nxt[pre[t[i].pos]] = nxt[t[i].pos];
    pre[nxt[t[i].pos]] = pre[t[i].pos];
  }
  for (RI i = 1; i <= n; ++i) {
    ans[t[i].pos] = t[i].id;
    Put(t[i].pos, t[i].id, t[i].id - 1);
  }
  int now = nxt[0];
  for (RI i = 1; i <= n; ++i) {
    int res = n - t[i].id;
    while (res) {
      if (now <= t[i].pos) Cannot;
      ans[now] = t[i].id, --res;
      now = nxt[now];
    }
  }
  puts("Yes");
  for (RI i = 1; i <= n * n; ++i)
    printf("%d ", ans[i]);

  return 0;
}

