			add(qy, n - pos[top].Y, pos[top].Y);
			if(++top <= n) add(qx, pos[top].Y - 1, pos[top].Y); 
		} else {
			if(qx.empty() == false) ans[i] = qx.front(), qx.pop();
			else if(qy.empty() == false) ans[i] = qy.front(), qy.pop();
			else return puts("No") * 0;
		}
	}
	puts("Yes");
	for(int i = 1; i <= n * n; i ++) 
		printf("%d%c", ans[i], i == n * n ? '\n' : ' ');

}

