vector<int> solve(vector<int> x) {
	int n = x.size();
	vector<pair<int, int> > a(n);
	for (int i = 0; i < n; i++) {
		a[i] = make_pair(x[i], i);
	}
	sort(a.begin(), a.end());

	vector<int> ans;
	vector<int> canUse;
	vector<int> cnt(n, 0);
	int j = 0, k = 0;
	if (a[k].second == 0) k++;
	for (int i = 0; i < n * n; i++) {
		if (j < n && i == a[j].first) {
			int x = a[j].second;
			if (cnt[x] != x) return vector<int>();
			ans.push_back(x);
			for (int l = x + 1; l < n; l++) canUse.push_back(l);
			j++;
			continue;
		}
		if (k < n) {
			ans.push_back(a[k].second);
			cnt[a[k].second]++;
			if (cnt[a[k].second] == a[k].second) {
				k++;
			}
			continue;
		}
		if (!canUse.empty()) {
			int x = canUse.back();
			canUse.pop_back();
			ans.push_back(x);
			continue;
		}
		return vector<int>();
	}
	return ans;
}

