            leftn[x - 1].emplace_back(i + 1, i);
        }
    }

    int empt = 0;
    int ptr = 0;
    repeat(i, M) {
        if (ans[i] == 0) ++empt;

        for (auto p : leftn[i]) {
            if (empt < p.second) bye("No");
            for (; p.second; --p.second) {
                while (ans[ptr]) ++ptr;
                ans[ptr] = p.first; --empt;
            }
        }
    }
    empt = 0;
    ptr = M - 1;
    rrepeat(i, M) {
        if (ans[i] == 0) ++empt;

        for (auto p : rightn[i]) {
            if (empt < p.second) bye("No");
            for (; p.second; --p.second) {
                while (ans[ptr]) --ptr;
                ans[ptr] = p.first; --empt;
            }
        }
    }

    printer << "Yes\n";
    repeat(i, M) {
        printer << ans[i] << ' ';
    }
    cout << endl;

    return 0;
}

