using namespace std;

inline int nxt(){
	int n;
	scanf("%d", &n);
	return n;
}

int main(){

	int n = nxt();
	vector<pair<int, int>> x(n);
	int nn = n * n;
	for (int i = 0; i < n; ++i) {
		x[i] = {nxt(), i};
	}
	sort(all(x));

	vector<int> zalupa;
	vector<int> trash;
	for (auto p : x) {
		for (int i = 0; i < p.second; ++i) {
			zalupa.push_back(p.second);
		}
		for (int i = 0; i < n - 1 - p.second; ++i) {
			trash.push_back(p.second);
		}
	}
	reverse(all(trash));

	vector<int> a(nn);
	int index = 0;
	int zi = 0;
	vector<int> last(n);
	for (int i = 0; i < n; ++i) {
		last[i] = i;
	}
	vector<char> used(n);
	for (int i = 0; i < nn; ++i) {
		if (index < n && x[index].first - 1 == i) {
			if (last[x[index].second]) {
				puts("No");
				return 0;
			}
			a[i] = x[index].second + 1;
			used[x[index].second] = 1;
			++index;
		} else {
			if (zi < (int)zalupa.size()) {
				last[zalupa[zi]] -= 1;
				a[i] = zalupa[zi] + 1;
				++zi;
			} else {
				if (!used[trash.back()]) {
					puts("No");
					return 0;
				}
				a[i] = trash.back() + 1;
				trash.pop_back();
			}
		}
	}

	printf("Yes\n");
	for (int i = 0; i < nn; ++i) {
		printf("%d ", a[i]);
	}
	printf("\n");

	return 0;
}

