// #define DEBUG

void solve() {
    int N;
    cin >> N;

    pair<int, int> x[N];
    FOR(i, 0, N) {
        cin >> x[i].fst;
        x[i].snd = i + 1;
    }
    sort(x, x + N);

    ll a[sq(N) + 1], now = 0;
    // now...今a[now]まで埋まっている
    fill(a, a + sq(N) + 1, -1);

    FOR(i, 0, N) {
        int idx, n;
        tie(idx, n) = x[i];
        a[idx] = n;
        FOR(_, 0, n - 1) {
            while (true) {
                if (a[++now] < 0) {
                    a[now] = n;
                    break;
                }
            }
        }

        if (now > idx) {
            cout << "No" << endl;
            return;
        }
    }

    now = sq(N) + 1;
    RFOR(i, 0, N) {
        int idx, n;
        tie(idx, n) = x[i];
        FOR(_, n, N) {
            while (true) {
                if (a[--now] < 0) {
                    a[now] = n;
                    break;
                }
            }
        }

        if (now < idx) {
            cout << "No" << endl;
            return;
        }
    }

    cout << "Yes" << endl;
    FOR(i, 1, sq(N) + 1) {
        cout << a[i] << " ";
    }
    cout << endl;
    return;
}


