const int INF = 1 << 30;
const int MOD = 1e9 + 7;

struct Edge {
  int v, c, cap;
  Edge* nxt;
};

const int C = 500;
const int N = C * C * 3 + C * 2 + 10;
const int M = 4e6 + 10;
Edge* a[N];
Edge pool[M];
Edge* last;

int d[N];

inline Edge* new_edge(int v, int c, Edge* nxt) {
  Edge* p = last++;
  p->v = v;
  p->cap = p->c = c;
  p->nxt = nxt;
  return p;
}

inline void add_edge(int u, int v, int c) {
  a[u] = new_edge(v, c, a[u]);
  a[v] = new_edge(u, 0, a[v]);
}

inline Edge* dual(Edge* p) {
  return pool + ((p - pool) ^ 1);
}

int augment(int u, int t, int bound) {
  if (u == t) return bound;
  int ret = 0;
  for (Edge* it = a[u]; it && ret < bound; it = it->nxt) {
    if (it->c && d[it->v] == d[u] + 1) {
      int aug = augment(it->v, t, min(it->c, bound - ret));
      ret += aug;
      it->c -= aug;
      dual(it)->c += aug;
    }
  }
  if (ret == 0) d[u] = -1;
  return ret;
}

bool path(int s, int t, int n) {
  fill(d, d + n, -1);
  d[s] = 0;
  queue<int> Q;
  Q.push(s);
  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (Edge* it = a[u]; it; it = it->nxt) {
      if (it->c && d[it->v] == -1) {
        Q.push(it->v);
        d[it->v] = d[u] + 1;
        if (it->v == t) return true;
      }
    }
  }
  return false;
}

int dinic(int s, int t, int n) {
  int ret = 0;
  while (path(s, t, n)) {
    while (int aug = augment(s, t, INF)) {
      ret += aug;
    }
  }
  return ret;
}

int pre[N];

int main() {
  int n;
  scanf("%d", &n);
  vector<int> x(n), ret(n * n);
  set<int> X;
  for (int i = 0; i < n; ++i) {
    scanf("%d", &x[i]), --x[i];
    X.insert(x[i]);
    ret[x[i]] = i;
  }
  int s = n * 2 + n * n * 3, t = s + 1;
  int U = n * 2, V = U + n * n, W = V + n * n;
  fill(a, a + t + 1, nullptr);
  last = pool;
  for (int i = 0; i < n; ++i) {
    if (i > 0) add_edge(s, i, i);
    if (n - 1 - i > 0) add_edge(s, i + n, n - 1 - i);
    if (x[i] - 1 >= 0) add_edge(i, U + x[i] - 1, INF);
    if (x[i] + 1 < n * n) add_edge(i + n, V + x[i] + 1, INF);
  }
  for (int i = 0; i < n * n; ++i) {
    add_edge(U + i, W + i, INF);
    add_edge(V + i, W + i, INF);
    if (i - 1 >= 0) add_edge(U + i, U + i - 1, INF);
    if (i + 1 < n * n) add_edge(V + i, V + i + 1, INF);
    if (X.find(i) == X.end()) add_edge(W + i, t, 1);
  }
  if (dinic(s, t, t + 1) != n * (n - 1)) {
    puts("No");
    return 0;
  }
  puts("Yes");
  fill(pre, pre + t + 1, -1);
  queue<int> Q;
  for (int i = 0; i < n * 2; ++i) {
    Q.push(i);
    pre[i] = i;
  }
  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (Edge* it = a[u]; it; it = it->nxt) {
      if (it->cap == it->c) continue;
      if (pre[it->v] >= 0) continue;
      pre[it->v] = pre[u];
      Q.push(it->v);
    }
  }
  for (int i = 0; i < n * n; ++i) {
    int cur = pre[W + i];
    if (cur >= n) cur -= n;
    if (cur >= 0) ret[i] = cur;
  }
  for (int i = 0; i < n * n; ++i) {
    printf("%d%c", ret[i] + 1, " \n"[i + 1 == n * n]);
  }
  return 0;
}

