		Y.push_back({i+1,N-(i+1)});
	}
	for(i=N*N;i>=1;i--) {
		if(T[i]>0) {
			R[i]=T[i];
			if(T[i]>1) V.push_back({T[i],T[i]-1});
		}
		else {
			if(V.size()) {
				R[i]=V.back().first;
				L[V.back().first]--;
				V.back().second--;
				if(V.back().second==0) V.pop_back();
			}
		}
	}
	if(V.size()) return _P("No\n");

	for(i=1;i<=N*N;i++) if(R[i]==0) {
		FOR(x,N) if(X[x+1]<i && L[x+1]) {
			R[i]=x+1;
			L[x+1]--;
			break;
		}
		if(x==N) return _P("No\n",i);
	}
	_P("Yes\n");
	FOR(i,N*N) _P("%d%c",R[i+1],(i==N*N-1)?'\n':' ');

}


