  std::vector<unsigned> ans(N * N + 1);
  for (unsigned i = 0; i < N; ++i) {
    std::cin >> x[i].first;
    x[i].second = i + 1;
  }
  std::sort(x.begin(),
            x.end(),
            [](std::pair<unsigned, unsigned> i, std::pair<unsigned, unsigned> j) -> bool { return i.first < j.first; });
  for (const auto &i : x) {
    used[i.first] = true;
    ans[i.first] = i.second;
  }
  unsigned index = 1u;
  for (unsigned i = 0; i < N; ++i) {
    unsigned cnt = x[i].second - 1;
    for (unsigned j = index; cnt > 0u; ++j) {
      if (used[j]) continue;
      ans[j] = x[i].second;
      --cnt;
      if (cnt == 0u) {
        index = j + 1;
        break;
      }
    }
    if (index > x[i].first) {
      std::cout << "No";
      return 0;
    }
  }
  index = N * N;
  for (unsigned i = N - 1; i-- > 0;) {
    unsigned cnt = N - x[i].second;
    for (unsigned j = index; cnt > 0u; --j) {
      if (used[j]) continue;
      ans[j] = x[i].second;
      --cnt;
      if (cnt == 0u) {
        index = j - 1;
        break;
      }
    }
    if (index < x[i].first) {
