void Main()    {
    int n;
    cin >> n;

    vector<pair<int, int> > x(n);
    for(int i = 0; i < n; i++) {
        cin >> x[i].first;
        x[i].second = i + 1;
    }

    vector<int> arr(n * n + 1, -1);
    sort(x.begin(), x.end());

    for(auto el: x) {
        int num = el.second, pos = el.first;
        arr[pos] = num;
        int toPut = num - 1;
        for(int i = 1; i < pos; i++)    {
            if(arr[i] == -1 and toPut)    {
                arr[i] = num;
                toPut--;
            }
        }  
