            printno();
        } 
    }

    reverse(x.begin(), x.end());
    for(auto el: x) {
        int num = el.second, pos = el.first;
        int toPut = n - num;
        for(int i = n * n; i > pos; i--)    {
            if(arr[i] == -1 and toPut)  {
                arr[i] = num;
                toPut--;
            }
        }
        if(toPut)   {
            printno();
        }
    }

    cout << "Yes\n";
    for(int i = 1; i <= n * n; i++) {
        cout << arr[i] << " ";
    }
    cout << "\n";
}

