    rep(i, n) {
        cin >> x[i];
        ins[i] = make_pair(x[i], i + 1);
    }
    sort(all(ins));
    vector<int> ans(n * n, -1);
    int j = 0;
    rep(i, n) {
        int p = ins[i].fr;
        --p;
        int num = ins[i].sc;
        for(int k = j, cnt = 0; cnt < num - 1;) {
            if(k >= n * n) {
                cout << "No" << endl;
                return;
            }
            if(ans[k] != -1) {
                ++k;
                continue;
            } else {
                ans[k] = ins[i].sc;
                ++k; ++cnt;
                if(cnt == num - 1) {
                    j = k;
                }
            }
        }
        if(ans[p] != -1) {
            cout << "No" << endl;
            return;
        }
        ans[p] = ins[i].sc;
    }
    j = 0;
    for(int i = 1; i <= n; ++i) {
        for(int k = j, cnt = 0; cnt < n - i;) {
            if(k >= n * n) {
                cout << "No" << endl;
                return;
            }
            if(ans[k] != -1) {
                ++k;
                continue;
            } else {
                if(k < x[i - 1]) {
                    ++k;
                    continue;
                }
                ans[k] = i;
                ++k; ++cnt;
                if(cnt == n - i) j = k;
            }
        }
    }
    cout << "Yes" << endl;
    rep(i, n * n) {
        cout << ans[i] << " ";
    }
    cout << endl;
}

