using namespace std;

void Yes(std::vector<int>& answer) {

    cout << "Yes" << endl;
    for (int i = 1; i < (int)answer.size(); i++) {
        cout << answer[i] << " ";
        assert(answer[i] != -1);
    }
    exit(0);
}

void No() {
    cout << "No" << endl;
    exit(0);
}

int main(void) {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n;
    cin >> n;

    std::vector<pair<int, int>> x(n);
    int tmp = 1;
    for (auto& el : x) {
        cin >> el.first;
        el.second = tmp;
        tmp++;
    }
    std::sort(x.begin(), x.end());

    std::vector<int> answer(n * n + 1, -1);
    std::vector<int> counts(n + 1, n);

    int cur = 1;

    for (auto& pr : x) {
        if (answer[pr.first] != -1) {
            No();
        }
        answer[pr.first] = pr.second;
        counts[pr.second]--;
        int cnt = pr.second - 1;
        while (cnt-->0) {
            if (answer[cur] != -1) {
                cur++;
                cnt++;
                continue;
            }
            answer[cur] = pr.second;
            counts[pr.second]--;
            cur++;
        }

        if (cur > pr.first) {
            No();
        }
    }

    for (int i = 1; i <= n; i++) {
        while (counts[i]-->0) {
            if (answer[cur] == -1) {
                answer[cur] = i;
            } else {
                counts[i]++;
            }
            cur++;
        }
    }
    assert(cur = n * n + 1);

    Yes(answer);
}

