			int t=lower_bound(p+1,p+n+1,mp(i,0))-p;
			int k=0;
			rep(j,t,n)
				if(c[p[j].se]){
					k=p[j].se;break;
				}
			if(!k)rep(j,1,n)if(c[j]){
				k=j;break;
			}
			if(!k){
				puts("No");
				return 0;
			}
			ans[i]=k;
			c[k]--;
		}
		else{
			if(c[f[i]]){
				puts("No");
				return 0;
			}
			ans[i]=f[i];
			c[f[i]]=n-f[i];
		}
	puts("Yes");
	rep(i,1,n*n)printf("%d ",ans[i]);
	puts("");
	return 0;
}

