// ll N, vl x
// 条件をすべて満たす数列 a が存在しないならば、No を出力せよ。存在するならば、1 行目に Yes を出力し、2 行目に a を空白区切りで出力せよ。
void solve(){
    vl a(N*N,-1);
    rep(i,N)a[x[i]-1]=i+1;

    queue<ll> reserved;
    rep(i,N*N){
        if(a[i]!=-1)rep(j,1,a[i])reserved.push(a[i]);
    }

    vl ans(N*N);
    vl used(N+1);
    queue<ll> waiting;
    rep(i,N*N){
        if(a[i]==-1){
            if(reserved.size()){
                ll x=reserved.front();reserved.pop();
                if(used[x]){
                    cout<<NO<<endl;
                    return;
                }
                ans[i]=x;
            }else{
                if(waiting.empty()){
                    cout<<NO<<endl;
                    return;
                }
                ll x=waiting.front();waiting.pop();
                ans[i]=x;
            }
        }else{
            ans[i]=a[i];
            used[a[i]]=true;
            rep(j,N-a[i])waiting.push(a[i]);
        }
    }
    cout<<YES<<endl;
    rep(i,N*N){
        if(i>0)cout<<' ';
        cout<<ans[i];
    }
    cout<<endl;
}

