int main() {
    int n;
    in(n);

    auto x = vin<int>(n);
    for (int i : rep(0, n)) {
        x[i]--;
    }

    vector<pair<int, int>> y(n);
    vector<int> ans(n * n, -1);

    for (int i : rep(0, n)) {
        y[i].first = x[i];
        y[i].second = i + 1;

        ans[x[i]] = i + 1;
    }

    sort(y);

    for (auto p : y) {
        int x = p.first;
        int i = p.second;

        int cnt = 0;
        for (int j : rep(0, x)) {
            if (cnt < i - 1 && ans[j] == -1) {
                ans[j] = i;
                cnt++;
            }
        }

        if (cnt != i - 1) {
            out("No");
            return 0;
        }
    }

    boost::reverse(y);

    for (auto p : y) {
        int x = p.first;
        int i = p.second;

        int cnt = 0;
        for (int j : rep(x, n * n)) {
            if (cnt < n - i && ans[j] == -1) {
                ans[j] = i;
                cnt++;
            }
        }

        if (cnt != n - i) {
            out("No");
            return 0;
        }
    }

    vout(ans, n * n);
}

