    return UF1[a] = Find1(UF1[a]);
}
int Find2(int a){
    if(a==UF2[a])return a;
    return UF2[a] = Find2(UF2[a]);
}
void Ins(int a, int b){
    Res[a] = b;
    UF1[a] = Find1(a-1);
    UF2[a] = Find2(a+1);
}
bool Do1(int a, int b, int y){
    int i, x;
    for(i=0;i<b;i++){
        x = Find2(1);
        if(x > a)return false;
        Ins(x, y);
    }
    return true;
}
bool Do2(int a, int b, int y){
    int i, x;
    for(i=0;i<b;i++){
        x = Find1(n*n);
        if(x < a)return false;
        Ins(x, y);
    }
    return true;
}
