int counts[501];
queue<int> que;

int main() {
    cin >> N; for (int j = 0; j < N; ++j) { cin >> X[j]; --X[j]; }
    fill(reqa, reqa+N*N, 0);
    fill(counts, counts+N+1, 0);
    for (int j = 0; j < N; ++j) {
        res[X[j]] = reqa[X[j]] = j+1;
        req[j].first = X[j]; req[j].second = j+1;
    }
