    bool ok = true;
    int idx = 0;
    if (req[0].second == 1) ++idx;
    for (int j = 0; ok && j < N*N; ++j) {
        if (reqa[j] > 0) {
            int num = reqa[j];
            if (++counts[num] < num) {
                ok = false;
            } else {
                for (int n = N-num; n > 0; --n) que.push(num);
            }
        } else if (idx < N) {
            int num = req[idx].second;
            if (counts[num] < num-1) {
                ++counts[num];
                res[j] = num;
            }
            if (counts[num] == num-1) {
                ++idx;
                if (idx < N && req[idx].second == 1) ++idx;
            }
