int main()
{
    int N;
    cin >> N;
    using P = pair<int, int>;
    vector<P> x(N);
    vector<int> ans(N * N, -1);
    bool ok = true;
    for (int i = 0; i < N; i++) {
        int y;
        cin >> y;
        x[i]       = { y - 1, i + 1 };
        ans[y - 1] = i + 1;
    }
    sort(x.begin(), x.end());
    for (int i = 0; i < N; i++) {
        int left = x[i].second - 1;
        for (int j = 0; j < x[i].first and left > 0; j++) {
            if (ans[j] == -1) {
                ans[j] = x[i].second;
                left--;
            }
        }
        if (left > 0) {
            ok = false;
            break;
        }
    }
    reverse(x.begin(), x.end());
    for (int i = 0; i < N; i++) {
        int left = N - x[i].second;
        for (int j = N * N - 1; j > x[i].first and left > 0; j--) {
            if (ans[j] == -1) {
                ans[j] = x[i].second;
                left--;
            }
        }
        if (left > 0) {
            ok = false;
            break;
        }
    }

    if (ok) {
        cout << "Yes" << endl;
        for (int i = 0; i < N * N; i++) {
            if (i != 0) {
                cout << " ";
            }
            cout << ans[i];
        }
        cout << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

