        a[x] = i;
    }
    queue<int> opt;
    for(int i = 1; i <= n*n; i++) {
        if(!a[i]) opt.push(i);
        else {
            int lftCnt = a[i]-1;
            if(opt.size() < lftCnt) {
                cout << "No" << endl;
                return 0;
            }
            while(lftCnt--) {
                int idx = opt.front();
                opt.pop();
                a[idx] = a[i];
