        else {
            if(done[a[i]]) continue;
            done[a[i]] = true;
            int rightCnt = n-a[i];
            if(opt.size() < rightCnt) {
                cout << "No" << endl;
                return 0;
            }
            while(rightCnt--) {
                int idx = opt.front();
                opt.pop();
                a[idx] = a[i];
            }
        }
