int n, x[500], a[500 * 500];
int b[501];

bool solve() {
	inc(i, n) {
		if(a[ x[i] ] != 0) { return false; }
		a[ x[i] ] = i + 1;
	}

	inc(i, n * n) {
		if(a[i] != 0) {
			int j = 0, c = 0;
			while(j < i && c < a[i] - 1) {
				if(a[j] == 0) { a[j] = a[i]; c++; }
				j++;
			}
			if(c < a[i] - 1) { return false; }
		}
	}

	inc(i, n * n) { b[ a[i] ]++; }
	int i = 0, j = 1;
	while(i < n * n) {
		while(i < n * n && a[i] != 0) { i++; }
		if(i == n * n) { break; }
		while(b[j] == n) { j++; }
		a[i++] = j; b[j]++;
	}

	return true;
}

int main() {
	cin >> n;
	inc(i, n) { cin >> x[i]; x[i]--; }

	if(! solve()) { cout << "No" << endl; }
	else {
		cout << "Yes" << endl;
		inc(i, n * n) {
			cout << (i == 0 ? "" : " ") << a[i];
		}
		cout << endl;
	}
}

