bool check(const vector<int>& X, const vector<int>& ans) {
	int N = X.size();
	vector<int> cnt(N);
	for (int i = 0; i < N*N; i++) {
		if (ans[i] == -1) return false;
		if (cnt[ans[i]] == ans[i]) {
			if (X[ans[i]] != i) return false;
		}
		cnt[ans[i]]++;
	}
	for (int i = 0; i < N; i++) {
		if (cnt[i] != N) return false;
	}
	return true;
}

const int MAXN = 555;
const int INF = 1e9;

int need[MAXN*MAXN];
int rest[MAXN];
int yoyu[MAXN];

int main() {
	int N;
	cin >> N;
	vector<int> X(N);
	memset(need, -1, sizeof(need));
	for (int i = 0; i < N; i++) {
		cin >> X[i];
		--X[i];
		need[X[i]] = i;
	}
	for (int i = 0; i < N; i++) {
		if (X[i] < i || X[i] + (N-i) < N) no();
	}
	vector<int> ans(N*N);
	// 最初に入れられる数を入れておく
	for (int i = 0; i < N; i++) {
		rest[i] = i;
		yoyu[i] = i-1-X[i];
	}
	for (int i = 0; i < N*N; i++) {
		if (need[i] != -1) {
			ans[i] = need[i];
			rest[need[i]] += N-need[i]-1;
			yoyu[i] = -INF;
		} else {
			int maxi = -INF-100, index = -1;
			for (int j = 0; j < N; j++) {
				if (maxi < yoyu[j] && rest[j] > 0) {
					index = j;
					maxi = yoyu[j];
				}
			}
			ans[i] = index;
			--rest[index];
			for (int j = 0; j < N; j++) {
				if (j != index) yoyu[j]++;
			}
		}
	}
	if (!check(X, ans)) no();
	cout << "Yes" << endl;
	for (int i = 0; i < N*N; i++) {
		cout << ans[i]+1 ;
		if (i < N*N-1) cout << " ";
	}
	cout << endl;
	return 0;
}

