        a--;
        if (a > 0)v.push_back({a, i + 1});
        if (ret[a] != 0)possible = false;
        ret[a] = i + 1;
    }
    sort(v.begin(), v.end());

    vector<int> extra;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; i + j <= n; j++) {
            extra.push_back(i);
        }
    }
    vector<int> count(n + 1);
    for (int i = 0; i < n; i++)count[i + 1] = i;

    int index = 0;
    for (int i = 0; i < n * n; i++) {
        if (ret[i] != 0) {
            if (count[ret[i]] != 0)possible = false;
            continue;
        }
        while (index < v.size() && count[v[index][1]] <= 0)index++;
        if (index < v.size()) ret[i] = v[index][1], count[v[index][1]]--;
        else ret[i] = extra.back(), extra.pop_back();
    }

    if (possible) {
        cout << "Yes" << endl;
        for (int i = 0; i < n * n; i++) {
            if (i > 0)cout << " ";
            cout << ret[i];
        }
        cout << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

