priority_queue<int, vector<int>, greater<int> > pq;
bool used[N_];

int get() {
	while(!pq.empty()) {
		int t = pq.top();
		if(!used[t]) {
			used[t] = true;
			return t;
		}
		pq.pop();
	}
	return -1;
}

int C[N_];

