int main(void) {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n;
    cin >> n;

    std::vector<pair<int, int>> x(n);
    int tmp = 1;
    for (auto& el : x) {
        cin >> el.first;
        el.second = tmp;
        tmp++;
    }
    std::sort(x.begin(), x.end());

    std::vector<int> answer(n * n + 1, -1);
    std::vector<int> counts(n + 1, n);

    int cur = 1;

    for (auto& pr : x) {
        if (answer[pr.first] != -1) {
            No();
        }
        answer[pr.first] = pr.second;
        counts[pr.second]--;
        int cnt = pr.second - 1;
        while (cnt-->0) {
            if (answer[cur] != -1) {
                cur++;
                cnt++;
                continue;
            }
            answer[cur] = pr.second;
            counts[pr.second]--;
            cur++;
        }

        if (cur > pr.first) {
            No();
        }
    }

    cur = n * n;
    std::reverse(x.begin(), x.end());
    for (auto& pr : x) {
        int i = pr.second;
        while (counts[i]-->0) {
            if (answer[cur] == -1) {
                answer[cur] = i;
            } else {
                counts[i]++;
            }
            cur--;
        }
        if (cur < pr.first) {
            No();
        }

    }
    assert(cur = n * n + 1);

    Yes(answer);
}

