int spec [MAX_N * MAX_N];

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  for (int i = 1; i <= n; i++) {
    cin >> kth[i];
    spec[kth[i]] = i;
  }

  for (int i = 1; i <= n * n; i++) {
    if (spec[i] != 0) {
      arr[i] = spec[i];
      cnt[spec[i]]++;
    } else {
      // find the leftmost spec we aren't ready for
      pair<int, int> cur_spec = make_pair(MAX_N * MAX_N, -1);
      for (int j = 1; j <= n; j++) {
        if (i < kth[j] && cnt[j] < j - 1) {
          cur_spec = min(cur_spec, make_pair(kth[j], j));
        }
      }

      if (cur_spec.second != -1) {
        arr[i] = cur_spec.second;
        cnt[cur_spec.second]++;
      } else {
        // find anything that passed and isn't full
        int cur = -1;
        for (int j = 1; j <= n; j++) {
          if (kth[j] < i && cnt[j] < n) {
            cur = j;
          }
        }

        if (cur != -1) {
          arr[i] = cur;
          cnt[cur]++;
        } else {
          failure();
        }
      }
    }
  }

  cout << "Yes" << endl;
  for (int i = 1; i <= n * n; i++) {
