vector<int> Solve() {
  int n;
  cin >> n;
  vector<int> xs(n);
  vector<pair<int, int>> pos_val_pairs;
  for (int i = 0; i < n; i++) {
    cin >> xs[i];
    xs[i]--;
    pos_val_pairs.push_back({xs[i], i});
  }
  sort(pos_val_pairs.begin(), pos_val_pairs.end());

  vector<int> ys(n * n, -1);
  int cur = 0;
  auto put_fn = [&](int val) {
    while (ys[cur] >= 0) cur++;
    ys[cur] = val;
  };

  for (const auto [pos, val] : pos_val_pairs) {
    for (int i = 0; i < val; i++) {
      put_fn(val);
    }
    if (ys[pos] >= 0) return vector<int>();
    ys[pos] = val;
  }

  cur = 0;
  for (const auto [pos, val] : pos_val_pairs) {
    for (int i = 0; i < n - 1 - val; i++) {
      put_fn(val);
    }
  }

  for (int k = 0; k < n; k++) {
    vector<int> ps;
    for (int i = 0; i < n * n; i++) {
      if (ys[i] == k) {
        ps.push_back(i);
      }
    }
    if (ps[k] != xs[k]) return vector<int>();
  }

  return ys;
}

