                ss.erase(r);
                if (ss.size() == 0)
                {
                    cout << "No";
                    return 0;
                }
                it = ss.begin();
                r = *it;
            }
            if (r.first > n * n) res[i] = r.first - n * n;
            else res[i] = res[r.first];
            ss.erase(it);
            r.second--;
            ss.insert(r);
        }
        else
        {
            auto it = ss.lower_bound({i, 0});
            pair<int, int> s = *it;
            //cout << s.first << " " << s.second << endl;
            if (s.second > 0)
            {
                cout << "No";
                return 0;
            }
            pair<int, int> v = {n * n + res[i], n - res[i]};
            ss.insert(v);
        }
    }
    cout << "Yes\n";
    for (int i = 1; i <= n * n; i++)
    {
        cout << res[i] << " ";
    }
}

