void solve() {
	cin >> N;
	memset(ans, -1, sizeof(ans));
	rep(i, 0, N) {
		int a; cin >> a; a--;
		A[i] = make_pair(pi(a - 1, i), i);
		B[i] = make_pair(pi(-(a + 1), N - i - 1), i);
		ans[a] = i;
	}
	sort(A, A + N);
	sort(B, B + N);
	rep(i, 0, N) {
		int l = A[i].fst.fst, c = A[i].fst.sec, num = A[i].sec;
		// debug(l, c, num, vi(ans, ans + N * N));
		if(c == 0) continue;
		int at = 0;
		while(at <= l && c != 0) {
			if(ans[at] == -1) {
				ans[at] = num;
				c--;
			}
			at++;
		}
		if(at == l + 1 && c != 0) {
			cout << "No\n"; return;
		}
	}
	rep(i, 0, N) {
		int r = B[i].fst.fst * -1, c = B[i].fst.sec, num = B[i].sec;
		if(c == 0) continue;
		// debug(r, c, num, vi(ans, ans + N * N));
		int at = N * N - 1;
		while(at >= r && c != 0) {
			if(ans[at] == -1) {
				ans[at] = num;
				c--;
			}
			at--;
		}
		if(at == r - 1 && c != 0) {
			cout << "No\n"; return;
		}
	}
	cout << "Yes\n";
	rep(i, 0, N * N) cout << ans[i] + 1 << " ";
	cout << "\n";
}

