#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
typedef tuple<int,int,int> tpl;

int N;
int X[510];
int R[510*510];
bool is_left_end[510];

bool solve(){
    memset(R,-1,sizeof(R));
    priority_queue<tpl, vector<tpl>, greater<tpl> > left_queue;
    for(int i = 0; i < N; i++){
        if(i != 0){
            left_queue.push(tpl(X[i] - i, i, i));
        }
        else{
            is_left_end[i] = true;
        }
        R[X[i]] = i;
    }
    queue<pii> right_queue;
    for(int i = 0; i < N * N; i++){
        // すでに決定済み
        if(R[i] != -1){
            const int idx = R[i];
            // この要素がまだleft_queueに残っている場合, NG
            if(!is_left_end[idx]) return false;
            // そうでない場合, right queueにいれておく
            if(N - idx - 1 > 0) right_queue.push(pii(N - idx - 1, idx));
        }
        else if(left_queue.size() == 0){
            // right queueで埋める
            if(right_queue.size() == 0) return false;
            const pii p = right_queue.front(); right_queue.pop();
            R[i] = p.second;
            if(p.first != 1) right_queue.push(pii(p.first-1,p.second));
        }
        else{
            // left_queueの要素を使って埋める
            const auto t = left_queue.top(); left_queue.pop();
            const int ccost = get<0>(t);
            const int cnt = get<1>(t);
            const int idx = get<2>(t);
            R[i] = idx;
            if(cnt - 1 > 0) left_queue.push(make_tuple(ccost+1, cnt-1, idx));
            else is_left_end[idx] = true;
        }
    }
    return true;
}

int main(){

    cin >> N;
    for(int i = 0; i < N; i++) cin >> X[i], X[i]--;
    if(!solve()){
        cout << "No" << endl;
    }
    else{
        cout << "Yes" << endl;
        for(int i = 0; i < N * N; i++){
            cout << R[i] + 1;
            if(i == N*N-1) cout << endl;
            else cout << " ";
        }
    }

    return 0;
}

