using namespace std;

class dsu {
 public:
  int n;
  vector<int> parent;

  dsu(int _n) : n(_n) {
    parent.resize(n);
    iota(parent.begin(), parent.end(), 0);
  }

  int find(int x) {
    if (x == -1 || x == n || x == parent[x]) {
      return x;
    }
    return parent[x] = find(parent[x]);
  }

};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  vector<int> ans(n * n, -1);
  dsu d_left(n * n), d_right(n * n);
  vector<int> x(n);
  for (int i = 0; i < n; i++) {
    cin >> x[i];
  }
  for (int i = 0; i < n; i++) {
    int t = i;
    for (int j = x[i] - 1; j >= 0 && t >= 0; t--, j = d_left.find(j)) {
      ans[j] = i;
      d_left.parent[j] = j - 1;
    }
    if (t > 0) {
      cout << "No\n";
      return 0;
    }
  }
  for (int i = n * n - 1; i >= 0; i--) {
    if (ans[i] != -1) {
      d_right.parent[i] = i + 1;
    }
  }
  for (int i = n - 1; i >= 0; i--) {
    int t = n - i - 1;
    for (int j = d_right.find(x[i] - 1); j < n * n && t >= 0; t--, j = d_right.find(j)) {
      ans[j] = i;
      d_right.parent[j] = j + 1;
    }
    if (t > 0) {
      cout << "No\n";
      return 0;
    }
  }
  cout << "Yes\n";
  for (int i = 0; i < n * n; i++) {
    cout << ans[i] + 1 << ' ';
  }
  cout << '\n';
  return 0;
}

