bool check(const vector<int>& X, const vector<int>& ans) {
	int N = X.size();
	vector<int> cnt(N);
	for (int i = 0; i < N*N; i++) {
		if (ans[i] == -1) return false;
		if (cnt[ans[i]] == ans[i]) {
			if (X[ans[i]] != i) return false;
		}
		cnt[ans[i]]++;
	}
	for (int i = 0; i < N; i++) {
		if (cnt[i] != N) return false;
	}
	return true;
}

