const int INF    = (int) 0x3f3f3f3f;
struct Flow {
    int n, s, t;
    int c[N][N], f[N][N], d[N], pr[N];
    void Init(int __n, int __s, int __t) {
        n = __n;
        s = __s; t = __t;
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= n; ++j)
                c[i][j] = f[i][j] = 0;
    }
    void AddEdge(int u, int v, int w) { c[u][v] = w; }

    bool BFS() {
        queue<int> Q; Q.push(s);
        for (int i = 1; i <= n; ++i) d[i] = -1; d[s] = 0;
        while (Q.size()) {
            int u = Q.front(); Q.pop();
            for (int v = 1; v <= n; ++v) if (c[u][v] > f[u][v] && d[v] == -1) {
                d[v] = d[u] + 1;
                Q.push(v);
            }
        }
        return d[t] != -1;
    }
    int DFS(int u, int fl) {
        if (u == t) return fl;
        for (int &v = pr[u]; v <= n; ++v) if (c[u][v] > f[u][v] && d[v] == d[u] + 1) {
            int x = DFS(v, min(fl, c[u][v] - f[u][v]));
            if (x) {
                f[u][v] += x;
                f[v][u] -= x;
                return x;
            }
        }
        return 0;
    }
    int MaxFlow() {
        int ans = 0;
        while (BFS()) {
            for (int i = 1; i <= n; ++i) pr[i] = 1;
            while (1) {
                int x = DFS(s, INF);
                if (x) ans += x; else break;
            }
        }
        return ans;
    }
} Flow;
int n, x[N], ans[N * N];
bool mark[N * N];

int main() {
    #ifdef LOCAL
        freopen("Data.inp", "r", stdin);
        freopen("Data.out", "w", stdout);
    #endif

    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) scanf("%d", &x[i]);
    for (int i = 1; i <= n; ++i) mark[x[i]] = true, ans[x[i]] = i;

    int _s = n * n + 2 * n + 1, _t = n * n + 2 * n + 2; Flow.Init(_t, _s, _t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= x[i] - 1; ++j)
            if (mark[j] == false) Flow.AddEdge(i, j + 2 * n, 1);
    for (int i = 1; i <= n; ++i)
        for (int j = x[i] + 1; j <= n * n; ++j)
            if (mark[j] == false) Flow.AddEdge(i + n, j + 2 * n, 1);
    for (int i = 1; i <= n * n; ++i) if (mark[i] == false) Flow.AddEdge(i + 2 * n, _t, 1);
    for (int i = 1; i <= n; ++i) Flow.AddEdge(_s, i, i - 1);
    for (int i = 1; i <= n; ++i) Flow.AddEdge(_s, i + n, n - i);

    if (Flow.MaxFlow() != n * n - n) {
        puts("No");
        return 0;
    }

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n * n; ++j)
            if (Flow.f[i][j + 2 * n] > 0) ans[j] = i;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n * n; ++j)
            if (Flow.f[i + n][j + 2 * n] > 0) ans[j] = i;

    puts("Yes");
    for (int i = 1; i <= n * n; ++i) printf("%d ", ans[i]);
    return 0;
}

