    REP(i, 0, N) {
        cin >> x[i];
        p[i] = plglg(x[i] - 1, i + 1);
    }
    sort(p, p + N);
    ll rem[3][N];
    REP(i, 0, N) {
        rem[0][i] = p[i].second;
        rem[1][i] = p[i].second - 1;
        rem[2][i] = N - p[i].second;
    }
    ll ans[N * N];
