        ans[p[i].first] = p[i].second;
        now = p[i].first + 1;
        pre = p[i].first;
    }
    if (!ok) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
        REP(i, now, N * N) {
            while (rem[2][markb] == 0) {
                markb++;
            }
            ans[i] = rem[0][markb];
            rem[2][markb]--;
        }
        REP(i, 0, N * N) {
            cout << ans[i];
            if (i < N * N - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
}

