	if (c=='-') q=0,c=getchar();
	while (c>='0'&&c <= '9') w=w*10+c-'0',c=getchar();
	return q? w:-w;
}
int fa[N],f[N];
bool o[N];
int ans[N];
inline int find(int x) { return fa[x]==x?x:fa[x]=find(fa[x]); }
int main()
{
