int bittree[250005]={},n,arr[505],ans[250005],reversebittree[250005]={};
bool possible=true;
vector <pair<int,int> > daftar;
int lsone(int angka)
{
	return (angka&-angka);
}
int ubah(int indeks)
{
	return (n*n-indeks+1);
}
void tambah(int indeks,int tambah)
{
	while(indeks<=n*n)
	{
		bittree[indeks]+=tambah;
		indeks+=lsone(indeks);
	}
}
int nilai(int indeks)
{
	int ret=0;
	while(indeks>0)
	{
		ret+=bittree[indeks];
		indeks-=lsone(indeks);
	}
	return ret;
}
void buatBIT()
{
	for(int i=1;i<=n*n;i++)		//ceritanya semua dalam keadaan on
		bittree[i]=lsone(i);
}
int lower()	//cari bilangan pertama yang masih kosong
{
	int bawah=1,atas=n*n,mid;
	while(bawah<=atas)
	{
		mid=(bawah+atas)>>1;
		if(nilai(mid)>=1)
			atas=mid-1;
		else
			bawah=mid+1;
	}
	return bawah;
}
int biggestlower()	//cari bilangan terbesar yang masih kosong
{
	int target=nilai(n*n);
	int bawah=1,atas=n*n,mid;
	while(bawah<=atas)
	{
		mid=(bawah+atas)>>1;
		if(nilai(mid)>=target)
			atas=mid-1;
		else
			bawah=mid+1;
	}
	return bawah;
}
