{
	int occ[n+5]={},last=1;
	for(int i=0;i<daftar.size();i++)
	{
		//cout<<"tai"<<endl;
		for(last;last<=daftar[i].first;last++)
			occ[ans[last]]++;
		if(!((ans[last-1]==daftar[i].second)&&(occ[daftar[i].second]==daftar[i].second)))
		{
			//cout<<daftar[i].second<<" "<<occ[daftar[i].second]<<endl;
			return false;
		}
	}
	return true;
}
