{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&arr[i]);
	}
	buatBIT();
	//cout<<"satu"<<endl;
	for(int i=1;i<=n;i++)		//prioritaskan yang di tunjuk;
	{
		daftar.push_back(make_pair(arr[i],i));
		ans[arr[i]]=i;
		tambah(arr[i],-1);
	}
	//sort(daftar.begin(),daftar.end());
	//cout<<"endl"<<endl;
	for(int i=0;i<daftar.size();i++)
	{
		pair<int,int> temp=daftar[i];
		for(int j=1;j<=temp.second-1;j++)
		{
			int indeks=lower();
			ans[indeks]=temp.second;
