    }

    for (int n = 1; n <= N; n++) {
        while (idx < N * N and num[n] < N) {
            if (ans[idx] < 0) {
                ans[idx] = n;
                num[n]++;

                if (idx < x[n - 1]) {
                    cout << "No" << endl;
                    return 0;
                }
            }
            idx++;
        }
    }

    int sum = 0;
    for (int n = 1; n <= N; n++) sum += num[n];

    if (sum != N * N) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;
    for (int a : ans) {
        cout << a << " ";
    }
    cout << endl;

    return 0;
}

