bool solve() {
    int N;
    cin >> N;
    vector<int> X(N+1);
    for ( int i = 1; i <= N; i++ ) {
        cin >> X[i];
    }
    vector<int> ans(N*N+1);
    set<int> r;
    for ( int i = 1; i <= N*N; i++ ) {
        r.insert(i);
    }
    for ( int i = 1; i <= N; i++ ) {
        ans[X[i]] = i;
    }
    vector<pair<int,int>> xi;
    for ( int i = 1; i <= N; i++ ) {
        xi.emplace_back(X[i], i);
    }
    sort(xi.begin(), xi.end());
    for ( int k = 0; k < N; k++ ) {
        int x = xi[k].first;
        int i = xi[k].second;
        auto p = r.lower_bound(x);
        for ( int j = 0; j < i-1; j++ ) {
            if ( p == r.begin() ) {
                return false;
            }
            auto pp = prev(p);
            while ( ans[*pp] > 0 ) {
                if ( pp == r.begin() ) {
                    return false;
                }
                pp = prev(pp);
            }
            ans[*pp] = i;
            r.erase(*pp);
        }
        r.erase(*p);
        p = r.end();
        for ( int j = i-1; j < N-1; j++ ) {
            auto pp = prev(p);
            while ( ans[*pp] > 0 ) {
                if ( pp == r.begin() ) {
                    return false;
                }
                pp = prev(pp);
            }
            if ( *pp < x ) return false;
            ans[*pp] = i;
            r.erase(*pp);
        }
    }

    cout << "Yes" << "\n";
    for ( int i = 1; i <= N*N; i++ ) {
        cout << (i != 1 ? " " : "") << ans[i];
    }
    cout << "\n";
    return true;
}

int main() {
    auto ans = solve();
    if ( !ans ) cout << "No" << "\n";
    return 0;
}

