using namespace std;
using pii = pair<int, int>;

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<int> x(n);
	for(int i = 0; i < n; ++i){
		cin >> x[i];
		--x[i];
	}
	vector<int> a(n * n), b(n * n, -1), done(n);
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	for(int i = 0; i < n; ++i){
		b[x[i]] = i;
		for(int j = 0; j < i; ++j){ pq.emplace(x[i], i); }
	}
	bool accept = true;
	for(int i = 0; i < n * n; ++i){
		if(b[i] >= 0){
			if(done[b[i]] != b[i]){
				accept = false;
				break;
			}
			a[i] = b[i];
			for(int j = b[i] + 1; j < n; ++j){
				pq.emplace(n, b[i]);
			}
		}else{
			if(pq.empty()){
				accept = false;
				break;
			}
			const auto t = pq.top();
			pq.pop();
			a[i] = t.second;
			++done[t.second];
		}
	}
	if(!accept){
		cout << "No" << endl;
	}else{
		cout << "Yes" << endl;
		for(int i = 0; i < n * n; ++i){
			cout << a[i] + 1 << " ";
		}
		cout << endl;
	}
	return 0;
}

