{
    return b[i - 1] < b[j - 1];
}

int main() 
{
    cin >> n;
    for (int i = 0; i < n; i++)
    {
        cin >> b[i];
        b[i]--;
        num[i] = i + 1;
        a[b[i]] = i + 1;
    }
    sort(num, num + n, cmp);
    int i = 0;
    int j = 0;
    int cnt = 1;
    while (i < n)
    {
        while (a[j])
        {
            j++;
        }
        if (cnt + 1 <= num[i])
        {
            a[j] = num[i];
            cnt++;
        }
        if (cnt == num[i])
        {
            i++;
            cnt = 1;
        }
    }
    i = 0;
    j = 0;
    cnt = num[0];
    while (i < n)
    {
        while (a[j])
        {
            j++;
        }
        if (cnt + 1 <= n)
        {
            a[j] = num[i];
            cnt++;
        }
        if (cnt == n)
        {
            i++;
            cnt = num[i];
        }
    }
    for (int i = 0; i < n * n; i++)
    {
        check[a[i]]++;
        if (i == b[num[i] - 1])
        {
            if (check[num[i]] != num[i])
            {
                cout << "No" << endl;
