    for (int i = 0; i < N; i++) {
    	for (int j = 0; j < i; j++) {
    		while (ans[top] >= 0) top++;
    		ans[top] = i + 1;
    	}
    }

    int bottom = N * N - 1;
    for (int i = N - 1; i >= 0; i--) {
    	for (int j = 0; j < N - 1 - i; j++) {
    		while (ans[bottom] >= 0) bottom--;
    		ans[bottom] = i + 1;
    	}
    }

    vector < int > cnt_pre(N, 0);
    vector < int > cnt_nxt(N, 0);
    REP(i,ans.size()) {
    	if (x[ans[i] - 1] < i) cnt_pre[ans[i] - 1]++;
    	if (x[ans[i] - 1] > i) cnt_nxt[ans[i] - 1]++; 
