int check()
{
  int kol[MAX];
  memset(kol, 0, sizeof kol);

  REP(i, n*n) {
    if (rje[i] < 1 || rje[i] > n) return 0;
    kol[rje[i]]++;
    if (kol[rje[i]] == rje[i] && i != x[rje[i]])
      return 0;
  }

  FOR(i, 1, n+1)
    if (kol[i] != n)
      return 0;

  return 1;
