    poz[i] = P(x[i], i);
    treba[x[i]] = i;
  }

  sort(poz + 1, poz + n + 1);

  REP(i, n*n) {
    if (treba[i])
      rje[i] = treba[i];
    else {
      int da = 0;

      FOR(j, 1, n+1) {
	int ind = poz[j].Y;
	if (ima[ind] + 1 < ind) {
	  rje[i] = ind;
	  da = 1;
	  break;
