int main() {
	ios::sync_with_stdio(0), cin.tie(0);

	int n;
	cin >> n;
	vector<pair<int, int> > stuff(n);
	vector<int> rem(n, n);
	vector<int> which(n * n, -1);
	for (int i = 0; i < n; i++) {
		int p;
		cin >> p;
		p--;
		stuff[i] = {p, i};
		which[p] = i;
	}
	sort(stuff.begin(), stuff.end());
	auto fail = [&]() -> void {
		cout << "No" << '\n';
		exit(0);
	};
	int cur = 0;
	vector<int> ans(n * n, -1);
	for (auto z : stuff) {
		for (int _ = 0; _ < z.second; _++) {
			while (cur < z.first && ans[cur] != -1) cur++;
			if (cur >= z.first) fail();
			ans[cur] = z.second;
			rem[z.second]--;
		}
		if (ans[z.first] != -1) fail();
		ans[z.first] = z.second;
		rem[z.second]--;
	}
	vector<bool> good(n, false);
	for (int i = 0; i < n * n; i++) {
		if (which[i] != -1) good[which[i]] = true;
		if (ans[i] == -1) {
			for (int x = n-1; x >= 0; x--) {
				if (rem[x] && good[x]) {
					ans[i] = x;
					rem[x]--;
					break;
				}
			}
			if (ans[i] == -1) fail();
		}
	}
	for (int x = 0; x < n; x++) assert(rem[x] == 0);
