using namespace std;
typedef long long int ll;
const int INF = 1 << 30;
#define rep(i,n) for(int i=(ll)0;i<(ll)n;++i)
#define ALL(x) x.begin(),x.end()
int main() {
	int n;
	int pos[510] = {};
	int dp[251][510] = {};
	int ans[2510] = {};
	cin >> n;
	rep(i, n) {
		cin >> pos[i];
		pos[i]--;
		for (int j = 0; j < pos[i];++j) {
			dp[j][i] = i;
		}
		for (int j = pos[i] + 1; j < n*n; ++j) {
			dp[j][i] = n - i - 1;
		}
	}
	rep(i, n*n) {
		int mn=INF,mnp=INF;
		bool fl = 0;
		for (int j = 0; j < n; ++j) {
			if (dp[i][j] != 0&&i!=pos[j]) {
				int num;
				if (i < pos[j])num = pos[j] - i;
				else num = INF - j-1;
				if (mn > num) { mn = num; mnp = j; }
			}
			if (i != n*n - 1&&i!=pos[j])dp[i + 1][j] = dp[i][j];
			if (i == pos[j]) { ans[i] = j + 1; fl = 1; }
		}
		if (fl)continue;
		if (mn == INF) { cout << "No" << endl; return 0; }
		dp[i][mnp] -= 1;
		ans[i] = mnp + 1;
		if (i != n*n - 1)dp[i + 1][mnp] = dp[i][mnp];
	}
	cout << "Yes" << endl;
	rep(i, n*n) {
		cout << ans[i]<<" ";
	}
	cout<<""<<endl;
	return 0;
}

