int n;
int a[maxn],ans[maxm];
pair<int,int>s[maxn];

bool solve() {
    int l = 1;
    for(int i=1; i<=n; i++) {
        int cnt = 0;
        if(s[i].second-1==0)continue;
        while(l<=n*n&&l<=s[i].first) {
            if(ans[l]) {
                l++;
                continue;
            }
            ans[l] = s[i].second;
            l++;
            cnt++;
            if(cnt==s[i].second-1)break;
        }
        if(cnt<s[i].second-1) {
            //cout<<s[i].second<<endl;
            return false;
        }
    }
    l = n*n;
    for(int i=n; i>=1; i--) {
        int cnt = 0;
        if(n-s[i].second==0)continue;
        while(l>0&&l>=s[i].first) {
            if(ans[l]) {
                l--;
                continue;
            }
            ans[l] = s[i].second;
            l--;
            cnt++;
            if(cnt==n - s[i].second)break;
        }
        if(cnt<n - s[i].second) {
            //cout<<s[i].second<<endl;
            return false;
        }
    }
    return true;
}

