typedef vector<int> vi;
const int maxn = 500 + 10;
#define pb push_back

vi g[maxn];

pair<int,int> vv[maxn];

int a[maxn];
int w[maxn * maxn];
int cnt[maxn];

#define NOSOL { puts("No"); return 0; }

int main() {
	int n; scanf("%d", &n);
	for(int i = 1; i <= n; ++i) scanf("%d", &a[i]), w[a[i]] = i;
	set<int> s(a + 1, a + n + 1);
	if(s.size() != n) NOSOL;
	for(int i = 1; i <= n; ++i) cnt[i] = i - 1;
	priority_queue< pair<int,int> > q;
	for(int i = 1; i <= n; ++i) if(cnt[i]) q.push({a[i], i});
	for(int k = 1; k <= n * n; ++k) {
		if(w[k]) continue;
		int p, i; tie(p, i) = q.top();
		if(k > p) NOSOL;
		w[k] = i;
		if(--cnt[i] == 0) q.pop();
		if(q.empty()) break;
	}
	if(!q.empty()) NOSOL;
	for(int i = 1; i <= n; ++i) cnt[i] = n - i;
	for(int i = 1; i <= n; ++i) if(cnt[i]) q.push({a[i], i});
	for(int k = n * n; k >= 1; --k) {
		if(w[k]) continue;
		int p, i; tie(p, i) = q.top();
		if(k < p) NOSOL;
		w[k] = i;
		if(--cnt[i] == 0) q.pop();
	}
	if(!q.empty()) NOSOL;
	puts("Yes");
	for(int i = 1; i <= n * n; ++i) 
		printf("%d%c", w[i], " \n"[i==n*n]);
	return 0;
}

