int main() {
  int n;
  scanf("%d", &n);
  vector<ii> x(n);
  vector<int> ret(n * n);
  vector<bool> fixed(n * n);
  for (int i = 0; i < n; ++i) {
    int v;
    scanf("%d", &v);
    --v;
    x[i] = {v, i + 1};
    ret[v] = i + 1;
    fixed[v] = true;
  }
  sort(x.begin(), x.end());
  bool found = false;
  for (int i = 0; i < n; ++i) {
    int L = x[i].second - 1, R = n - 1 - L, j;
    vector<int> homeless;
    for (j = 0; L && j < x[i].first; ++j) {
      if (ret[j] == 0) {
        ret[j] = x[i].second;
        fixed[j] = true;
        --L;
      } else if (!fixed[j]) {
        homeless.push_back(ret[j]);
        ret[j] = x[i].second;
        fixed[j] = true;
        --L;
      }
    }
    if (L) {
      found = true;
      break;
    }
    for (; homeless.size() && j < x[i].first; ++j) {
      if (ret[j] == 0) {
        ret[j] = homeless.back();
        homeless.pop_back();
      }
    }
    // print(ret);
    for (j = x[i].first + 1; (R || homeless.size()) && j < n * n; ++j) {
      if (ret[j]) continue;
      if (R) {
        ret[j] = x[i].second;
        --R;
      } else {
        ret[j] = homeless.back();
        homeless.pop_back();
      }
    }
    if (R || homeless.size()) {
      found = true;
      break;
    }
    // print(ret);
    // trace("==");
  }
  if (found) {
    puts("No");
  } else {
    puts("Yes");
    for (int i = 0; i < n * n; ++i) {
      printf("%d%c", ret[i], " \n"[i + 1 == n * n]);
    }
  }
  return 0;
}

