    int ans[n*n+1],first[n*n+1];
    for(i=1;i<=n*n;i++)ans[i]=NIL,first[i]=NIL;
    for(i=1;i<=n;i++)ans[x[i]]=i,first[x[i]]=i;

    int j=1,flag=1;  /*flag 1は真 0は偽*/

    while(j<=n*n){
        if(ans[j]!=NIL){
            int count=1,k=1;
            while(count<=ans[j]-1 && k<=j-1){
                if(ans[k]==NIL){
                    ans[k]=ans[j];
                    count++;
                }
                k++;
            }
            if(count!=ans[j])flag=0;
        }
        j++;
    }

    j=n*n;
