#include <stdio.h>

typedef struct {
	int key, id;
} data;

typedef struct {
	data obj[250001];
	int size;
} min_heap;

void push(data x, min_heap* h)
{
	int i = ++(h->size);
	data tmp;
	h->obj[i] = x;
	while (i > 1) {
		if (h->obj[i].key < h->obj[i>>1].key) {
			tmp = h->obj[i>>1];
			h->obj[i>>1] = h->obj[i];
			h->obj[i] = tmp;
			i >>= 1;
		} else break;
	}
}

data pop(min_heap* h)
{
	int i = 1, j = 2;
	data output = h->obj[1], tmp;
	h->obj[1] = h->obj[(h->size)--];
	while (j <= h->size) {
		if (j < h->size && h->obj[j^1].key < h->obj[j].key) j ^= 1;
		if (h->obj[j].key < h->obj[i].key) {
			tmp = h->obj[j];
			h->obj[j] = h->obj[i];
			h->obj[i] = tmp;
			i = j;
			j = i << 1;
		} else break;
	}
	return output;
}

int main()
{
	int i, N, x[501];
	scanf("%d", &N);
	for (i = 1; i <= N; i++) scanf("%d", &(x[i]));

	int j, M = N * N, ans[250001] = {};
	data d;
	min_heap h[2];
	h[0].size = 0;
	h[1].size = 0;
	for (i = 1; i <= N; i++) {
		ans[x[i]] = i;
		d.key = x[i];
		d.id = i;
		for (j = 1; j < i; j++) push(d, &(h[0]));
	}
	for (i = 1; i <= M; i++) {
		if (ans[i] == 0) {
			if (h[0].size > 0) {
				d = pop(&(h[0]));
				if (x[d.id] < i) break;
				else ans[i] = d.id;
			} else if (h[1].size > 0) ans[i] = pop(&(h[1])).id;
			else break;
		} else {
			d.key = i;
			d.id = ans[i];
			for (j = ans[i] + 1; j <= N; j++) push(d, &(h[1]));
		}
	}

	if (i <= M) printf("No\n");
	else {
		printf("Yes\n");
		for (i = 1; i < M; i++) printf("%d ", ans[i]);
		printf("%d\n", ans[M]);
	}
	fflush(stdout);
	return 0;
}

