#include<stdio.h>
#include<stdlib.h>
#include<stdint.h>
#include<inttypes.h>
#include<string.h>

typedef int32_t i32;

void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  i32 *x = (i32 *) calloc (n + 1, sizeof (i32));
  for (i32 i = 1; i <= n; ++i) {
    scanf ("%" SCNi32, x + i);
  }
  x[0] = n * n + 1;
  i32 *ans = (i32 *) calloc (n * n + 1, sizeof (i32));
  for (i32 i = 1; i <= n; ++i) {
    ans[x[i]] = i;
  }
  uint8_t *used = (uint8_t *) calloc (n + 1, sizeof (uint8_t));
  for (i32 i = 0; i < n; ++i) {
    i32 min = 0;
    for (i32 j = 1; j <= n; ++j) {
      if (!used[j] && x[min] > x[j]) min = j;
    }
    used[min] = 1;
    i32 k = min - 1;
    for (i32 j = x[min]; j >= 1 && k > 0; --j) {
      if (ans[j] > 0) continue;
      ans[j] = min;
      k--;
    }
    if (k > 0) {
      puts ("No");
      return;
    }
  }
  memset (used, 0, sizeof (uint8_t) * (n + 1));
  x[0] = 0;
  for (i32 i = 0; i < n; ++i) {
    i32 max = 0;
    for (i32 j = 1; j <= n; ++j) {
      if (!used[j] && x[max] < x[j]) max = j;
    }
    used[max] = 1;
    i32 k = n - max;;
    for (i32 j = x[max]; j <= n * n && k > 0; ++j) {
      if (ans[j] > 0) continue;
      ans[j] = max;
      k--;
    }
    if (k > 0) {
      puts ("No");
      return;
    }
  }
  puts ("Yes");
  for (i32 i = 1; i <= n * n; ++i) {
    printf ("%" PRIi32, ans[i]);
    putchar (" \n"[i < n * n ? 0 : 1]);
  }
}

int main (void) {
  run();
  return 0;
}

