  int output[501];

  for (i = 0; i < 501; i++) {
    necessary[i] = 0;
  }
  for (i = 0; i < 250001; i++) {
    result[i] = 0;
  }

  int N;

  scanf("%d", &N);
  for (i = 1; i <= N; i++) {
    scanf(" %d", &data[i]);
  }

  for (i = 1; i < 501; i++) {
    output[i] = N;
  }

  int temp1, temp2, tempn;

  for (i = 1; i <= N; i++) {
    temp1 = 0;
    temp2 = 0;
    for (j = 1; j <= N; j++) {
      if (i == j) {
        temp1 += j - 1;
        temp2 += (N - j);
      }
      else if (data[j] < data[i]) {
        temp1 += j;
      } else {
        temp2 += (N - j + 1);
      }
