    if(temp1 > data[i]-1||temp2>(N*N-data[i])){
      flag = 1;
      break;
    }
    else {
      k = 1;
      while (output[i] > N-i+1  && data[i] > k) {
        if (result[k] == 0) {
          result[k] = i;
          output[i]--;
        }
        k++;
      }
      result[data[i]] = i;
      output[i]--;
    }
  }

  if (flag == 1) {
    printf("No");
  } else {
    printf("Yes\n");
    for (i = 1; i <= N; i++) {
  //    printf("%d\n", output[i]);
