    var x=Array(n+1){IntArray(2){0} }
    val inp= readLine()!!.split(" ").map { it.toInt() }
    var a=IntArray(n*n){0}
    for (i in 1..n){
        x[i][0]=i
        x[i][1]=inp[i-1]-1
        a[x[i][1]]=i
    }
    x.sortBy { it[1] }
    var que=ArrayDeque<Int>()
    var cnt=IntArray(2){1}
    var f=true
    var tmp=mutableListOf(x[cnt[1]][0], x[cnt[1]][0]-1)
    for (i in 0 until n*n){
        if (cnt[1]>n){
            if (cnt[0]<n && x[cnt[0]][1]==i){
                cnt[0]++
            }else{
                a[i]=que.removeFirst()
            }
        }else{
            if (x[cnt[0]][1]>i){
                a[i]=tmp[0]
                tmp[1]--
            }
            if (tmp[1]==0){
                for (j in 0 until n-x[cnt[1]][0]){
                    que.addFirst(x[cnt[1]][0])
                }
                if (cnt[1]++<n){
                    tmp=mutableListOf(x[cnt[1]][0], x[cnt[1]][0]-1)
                }
            }
            if (x[cnt[0]][1]==i){
                cnt[0]++
            }
            if (cnt[0]>cnt[1]){
                f=false
                break
            }
        }
    }
    if (f){
        println("Yes")
        println(a.joinToString(separator = " "))
    }else{
        println("No")
    }

}

