import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            final int n = in.nextInt();
            final int N = n * n;
            final int[] res = new int[N + 1];
            boolean[] check = new boolean[N + 1];
            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                res[a] = i + 1;
                check[a] = true;
            }
            int sum = 0;
            for (int i = 1; i <= N; ++i) {
                if (res[i] > 0)
                    sum += res[i];
                if (i < sum) {
                    out.println("No");
                    return;
                }
            }

            sum = 0;
            for (int i = N; i > 0; --i) {
                if (res[i] > 0)
                    sum += n - res[i];
                if ((N - i + 1) < sum) {
                    out.println("No");
                    return;
                }
            }

            List<Integer> order = new ArrayList<>();
            for (int i = 1; i<=N; ++i) {
                if (res[i] > 0) order.add(res[i]);
            }
            int pos = 0;
            int cnt = order.get(0) - 1;
            outerloop:
            for (int i =1 ; i <=N; ++i) {
                if (res[i] > 0) continue;
                while (cnt == 0) {
                    pos++;
                    if (pos >= order.size()) break outerloop;
                    cnt = order.get(pos) - 1;
                }
                res[i] = order.get(pos);
                cnt--;
            }

            pos = order.size() - 1;
            cnt = n - order.get(order.size() - 1);
            outerloop1:
            for (int i = N; i > 0; --i) {
                if (res[i] > 0) continue;
                while (cnt == 0) {
                    pos--;
                    if (pos < 0) break outerloop1;
                    cnt = n - order.get(pos);
                }
                res[i] = order.get(pos);
                cnt--;
            }
            int[] freq = new int[n + 1];
            for (int i = 1; i <= N; ++i) {
//                if (res[i] == 0) call();
                freq[res[i]]++;
                if (!check[i]) continue;
                if (freq[res[i]] != res[i])
                    call();
            }

            out.println("Yes");
            for (int i = 1; i <= N; ++i) {
                if (i > 1) out.print(" ");
                out.print(res[i]);
            }
            out.println();

        }

        private void call() {
            throw new RuntimeException();
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;

public class Main {
  static Scanner sc = new Scanner(System.in);

  public static void main(String[] args) {
    int N = sc.nextInt();
    final int[] X = new int[N];
    BIT bit = new BIT(N * N);
    int[] order = new int[N];
    for (int i = 0; i < N; i++) {
      X[i] = sc.nextInt();
      order[i] = (X[i] << 10) | i;
      bit.add(X[i], i + 1);
    }
    for (int i = 0; i < N; i++) {
      if (bit.cumulativeSum(X[i]) > X[i]) {
        System.out.println("No");
        return;
      }
    }
    Arrays.sort(order);
    HashMap<Integer, Integer> xs = new HashMap<>();
    for (int i = 0; i < N; i++) {
      order[i] &= 0x3FF;
      xs.put(X[i], i + 1);
    }
    ArrayList<Integer> output = new ArrayList<>();
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < order[i]; j++) {
        output.add(order[i] + 1);
      }
    }
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N - 1 - order[i]; j++) {
        output.add(order[i] + 1);
      }
    }
    int[] count = new int[N];
    StringBuilder sb = new StringBuilder();
    for (int i = 0, pos = 0; i < N * N; i++) {
      if (xs.containsKey(i + 1)) {
        int v = xs.get(i + 1);
        if (count[v - 1] != v - 1) {
          System.out.println("No");
          return;
        }
        sb.append(v + " ");
      } else {
        count[output.get(pos) - 1]++;
        sb.append(output.get(pos++) + " ");
      }
    }
    System.out.println("Yes");
    sb.deleteCharAt(sb.length() - 1);
    System.out.println(sb);
  }

  static class BIT {
    long[] v;

    BIT(int size) {
      int len = 1;
      while (len < size) {
        len *= 2;
      }
      this.v = new long[len + 1];
    }

    long cumulativeSum(int index) {
      long ret = 0;
      while (index > 0) {
        ret += v[index];
        index &= index - 1;
      }
      return ret;
    }

    // inclusive, 1-indexed
    long sum(int l, int r) {
      long ret = cumulativeSum(r) - cumulativeSum(l - 1);
      return ret;
    }

    void add(int index, long val) {
      while (index < v.length) {
        v[index] += val;
        index += (index & -index);
      }
    }

    void set(int index, long val) {
      long old = sum(index, index);
      add(index, val - old);
    }
  }
}

