			int orCo=0;
			for(int j=0;j<N*N ;j++) {
				if(array[j] != 0) {
					String co = String.valueOf(j+1);
					String value = String.valueOf(array[j]);
					order[orCo]= co+":"+value;
					orCo++;
				}
			}
			int point = 1;
			count = 1;
			for(int x =0 ; x<N ; x++) {
				String [] temp = order[x].split(":");
				int limit = Integer.parseInt(temp[0]);
				point = Integer.parseInt(temp[1]);
				for(int i=0 ; i<N*N ; i++) {
					if(limit-1 > i && array[i] == 0 && point != count) {
						array[i] = point;
						count++;
					}
				}
				if(count != point) {
					notFlag = true;
					break;
				}
				//point++;
				count = 1;
			}
			if(!notFlag) {
				point = 1;
				count = 0;
				orCo = N-1;
				String [] sp;
				for(int i=N*N-1 ;i>=0;i--) {
					if(orCo < 0 ) {
						break;
					}
					sp = order[orCo].split(":");
					point = Integer.parseInt(sp[1]);
					int temp = N - point;
					if(array[i] == 0) {
						array[i] = point;
						count++;
					}
					if(count == temp) {
						count = 0;
						orCo--;
						point++;
					}
				}
			}
		}
		if(notFlag) {
			System.out.println("No");
		}else {
			System.out.println("Yes");
			int co = 1;
			for( int re : array ) {
				if(N*N > co) {
					System.out.print(re+" ");
				}else {
					System.out.print(re);
					System.out.println();
				}
				co++;
			}
		}
	}
}

import java.io.*;
