import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args)throws Exception {
		BufferedReader br = new BufferedReader ( new InputStreamReader(System.in));
		int N = Integer.parseInt(br.readLine());
		String [] input = br.readLine().split(" ");
		int [] array = new int[N*N];
		String []order = new String[N];
		int count = 1;
		boolean notFlag = false;
		for(String s : input) {
			int temp = Integer.parseInt(s);
			if(count != 1 && (temp - 1) < count) {
				notFlag = true;
				break;
			}
			if(array[temp-1] == 0) {
				array[temp-1] = count;
				count++;
			}else {
				notFlag = true;
				break;
			}
		}
		if(!notFlag) {
			int orCo=0;
			for(int j=0;j<N*N ;j++) {
				if(array[j] != 0) {
					String co = String.valueOf(j+1);
					String value = String.valueOf(array[j]);
					order[orCo]= co+":"+value;
					orCo++;
				}
			}
			int point = 1;
			count = 1;
			for(int x =0 ; x<N ; x++) {
				String [] temp = order[x].split(":");
				int limit = Integer.parseInt(temp[0]);
				point = Integer.parseInt(temp[1]);
				for(int i=0 ; i<N*N ; i++) {
					if(limit-1 > i && array[i] == 0 && point != count) {
						array[i] = point;
						count++;
					}
				}
				if(count != point) {
					notFlag = true;
					break;
				}
				//point++;
				count = 1;
			}
			if(!notFlag) {
				point = 1;
				count = 0;
				for(int i=N*N-1 ;i>=0;i--) {
					int temp = N - point;
					if(array[i] == 0) {
						array[i] = point;
						count++;
					}
					if(count == temp) {
						count = 0;
						orCo++;
						point++;
					}
				}
			}
		}
		if(notFlag) {
			System.out.println("No");
		}else {
			System.out.println("Yes");
			int co = 1;
			for( int re : array ) {
				if(N*N > co) {
					System.out.print(re+" ");
				}else {
					System.out.print(re);
					System.out.println();
				}
				co++;
			}
		}
	}
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            final int n = in.nextInt();
            final int N = n * n;
            final int[] res = new int[N + 1];
            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                res[a] = i + 1;
            }
            int sum = 0;
            for (int i = 1; i <= N; ++i) {
                if (res[i] > 0)
                    sum += res[i];
                if (i < sum) {
                    out.println("No");
                    return;
                }
            }

            sum = 0;
            for (int i = N; i > 0; --i) {
                if (res[i] > 0)
                    sum += n - res[i];
                if ((N - i + 1) < sum) {
                    out.println("No");
                    return;
                }
            }

            List<Integer> order = new ArrayList<>();
            for (int i = 1; i<=N; ++i) {
                if (res[i] > 0) order.add(res[i]);
            }
            int pos = 0;
            int cnt = order.get(0) - 1;
            outerloop:
            for (int i =1 ; i <=N; ++i) {
                if (res[i] > 0) continue;
                while (cnt == 0) {
                    pos++;
                    if (pos >= order.size()) break outerloop;
                    cnt = order.get(pos) - 1;
                }
                res[i] = order.get(pos);
                cnt--;
            }
            if (cnt > 0) call();
            pos = order.size() - 1;
            cnt = n - order.get(order.size() - 1);
            outerloop1:
            for (int i = N; i > 0; --i) {
                if (res[i] > 0) continue;
                while (cnt == 0) {
                    pos--;
                    if (pos < 0) break outerloop1;
                    cnt = n - order.get(pos);
                }
                res[i] = order.get(pos);
                cnt--;
            }
            if (cnt > 0) call();
            out.println("Yes");
            for (int i = 1; i <= N; ++i) {
                if (i > 1) out.print(" ");
                out.print(res[i]);
            }
            out.println();

        }

        private void call() {
            throw new RuntimeException();
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

