class Algorithm {
  private static void swap(Object[] list, int a, int b) {
    Object tmp = list[a];
    list[a] = list[b];
    list[b] = tmp;
  }

  public static <T extends Comparable<? super T>> boolean nextPermutation(T[] ts) {
    int rightMostAscendingOrderIndex = ts.length - 2;
    while (rightMostAscendingOrderIndex >= 0 &&
        ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostAscendingOrderIndex + 1]) >= 0) {
      rightMostAscendingOrderIndex--;
    }
    if (rightMostAscendingOrderIndex < 0) {
      return false;
    }

    int rightMostGreatorIndex = ts.length - 1;
    while (ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostGreatorIndex]) >= 0) {
      rightMostGreatorIndex--;
    }

    swap(ts, rightMostAscendingOrderIndex, rightMostGreatorIndex);
    for (int i = 0; i < (ts.length - rightMostAscendingOrderIndex - 1) / 2; i++) {
      swap(ts, rightMostAscendingOrderIndex + 1 + i, ts.length - 1 - i);
    }
    return true;
  }
}

class Pair implements Comparable<Pair> {
  int v;
  int x;

  Pair(int v, int x) {
    this.v = v;
    this.x = x;
  }

  public int compareTo(Pair p) {
    return this.x - p.x;
  }
}

class Node {
  int v;
  int counts;
  boolean front;

  Node(int v, int counts, boolean front) {
    this.v = v;
    this.counts = counts;
    this.front = front;
  }
}

class Solver {
  public int[] solve(int n, int[] x) {
    int[] output = new int[n*n];
    Pair[] pairs = new Pair[n];
    for (int i = 0; i < n; i++) {
      pairs[i] = new Pair(i + 1, x[i]);
      output[x[i] - 1] = i + 1;
    }
    Arrays.sort(pairs);

    ArrayDeque<Node> queue = new ArrayDeque<>();
    for (int i = 0; i < pairs.length; i++) {
      int v = pairs[i].v;
      if (v - 1 > 0) {
        queue.addLast(new Node(v, v - 1, true));
      }
    }
    for (int i = 0; i < pairs.length; i++) {
      int v = pairs[i].v;
      if (n - v > 0) {
        queue.addLast(new Node(v, n - v, false));
      }
    }

    for (int i = 0; i < n*n; i++) {
      if (output[i] > 0) {
        continue;
      }

      Node node = queue.peekFirst();
      if (i < x[node.v - 1] != node.front) {
        return null;
      }
      output[i] = node.v;
      node.counts--;
      if (node.counts == 0) {
        queue.pollFirst();
      }
    }
    return output;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] x = reader.nextIntArray(n);
    int[] answer = new Solver().solve(n, x);
    if (answer != null) {
      out.println("Yes");
      out.print(answer[0]);
      for (int i = 1; i < answer.length; i++) {
        out.print(" ");
        out.print(answer[i]);
      }
      out.println();
    } else {
      out.println("No");
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            final int n = in.nextInt();
            final int N = n * n;
            final int[] res = new int[N + 1];
            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                res[a] = i + 1;
            }
            if (!(enoughSpaceLeft(res, n) && enoughSpaceRight(res, n))) {
                out.println("No");
                return;
            }
            List<Integer> order = new ArrayList<>();
            for (int i = 1; i<=N; ++i) {
                if (res[i] > 0) order.add(res[i]);
            }
            int[] freq = new int[n + 1];
            for (int i = 1; i <= n; i++)
                freq[i] = i - 1;
            put(res, order, freq, n);
            for (int i = 1; i <= n; ++i)
                freq[i] = n - i;
            put(res, order, freq, n);

            out.println("Yes");
            for (int i = 1; i <= N; ++i) {
                if (i > 1) out.print(" ");
                out.print(res[i]);
            }
            out.println();

        }

        private void put(int[] res, List<Integer> order, int[] freq, int n) {
            final int N = n * n;
            int pos = 0;
            for (int i =1 ; i <=N; ++i) {
                if (res[i] > 0) continue;
                while (pos < n && freq[order.get(pos)] == 0)
                    pos++;
                if (pos == n) break;
                res[i] = order.get(pos);
                freq[order.get(pos)]--;
            }
        }

        private boolean enoughSpaceRight(int[] res, int n) {
            int sum = 0;
            int N = n * n;
            for (int i = N; i > 0; --i) {
                if (res[i] > 0) sum += n - res[i] + 1;
                if ((N - i + 1) < sum) return false;
            }
            return true;
        }

        private boolean enoughSpaceLeft(int[] res, int n) {
            int sum = 0;
            int N = n * n;
            for (int i = 1; i <= N; ++i) {
                if (res[i] > 0) sum += res[i];
                if (i < sum) return false;
            }
            return true;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

