    void solve() throws IOException {
        int n = ni();
        int[] x = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = ni() - 1;
        }

        PriorityQueue<Pair> Q = new PriorityQueue<>();

        for (int i = 0; i < n; i++) {
            if (i > 0) Q.add(new Pair(i + 1, x[i] - 1, i));
        }

        int[] ans = new int[n * n];
        for (int i = 0; i < n; i++) {
            ans[x[i]] = i + 1;
        }

        for (int i = 0; i < n * n; i++) {
            if (ans[i] != 0) continue;

            Pair p = Q.poll();
            if (p.y < i) {
                out.println("No");
                return;
            }

            ans[i] = p.x;
            if (p.z > 1) {
                Q.add(new Pair(p.x, p.y, p.z - 1));
            }

            if (Q.isEmpty()) break;
        }

        if (!Q.isEmpty()) {
            out.println("No");
            return;
        }

        out.println(Arrays.toString(ans));

        Q = new PriorityQueue<>(Collections.reverseOrder());

        for (int i = 0; i < n; i++) {
            if (i < n) Q.add(new Pair(i + 1, x[i] + 1, n - 1 - i));
        }

        for (int i = n * n - 1; i >= 0; i--) {
            if (ans[i] != 0) continue;

            Pair p = Q.poll();
            if (p.y > i) {
                out.println("No");
                return;
            }

            ans[i] = p.x;
            if (p.z > 1) {
                Q.add(new Pair(p.x, p.y, p.z - 1));
            }

            if (Q.isEmpty()) break;
        }

        if (!Q.isEmpty()) {
            out.println("No");
            return;
        }

        out.println("Yes");
        for (int i = 0; i < n * n; i++) {
            if (i > 0) out.print(" ");
            out.print(ans[i]);
        }
        out.println();
    }

