public class Main {


  private static void solve() {
    int n = ni();
    int[][] x = new int[n][2];
    for (int i = 0; i < n; i ++) {
      x[i][0] = i + 1;
      x[i][1] = ni() - 1;
    }
    Arrays.sort(x, (o1, o2) -> o1[1] - o2[1]);

    int[] a = new int[n * n];
    int ptr = 0;
    Deque<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < n; i ++) {
      for (int j = 0; j < x[i][0] - 1; j ++) {
        q.add(x[i][0]);
      }
    }

    for (int i = 0; i < n; i ++) {

      while (ptr < x[i][1]) {
        if (q.size() == 0) {
          System.out.println("No");
          return;
        }
        a[ptr ++] = q.poll();
      }
      if (q.size() > 0 && q.peekFirst() == x[i][0]) {
        System.out.println("No");
        return;
      }
      a[ptr ++] = x[i][0];
      for (int j = 0; j < n - x[i][0]; j ++) {
        q.add(x[i][0]);
      }
    }

    while (q.size() > 0) {
      a[ptr ++] = q.poll();
