public class Main {



    public static void main(String[] args) throws Exception {
        IO io = new IO(null, null);
        int n = io.getNextInt();
        int [] X = new int[n+1];
        for (int i = 1;i <= n;i++)
            X[i] = io.getNextInt();
        int [] A = new int[n*n+1];
        for (int i = 1;i <= n;i++)
            A[X[i]] = i;
        boolean can = true;
        Deque<Integer> dq = new ArrayDeque<>();
        for (int i = A.length-1;i > 0 && can;i--){
            if (A[i] != 0)
                for (int j = 0;j < A[i]-1;j++)
                    dq.addFirst(A[i]);
        }
//        System.err.println(can);
//        System.err.println(Arrays.toString(A));
        for (int i = 1;i < A.length && can;i++) {
            if (A[i] == 0) {
                if (dq.isEmpty()) can = false;
                else A[i] = dq.pollFirst();
            }
            else {
                for (int j = A[i];j < n;j++)
                    dq.addLast(A[i]);
            }
        }
//        System.err.println(Arrays.toString(A));
        HashMap<Integer,Integer> HM = new HashMap<>();
        int [] C = new int[n*n+1];
        for (int i = 1;i <= n;i++) HM.put(i,0);
        for (int i = 1;i < A.length && can;i++){
            HM.put(A[i],HM.get(A[i]) + 1);
            C[i] = HM.get(A[i]);
        }
//        System.err.println(Arrays.toString(C));
        for (int i = 1;i <= n && can;i++)
            can &= C[X[i]] == i;
        if (can) {
            io.println("Yes");
            for (int i = 1;i < A.length;i++)
                io.print(A[i] + " ");
        }
        else io.println("No");
        io.close();
    }
}


