import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int[] a = in.nextInts(n);

        int[] ans = solve(a);
        if (ans == null) {
            out.println("No");
        } else {
            out.println("Yes");
            for (int i = 0; i < n*n ; i++) {
                if (i >= 1) {
                    out.print(' ');
                }
                out.print(ans[i]);
            }
            out.println();
        }
        out.flush();
    }

    private static int[] solve(int[] a) {
        int n = a.length;
        if (a[0] != 1 || a[n-1] != n*n) {
            return null;
        }
        for (int i = 0 ; i < n-1 ; i++) {
            if (a[i] > a[i+1]) {
                return null;
            }
        }

        int[] ret = new int[n*n];
        for (int i = 0; i < n ; i++) {
            ret[a[i]-1] = i+1;
        }


        int[] consumeQue = new int[n*n];
        int ch = 0;
        int ct = 0;
        for (int l = 2 ; l <= n ; l++) {
            for (int r = 0 ; r < l-1 ; r++) {
                consumeQue[ch++] = l;
            }
        }

        int[] freeQue = new int[n*n];
        int qh = 0;
        int qt = 0;

        for (int i = 0; i < ret.length; i++) {
            if (ret[i] != 0) {
                // yay! add numbers to queue!
                for (int k = ret[i] ; k < n ; k++) {
                    freeQue[qh++] = ret[i];
                }
            } else {
                if (ct < ch) {
                    ret[i] = consumeQue[ct++];
                } else if (qt < qh) {
                    ret[i] = freeQue[qt++];
                } else  {
                    return null;
                }
            }
        }
        return ret;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int[] nextInts(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }

        private int[][] nextIntTable(int n, int m) {
            int[][] ret = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextInt();
                }
            }
            return ret;
        }

        private long[] nextLongs(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        private long[][] nextLongTable(int n, int m) {
            long[][] ret = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextLong();
                }
            }
            return ret;
        }

        private double[] nextDoubles(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.*;
import java.util.*;

public class Main {

	static PrintWriter out;

	final static int INF = (int) 1e9;
	final static int MOD = (int) 1e9 + 7;
	final static long LINF = (long) 1e18;
	final static double PI = (double) Math.acos(-1.0);
	final static double EPS = (double) 1e-9;

	void solve() {
		int n = Input.nextInt();
		final int[] x = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = Input.nextInt() - 1;
		}
		TreeSet<Integer> st = new TreeSet<>();
		for (int i = 0; i < n * n; i++) {
			st.add(i);
		}
		int[] res = new int[n * n];
		for (int i = 0; i < n; i++) {
			res[x[i]] = i + 1;
			st.remove(x[i]);
		}
		ArrayList<Integer> v = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			v.add(i);
		}
		Collections.sort(v, new Comparator<Integer>() {
			public int compare(Integer i, Integer j) {
				return Integer.compare(x[i], x[j]);
			}
		});
		for (int j = 0; j < n; j++) {
			int i = v.get(j);
			int cnt = i;
			while (cnt > 0) {
				Integer k = st.lower(x[i]);
				if (k == null) {
					out.println("No");
					return;
				}
				res[k] = i + 1;
				cnt--;
				st.remove(k);
			}
		}
		Collections.sort(v, new Comparator<Integer>() {
			public int compare(Integer i, Integer j) {
				return Integer.compare(x[j], x[i]);
			}
		});
		for (int j = 0; j < n; j++) {
			int i = v.get(j);
			int cnt = n - i - 1;
			while (cnt > 0) {
				Integer k = st.higher(x[i]);
				if (k == null) {
					out.println("No");
					return;
				}
				res[k] = i + 1;
				cnt--;
				st.remove(k);
			}
		}
		out.println("Yes");
		for (int i = 0; i < n * n; i++) {
			out.printf("%d%c", res[i], " \n".charAt(i == n * n - 1 ? 1 : 0));
		}
	}

