	class Pair implements Comparable<Pair> {
		int v;
		int idx;

		Pair(int v, int idx) {
			this.v = v;
			this.idx = idx;
		}

		public int compareTo(Pair s) {
			return idx - s.idx;
		}

		public String toString() {
			return "(" + v + ", " + idx + ")";
		}
	}

	public void solve() {
		int n = in.nextInt(), n2 = n * n;
		int[] a = new int[n+1];
		for (int i = 1; i <= n; i++) {
			a[i] = in.nextInt();
		}

		int[] res = new int[n2+1];
		int[] cnt = new int[n+1];
		Arrays.fill(res, -1);
		for (int i = 1; i <= n; i++) {
			res[a[i]] = i;
			cnt[i]++;
		}

		PriorityQueue<Pair> pq = new PriorityQueue<>();
		Queue<Integer> free = new LinkedList<>();

		for (int i = 1; i <= n; i++) {
			pq.add(new Pair(i, a[i]));
		}

		for (int i = 1; i <= n2; i++) {
			if (res[i] != -1) {
				if (cnt[res[i]] == res[i]) {
					free.add(res[i]);
					continue;
				} else {
					System.out.println("No");
					return;
				}
			}
			if (!pq.isEmpty()) {
				Pair next = pq.peek();
				if (cnt[next.v] == next.v) {
					pq.poll(); i--;
					continue;
				} else {
					cnt[next.v]++;
					res[i] = next.v;
				}
			} else {
				while (!free.isEmpty()) {
					int next = free.peek();
					if (cnt[next] == n) {
						free.poll();
						continue;
					}
					res[i] = next;
					cnt[next]++;
					break;
				}

				if (res[i] == -1) {
					System.out.println("No");
					return;
				}
			}
		}
		out.println("Yes");
		for (int i = 1; i <= n2; i++) {
			out.print(res[i]);
			if (i != n2) out.print(" ");
		}
		out.println();
		out.close();
	}

