		int[] res = new int[n * n];
		for (int i = 0; i < n; i++) {
			res[x[i]] = i + 1;
		}
		for (int j = 0; j < n; j++) {
			int i = v.get(j);
			int cnt = i;
			for (int k = x[i] - 1; k >= 0 && cnt > 0; k--) {
				if (res[k] == 0) {
					res[k] = i + 1;
					cnt--;
				}
			}
			if (cnt > 0) {
				out.println("No");
				return;
			}
			cnt = n - i - 1;
			for (int k = n * n - 1; k > x[i] && cnt > 0; k--) {
				if (res[k] == 0) {
					res[k] = i + 1;
					cnt--;
				}
			}
			if (cnt > 0) {
				out.println("No");
				return;
			}
		}
		out.println("Yes");
		for (int i = 0; i < n * n; i++) {
			out.printf("%d%c", res[i], " \n".charAt(i == n * n - 1 ? 1 : 0));
		}
	}

