import java.io.*;
import java.util.Arrays;
import java.util.Comparator;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static int[] X;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        X = sc.nextIntArray(N);

        int[] ans = solve();
        if( ans != null ) {
            System.out.println("YES");
            writeSingleLine(ans);
        } else {
            System.out.println("No");
        }
    }

    static int[] solve() {
        int[][] XI = new int[N][2];
        for (int i = 0; i < N; i++) {
            XI[i][0] = i+1;
            XI[i][1] = X[i];
        }
        Arrays.sort(XI, Comparator.comparingInt(xi -> xi[1]));

        Integer[] ans = new Integer[N*N];
        int next = 0;
        for (int[] xi : XI) {
            int i = xi[0]; // [1, n]
            int x = xi[1]; // i番目のiが入る場所

            // もう入っていた...
            if( ans[x-1] != null ) return null;
            ans[x-1] = i;

            int left = i - 1;
            for (int j = 0; j < left; j++) {
                while( next < N*N && ans[next] != null ) {
                    next++;
                }
                // nextを超えたらおかしい
                if( next < N*N && next < x-1 && ans[next] == null ) {
                    ans[next] = i;
                } else {
                    return null;
                }
            }
        }

        // 余った場所に余りを詰める
        for (int i = 1; i <= N; i++) {
            int right = N-i;
            for (int j = 0; j < right; j++) {
                while( next < N*N && ans[next] != null ) {
                    next++;
                }

                if( next < N*N && ans[next] == null ) {
                    ans[next] = i;
                } else {
                    return null;
                }
            }
        }

        int[] ret = new int[N*N];
        for (int i = 0; i < N*N; i++) {
            ret[i] = (ans[i] != null) ? ans[i] : -1;
        }
        return ret;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(as[i]);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg == null) j.add("null");
            else if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < array.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(array[i]);
        }
        pw.println();
        pw.flush();
    }

    static int lowerBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] < value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] <= value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args)throws Exception {
		BufferedReader br = new BufferedReader ( new InputStreamReader(System.in));
		int N = Integer.parseInt(br.readLine());
		String [] input = br.readLine().split(" ");
		int [] array = new int[N*N];
		int count = 1;
		boolean notFlag = false;
		for(String s : input) {
			int temp = Integer.parseInt(s);
			if(count != 1 && (temp - 1) < count) {
				notFlag = true;
				break;
			}
			if(array[temp-1] == 0) {
				array[temp-1] = count;
				count++;
			}else {
				notFlag = true;
				break;
			}
		}
		int point = 1;
		count = 1;
		for(String s : input) {
			int limit = Integer.parseInt(s);
			for(int i=0 ; i<N*N ; i++) {
				if(limit-1 > i && array[i] == 0 && point != count) {
					array[i] = point;
					count++;
				}
			}
			if(count != point) {
				notFlag = true;
				break;
			}
			point++;
			count = 1;
		}
		point = 1;
		count = 0;
		for(int i=0 ;i<N*N;i++) {
			int temp = N - point;
			if(array[i] == 0) {
				array[i] = point;
				count++;
			}
			if(count == temp) {
				count = 0;
				point++;
			}
		}
		if(notFlag) {
			System.out.println("No");
		}else {
			System.out.println("Yes");
			int co = 1;
			for( int re : array ) {
				if(N*N > co) {
					System.out.print(re+" ");
				}else {
					System.out.print(re);
					System.out.println();
				}
				co++;
			}
		}
	}
}

