    static class DKThK {
        public void solve(int testNumber, LightScanner2 in, LightWriter2 out) {
            int n = in.ints(), m = n * n;
            int[] x = new int[n], res = new int[m];
            for (int i = 0; i < n; i++) x[i] = in.ints() - 1;
            Arrays.fill(res, -1);
            PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.comparingInt(i -> x[i]));
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) pq.offer(i);
                res[x[i]] = i;
            }
            for (int i = 0; i < m; i++) {
                if (res[i] == -1) {
                    if (pq.isEmpty()) {
                        out.noln();
                        return;
                    }
                    res[i] = pq.poll();
                } else if (!pq.isEmpty() && pq.peek() == res[i]) {
                    out.noln();
                    return;
                } else {
                    x[res[i]] = Integer.MAX_VALUE;
                    for (int j = 0; j < n - res[i] - 1; j++) pq.offer(res[i]);
                }
            }
            out.yesln();
            for (int i = 0; i < m; i++) out.ans(res[i] + 1);
            out.ln();
        }

    }

    static abstract class LightScannerAdapter implements AutoCloseable {
