import java.io.*;
import java.util.Arrays;
import java.util.Comparator;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static int[] X;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        X = sc.nextIntArray(N);

        int[] ans = solve();
        if( ans != null ) {
            System.out.println("Yes");
            writeSingleLine(ans);
        } else {
            System.out.println("No");
        }
    }

    static int[] solve() {
        int[][] XI = new int[N][2];
        for (int i = 0; i < N; i++) {
            XI[i][0] = i+1;
            XI[i][1] = X[i];
        }
        Arrays.sort(XI, Comparator.comparingInt(xi -> xi[1]));

        Integer[] ans = new Integer[N*N];
        int next = 0;
        for (int[] xi : XI) {
            int i = xi[0]; // [1, n]
            int x = xi[1]; // i番目のiが入る場所

            // もう入っていた...
            if( ans[x-1] != null ) return null;
            ans[x-1] = i;

            int left = i - 1;
            for (int j = 0; j < left; j++) {
                while( next < N*N && ans[next] != null ) {
                    next++;
                }
                // nextを超えたらおかしい
                if( next < N*N && next < x-1 && ans[next] == null ) {
                    ans[next] = i;
                } else {
                    return null;
                }
            }
        }

        // 余った場所に余りを詰める
        for (int i = 1; i <= N; i++) {
            int right = N-i;
            for (int j = 0; j < right; j++) {
                while( next < N*N && ans[next] != null ) {
                    next++;
                }

                if( next < N*N && ans[next] == null ) {
                    ans[next] = i;
                } else {
                    return null;
                }
            }
        }

        int[] ret = new int[N*N];
        for (int i = 0; i < N*N; i++) {
            ret[i] = (ans[i] != null) ? ans[i] : -1;
        }
        return ret;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
