	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int N;
		int[] x;
		void Read()
		{
			N = sc.Int;
			x = sc.ReadMany<int>();
		}
		int[] a;
		int l, r, N2;
		void SolveOne()
		{
			N2 = N * N;
			a = new int[N2];
			for (var i = 0; i < N2; i++) a[i] = -1;
			for (var i = 0; i < N; i++) a[--x[i]] = i;
			l = 0; r = N2 - 1;
			var qs = new List<Tuple<int, int>>();
			for (var i = 0; i < N; i++) qs.Add(new Tuple<int, int>(i, x[i]));
			qs.Sort((_x, _y) => _x.Item2.CompareTo(_y.Item2));
			var flag = true;
			foreach (var q in qs)
			{
				if (!flag) break;
				for (var i = 0; flag && i < q.Item1; i++)
				{
					while (l < N2 && a[l] >= 0) l++;
					if (flag &= l < q.Item2) a[l] = q.Item1;
				}
			}
			qs.Reverse();
			foreach (var q in qs)
			{
				if (!flag) break;
				for (var i = 0; flag && i < N - 1 - q.Item1; i++)
				{
					while (r >= 0 && a[r] >= 0) r--;
					if (flag &= r > q.Item2) a[r] = q.Item1;
				}
			}
			for (var i = 0; flag && i < N2; i++) flag &= a[i] >= 0;
			var b = new int[N];
			for (var i = 0; flag && i < N2; i++)  if (b[a[i]]++ == a[i]) flag &= i == x[a[i]];
			for (var i = 0; i < N2; i++) a[i]++;
			pr.WriteLine(flag ? "Yes" : "No");
			if (flag) pr.WriteLine(string.Join(" ", a));
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			  {
				  if (r[i] != r[j]) return r[i] - r[j];
				  var a = i + k <= N ? r[i + k] : -1;
				  var b = j + k <= N ? r[j + k] : -1;
				  return a - b;
			  };
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
