using System;
using System.Collections.Generic;

public class Program
{
    private int N;
    private int[] X;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        X = sc.IntArray();

        int[] ans = new int[N * N];

        int[] ar = new int[N * N];
        for (int i = 0; i < N; i++)
        {
            ar[X[i] - 1] = i + 1;
            ans[X[i] - 1] = i + 1;
        }

        var q = new Queue<int>();

        for (int i = 0; i < N * N; i++)
        {
            if (ar[i] == 0)
            {
                q.Enqueue(i);
            }
            else
            {
                int n = ar[i];
                for (int j = 0; j < n - 1; j++)
                {
                    if (q.Count <= 0)
                    {
                        Console.WriteLine("No");
                        return;
                    }

                    ans[q.Dequeue()] = n;
                }
            }
        }

        q = new Queue<int>();
        for (int i = N * N - 1; i >= 0; i--)
        {
            if (ans[i] == 0)
            {
                q.Enqueue(i);
            }
            else if (ar[i] != 0)
            {
                int n = ar[i];
                for (int j = 0; j < N - n; j++)
                {
                    if (q.Count <= 0)
                    {
                        Console.WriteLine("No");
                        return;
                    }

                    ans[q.Dequeue()] = n;
                }
            }
        }
        Console.WriteLine("Yes");
        Console.WriteLine(string.Join(" ",ans));
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

