    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var a = sc.Integer(n);
            var ans = new List<int>();

            var rem = new Queue<int>();
            foreach (var idx in Enumerate(n, x => x).OrderBy(x => a[x]))
            {
                for (int i = 0; i < idx; i++)
                    rem.Enqueue(idx);
            }
            foreach (var idx in Enumerate(n, x => x).OrderBy(x => a[x]))
            {
                var to = a[idx];
                while (ans.Count + 1 < to && rem.Count > 0)
                {
                    ans.Add(rem.Dequeue());
                }
                ans.Add(idx);
                if (ans.Count != to) break;
                for (int i = idx + 1; i < n; i++)
                    rem.Enqueue(idx);
            }
            while (rem.Count > 0)
                ans.Add(rem.Dequeue());
            Debug.WriteLine(rem.Count);
            Debug.WriteLine(ans.AsJoinedString());

            if (ans.Count != n * n)
            {
                IO.Printer.Out.WriteLine("No");
                return;
            }
            var cnt = new int[n];
            for (int i = 0; i < n * n; i++)
            {
                cnt[ans[i]]++;
                if (cnt[ans[i]] == ans[i] + 1)
                {
                    if (i + 1 != a[ans[i]])
                    {
                        Debug.WriteLine("otaku");
                        IO.Printer.Out.WriteLine("No");
                        return;
                    }
                }
            }

            for (int i = 0; i < n * n; i++)
                ans[i]++;
            IO.Printer.Out.WriteLine("Yes");
            IO.Printer.Out.WriteLine(ans.AsJoinedString());
        }


