        /// </summary>
        void SolveOne()
        {
            int n = sc.nextInt();
            int[] x = sc.nextInt(n);
            int[] ls = new int[n];
            for (int i = 0; i < n; i++)
            {
                ls[i] = i + 1;
            }
            Array.Sort(x, ls);
            bool ok = true;
            int[] dest = new int[n * n + 1];    // kimatteiru tokoro
            int[] ans = new int[n * n + 1];     // kotae
            /*
            Dictionary<int, int> dic = new Dictionary<int, int>();
            int[] sorttmp = new int[n];


            for (int i = 0; i < n; i++)
            {
                dic.Add(x[i], i + 1);
                sorttmp[i] = x[i];
            }
            Array.Sort(sorttmp);
            */

            for (int i = 0; i < n; i++)
            {
                //ls[i] = dic[sorttmp[i]];
                dest[x[i]] = i + 1;
            }

            int[] cnt = new int[n + 1]; // tukatta kaisuu
            int next = 0;
            bool nisyuume = false;
            for (int i = 1; i <= n*n; i++)
            {
                if(dest[i]>0)
                {
                    if (cnt[dest[i]]+ 1 != dest[i])
                    {
                        ok = false;
                        break;
                    }
                    else
                    {
                        ans[i] = dest[i];
                        cnt[dest[i]]++;
                    }
                } 
                else
                {
                    if (nisyuume == false)
                    {
                        while (cnt[ls[next]] >= ls[next] - 1)
                        {
                            next++;
                            if(next >=n)
                            {
                                next = 0;
                                nisyuume = true;
                                break;
                            }
                        }
                    }
                    if(nisyuume == true)
                    {
                        while(cnt[ls[next]] >=n)
                        {
                            next++;
                            if (next >= n - 1) break;
                        }
                    }
                    ans[i] = ls[next];
                    cnt[ls[next]]++;                    
                }

            }
            if(ok)
            {
                Console.WriteLine("Yes");
                for (int i = 1; i <= n * n; i++)
                {
                    if (i > 1) Console.Write(" ");
                    Console.Write(ans[i]);
                }
                Console.WriteLine();
            }
            else
            {
                Console.WriteLine("No");
            }

        }
    }
