using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		long n = long.Parse(Console.ReadLine());
    long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long[] answers = new long[n*n];
    long[][] numPositions = new long[n][];
    for(long i = 0; i < n; i++)
    {
      numPositions[i] = new long[2];
      numPositions[i][0] = i;
      numPositions[i][1] = nums[i]-1;
    }
    Array.Sort(numPositions, (a, b) => a[1].CompareTo(b[1]));
    bool answer = true;

    for(long i = 0; i < n; i++)
    {
      answers[numPositions[i][1]] = numPositions[i][0]+1;
    }

    long leftNum = 0;
    long rightNum = n*n-1;
    for(long i = 0; i < n; i++)
    {
      for(long j = 0; j < numPositions[i][0]; j++)//置く個数
      {
        while(answers[leftNum] != 0)
        {
          if(leftNum < n*n-1) leftNum++;
        }

        if(leftNum >= numPositions[i][1])
        {
          answer = false;
          break;
        }else
        {
          answers[leftNum] = numPositions[i][0]+1;
          leftNum++;
        }
      }
    }

    for(long i = 0; i < n; i++)
    {
      for(long j = 0; j < n-numPositions[i][0]-1; j++)//置く個数
      {
        while(answers[rightNum] != 0)
        {
          if(rightNum > 0) rightNum--;
        }

        if(rightNum <= numPositions[i][1])
        {
          answer = false;
          break;
        }else
        {
          answers[rightNum] = numPositions[i][0]+1;
          rightNum--;
        }
      }
    }

    if(answer)
    {
      Console.WriteLine("Yes");
		  Console.WriteLine(string.Join(" ", answers));
    }else Console.WriteLine("No");
	}
}

using System;
using System.Text;
using System.Collections.Generic;
class Solve{
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        string[] str = Console.ReadLine().Split(' ');
        int[] X = new int[N];
        for(int i=0;i<N;i++){
            X[i] = int.Parse(str[i]);
        }
        int[] a = new int[N];
        for(int i=0;i<N;i++){
            a[i] = i;
        }
        Array.Sort(a,(x,y) => X[x]-X[y]);
        int[] L = new int[N];
        for(int i=0;i<N;i++){
            L[i] = N;
        }
        int[] Y = new int[N*N];
        bool[] finished = new bool[N*N];
        int p = 0;
        bool b = true;
        for(int i=0;i<N;i++){
            int d = a[i] + 1;
            finished[X[a[i]]-1] = true;
            Y[X[a[i]]-1] = a[i] + 1;
            L[a[i]] -= a[i] + 1; 
            for(int j=0;j<a[i];j++){
                while(p < N && finished[p]){
                    p++;
                }
                Y[p] = d;
                p++;
                if(j != a[i] - 1 && p > X[a[i]] - 1){
                    b = false;
                }
            }
        }
        int q = 0;
        for(;p<N*N;p++){
            if(finished[p]){
                continue;
            }
            while(q < N && L[q] == 0){
                q++;
            }
            if(q == N){
                b = false;
                break;
            }
            else{
                Y[p] = q+1;
                if(p < X[q]){
                    b = false;
                }
                L[q]--;
            }
        }
        if(b){
            sb.Append("Yes\n");
            for(int i=0;i<N*N;i++){
                sb.Append(Y[i]+" ");
            }
            sb.Append("\n");
        }
        else{
            sb.Append("No\n");
        }
    }
}

