        /// </summary>
        void SolveOne()
        {
            int n = sc.nextInt();
            int[] x = sc.nextInt(n);
            bool ok = true;
            int[] dest = new int[n * n + 1];    // kimatteiru tokoro
            int[] ans = new int[n * n + 1];     // kotae
            Dictionary<int, int> dic = new Dictionary<int, int>();
            int[] sorttmp = new int[n];

            for (int i = 0; i < n; i++)
            {
                dic.Add(x[i], i + 1);
                sorttmp[i] = x[i];
            }
            Array.Sort(sorttmp);
            int[] ls = new int[n];
            for (int i = 0; i < n; i++)
            {
                ls[i] = dic[sorttmp[i]];
            }

            for (int i = 0; i < n; i++)
            {
                dest[x[i]] = i + 1;
            }

            int[] cnt = new int[n + 1];
            for (int i = 1; i <= n*n; i++)
            {
                if(dest[i]>0)
                {
                    if (cnt[dest[i]]+ 1 != dest[i])
                    {
                        ok = false;
                        break;
                    }
                    else
                    {
                        ans[i] = dest[i];
                        cnt[dest[i]]++;
                    }
                } 
                else
                {
                    bool done = false;
                    for (int j = 0; j < n; j++)
                    {
                        if(cnt[ls[j]]< ls[j] - 1)
                        {
                            done = true;
                            ans[i] = ls[j];
                            cnt[ls[j]]++;
                            break;
                        }
                    }
                    if(done==false)
                    {
                        for (int j = 0; j < n; j++)
                        {
                            if (cnt[ls[j]] < n)
                            {
                                done = true;
                                ans[i] = ls[j];
                                cnt[ls[j]]++;
                                break;
                            }
                        }
                    }
                }

            }
            if(ok)
            {
                Console.WriteLine("Yes");
                for (int i = 1; i <= n * n; i++)
                {
                    if (i > 1) Console.Write(" ");
                    Console.Write(ans[i]);
                }
                Console.WriteLine();
            }
            else
            {
                Console.WriteLine("No");
            }

        }
    }
