class Solver
{
    Scanner sc = new Scanner();
    //
    public void Solve()
    {
        var N = sc.Int;
        var res = new int[N * N];
        var xs = new Pi[N];
        var q = new Queue<int>();
        for(var i = 0; i < N; i++)
        {
            var x = sc.Next<int>();
            xs[i] = new Pi(x, i);
            res[x - 1] = i + 1;
        }
        Array.Sort(xs, (a, b) => a.v1 - b.v1);
        var s = 0;
        for (var i = 0; i < N; i++)
        {
            s += xs[i].v2;
            for (var j = 0; j < xs[i].v2; j++)
                q.Enqueue(xs[i].v2 + 1);
        }
        var idx = 0;
        foreach (var x in xs)
        {
            while (idx <= x.v1 - 2)
            {
                if (!q.Any()) Fail("No");
                res[idx] = q.Dequeue();idx++;
            }
            if (q.Any() && q.Peek() == x.v2 + 1) Fail("No");
            idx++;
            for (var j = x.v2+1; j < N; j++)
                q.Enqueue(x.v2 + 1);
        }
        WriteLine("Yes");
        Console.WriteLine(string.Join(" ", res));
    }
}

