public class BinaryIndexedTree {
	private long[] data;
	private int max;

	public BinaryIndexedTree(long sz) { 
		data = new long[++sz]; 
		max = 1;
        while ((max << 1) < data.Length) max <<= 1;
	}
	public long Sum(long k) {
		long ret = 0;
		for(++k; k > 0; k -= k & -k) ret += data[k];
		return ret;
	}
	public long Sum(long k1, long k2) {	// [k1, k2]
		return (Sum(k2) - (0<k1 ? Sum(k1 - 1) : 0));
	}
	public void Add(long k, long x) { for(++k; k < data.Length; k += k & -k) data[k] += x; }
    public long LowerBound(long v) {
		if (v <= 0) return 0;
		int x = 0;
		for (int k = max; k > 0; k >>= 1) {
			if (x + k < data.Length && data[x + k] < v) {
				v -= data[x + k];
				x += k;
			}
		}
		return x;
    }

}














