public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int[] x = sc.IntArray();

        var sortedX = new int[n];
        for (int i = 0; i < n; i++)
        {
            sortedX[i] = i;
        }

        Array.Sort(sortedX, (l, r) => sortedX[l].CompareTo(sortedX[r]));

        int[] a = new int[n * n];
        int index = 0;
        foreach (int i in sortedX)
        {
            for (int j = 0; j < i; j++)
            {
                while (a[index] != 0)
                {
                    index++;
                }

                a[index++] = i + 1;
            }

            if (a[x[i] - 1] != 0)
            {
                Console.WriteLine("No");
                return;
            }

            a[x[i] - 1] = i + 1;
        }

        index = n * n - 1;
        for (int t = n - 1; t >= 0; t--)
        {
            int i = sortedX[t] + 1;
            for (int j = 0; j < n - i; j++)
            {
                while (a[index] != 0)
                {
                    if (a[index] == i)
                    {
                        Console.WriteLine("No");
                        return;
                    }

                    index--;
                }

                a[index--] = i;
            }
        }

        Console.WriteLine("Yes");
        Console.WriteLine(string.Join(" ", a));
    }

