using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int[] x = sc.IntArray();

        int[] ans = new int[n * n];
        for (int i = 0; i < n; i++)
        {
            ans[x[i] - 1] = i + 1;
        }

        var q = new Queue<int>();
        for (int i = 0; i < n * n; i++)
        {
            if (ans[i] == 0)
            {
                q.Enqueue(i);
            }
            else
            {
                if (q.Count < ans[i] - 1)
                {
                    Console.WriteLine("No");
                    return;
                }

                for (int j = 0; j < ans[i] - 1; j++)
                {
                    ans[q.Dequeue()] = ans[i];
                }
            }
        }

        bool[] f = new bool[n+1];
        q = new Queue<int>();
        for (int i = n * n - 1; i >= 0; i--)
        {
            if (ans[i] == 0)
            {
                q.Enqueue(i);
            }
            else
            {
                if(f[ans[i]]) continue;
                if (q.Count < n - ans[i])
                {
                    Console.WriteLine("No");
                    return;
                }

                for (int j = 0; j < n - ans[i]; j++)
                {
                    ans[q.Dequeue()] = ans[i];
                }

                f[ans[i]] = true;
            }
        }

        Console.WriteLine("Yes");
        Console.WriteLine(string.Join(" ", ans));
    }

    public static void Main(string[] args) => new Program().Solve();
}

