class Solver
{
    Scanner sc = new Scanner();
    //
    public void Solve()
    {
        var N = sc.Int;
        var res = new int[N * N];
        var xs = new Pi[N];
        var q = new Queue<int>();
        for(var i = 0; i < N; i++)
        {
            var x = sc.Next<int>();
            xs[i] = new Pi(x, i);
            res[x - 1] = i + 1;
        }
        Array.Sort(xs, (a, b) => a.v1 - b.v1);
        for (var i = 0; i < N; i++)
        {
            if (xs[i].v1 - xs[i].v2 - i <= 0) 
                Fail("No");
            for (var j = 0; j < xs[i].v2; j++)
                q.Enqueue(xs[i].v2 + 1);
        }
        var idx = 0;
        foreach (var x in xs)
        {
            while (idx <= x.v1 - 2)
            {
                res[idx] = q.Dequeue();idx++;
            }
            idx++;
            for (var j = x.v2+1; j < N; j++)
                q.Enqueue(x.v2 + 1);
        }
        WriteLine("Yes");
        Console.WriteLine(string.Join(" ", res));
    }
}

