public static class P
{
    public static void Main()
    {
        Action abort = () => { Console.WriteLine("No"); Environment.Exit(0); };

        int n = int.Parse(Console.ReadLine());
        var x = Console.ReadLine().Split().Select(y => int.Parse(y) - 1).ToArray();
        Queue<int> remainItem = new Queue<int>();
        int[] res = new int[n * n];
        int ind = 0;
        foreach (var item in x.Select((Index, Item) => new { Item = Item + 1, Index }).OrderBy(y => y.Index))
        {
            for (int i = 0; i < item.Item - 1; i++)
            {
                while (res[ind] != 0) ind++;
                if (item.Index <= ind) abort();
                res[ind] = item.Item;
            }
            res[item.Index] = item.Item;
            for (int i = item.Item; i < n; i++)
                remainItem.Enqueue(item.Item);
        }
        while (remainItem.Count > 0)
        {
            while (res[ind] != 0) ind++;
            var item = remainItem.Dequeue();
            if (ind < x[item - 1]) abort();
            res[ind] = item;
        }
        Console.WriteLine("Yes");
        Console.WriteLine(string.Join(" ", res));
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
    int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
		int[] answers = new int[n*n];
    int[][] numPositions = new int[n][];
    for(int i = 0; i < n; i++)
    {
      numPositions[i] = new int[2];
      numPositions[i][0] = i;
      numPositions[i][1] = nums[i]-1;
    }
    Array.Sort(numPositions, (a, b) => a[1].CompareTo(b[1]));
    bool answer = true;

    answers[numPositions[0][1]] = numPositions[0][0]+1;
    for(int i = 1; i < n; i++)
    {
      if(answers[numPositions[i][1]] != 0) answer = false;
      answers[numPositions[i][1]] = numPositions[i][0]+1;
    }

    int leftNum = 0;
    int rightNum = n*n-1;
    for(int i = 0; i < n; i++)
    {
      for(int j = 0; j < numPositions[i][0]; j++)//置く個数
      {
        while(answers[leftNum] != 0)
        {
          if(leftNum < n*n-1) leftNum++;
        }

        if(leftNum >= numPositions[i][1])
        {
          answer = false;
          break;
        }else
        {
          answers[leftNum] = numPositions[i][0]+1;
          leftNum++;
        }
      }
    }

    for(int i = 0; i < n; i++)
    {
      for(int j = 0; j < n-numPositions[i][0]-1; j++)//置く個数
      {
        while(answers[rightNum] != 0)
        {
          if(rightNum > 0) rightNum--;
        }

        if(rightNum <= numPositions[i][1])
        {
          answer = false;
          break;
        }else
        {
          answers[rightNum] = numPositions[i][0]+1;
          rightNum--;
        }
      }
    }

    if(answer)
    {
      Console.WriteLine("Yes");
		  Console.WriteLine(string.Join(" ", answers));
    }else Console.WriteLine("No");
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using static System.Console;
using static System.Math;

namespace AtTest.AGC_Challenge
{
    class _008_D
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] xs = ReadInts();
            int[][] xIndexes = new int[n][];
            for(int i = 0; i < n; i++)
            {
                xIndexes[i] = new int[2] { xs[i] - 1, i + 1 };
            }
            Array.Sort(xIndexes, (a, b) => a[0] - b[0]);
            Queue<int> que = new Queue<int>();
            for(int i = 0; i < n; i++)
            {
                for(int j = 1; j < xIndexes[i][1]; j++)
                {
                    que.Enqueue(xIndexes[i][1]);
                }
            }
            int[] res = new int[n * n];
            int now = 0;
            int[] cnts = new int[n];
            for(int i = 0; i < n * n; i++)
            {
                if (now < n && i == xIndexes[now][0])
                {
                    if (cnts[xIndexes[now][1] - 1] == xIndexes[now][1] - 1)
                    {
                        res[i] = xIndexes[now][1];
                        cnts[xIndexes[now][1] - 1]++;
                        for (int j = xIndexes[now][1]; j < n; j++)
                        {
                            que.Enqueue(xIndexes[now][1]);
                        }
                        now++;
                    }
                    else
                    {
                        WriteLine("No");
                        return;
                    }
                }
                else
                {
                    if (que.Count > 0)
                    {
                        res[i] = que.Peek();
                        cnts[que.Dequeue() - 1]++;
                    }
                    else
                    {
                        WriteLine("No");
                        return;
                    }
                }
            }

            WriteLine("Yes");
            for(int i = 0; i < n*n; i++)
            {
                Write(res[i]+" ");
            }
            WriteLine();
        }

        private static string Read() { return ReadLine(); }
        private static char[] ReadChars() { return Array.ConvertAll(Read().Split(), a => a[0]); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

