def solve():
    N = int(input())
    Xs = [(X, i+1) for i, X in enumerate(map(int, input().split()))]

    N2 = N**2
    Xs.sort()

    As = [0] * (2*N2+1)
    for X, no in Xs:
        As[X] = no

    iA = 1
    for X, no in Xs:
        num = no-1
        while num:
            if As[iA] == 0:
                As[iA] = no
                num -= 1
            iA += 1
        if iA > X:
            return []

    for X, no in Xs:
        while As[iA] != 0:
            iA += 1
        if iA <= X:
            return []
        num = N-no
        while num:
            if As[iA] == 0:
                As[iA] = no
                num -= 1
            iA += 1

    if iA != N2+1:
        return []

    return As[1:iA]


