def solve(X):
    N = len(X)
    X = sorted((x,i) for i,x in enumerate(X, start=1))
    L = N**2
    res = [-1]*L
    i = 0
    for x,n in X:
        r = n-1
        while r > 0 and i < x:
            if res[i] < 0:
                res[i] = n
                r -= 1
            i += 1
        if res[x] > 0 or r > 0:
            return None
        else:
            res[x] = n
    i = L
    for x,n in reversed(X):
        r = N-n
        while r > 0 and i > x:
            if res[i-1] < 0:
                res[i-1] = n
                r -= 1
            i -= 1
        if r > 0:
            return None

    return res

