                i += 1
            ans[i] = k
            i += 1
            j -= 1
        if i > x:
            return False
        ans[x] = k

    for x, k in yyy:
        while i < n2 and ans[i] != -1:
            i += 1
        if i < x:
            return False
        j = n - k
        while j:
            while i < n2 and ans[i] != -1:
                i += 1
            if i == n2:
                return False
            ans[i] = k
            i += 1
            j -= 1

    return ans


