que = deque()
for p, i in P:
    ans[p] = i
    for _ in range(i - 1):
        que.append(i)

for p in range(1, N ** 2 + 1):
    if not que:
        break
    if ans[p] is not None:
        i = ans[p]
        for _ in range(N - i):
            que.append(i)
    else:
        ans[p] = que.popleft()


def is_ok(ans, que):
    if que:
        return False
    for a in ans[1:]:
        if a is None:
            return False
    counts = defaultdict(int)
    C = [0]
    for a in ans[1:]:
        counts[a] += 1
        C.append(counts[a])
    for i, x in enumerate(X, 1):
        if C[x] != i:
            return False
    return True


if is_ok(ans, que):
    print('Yes')
    print(*ans[1:])
else:
    print('No')

