fn main() {
    input! { n, x: [usize1; n] };
    let mut ans = vec![0; n * n];
    for i in 0..n {
        ans[x[i]] = i + 1;
    }
    let mut idx = (0..n).collect::<Vec<_>>();
    idx.sort_by_key(|&i| x[i]);
    let mut i = 0;
    let mut j = 0;
    let mut need = (0..n).collect::<Vec<_>>();
    let mut free = vec![];
    while j < n * n {
        if ans[j] != 0 {
            if need[ans[j] - 1] > 0 {
                println!("No");
                return;
            }
            free.extend((0..n - ans[j]).map(|_| ans[j]));
            j += 1;
            continue;
        }
        while i < n && need[idx[i]] == 0 {
            i += 1;
        }
        if i < n {
            ans[j] = idx[i] + 1;
            need[idx[i]] -= 1;
        } else if let Some(x) = free.pop() {
            ans[j] = x;
        } else {
            println!("No");
            return;
        }
        j += 1;
    }
    println!("Yes");
    for i in 0..n * n {
        print!("{} ", ans[i]);
    }
    println!("");
}

