use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let x: Vec<usize> = sc.vec(n);
    let mut x: Vec<(usize, usize)> = x
        .into_iter()
        .enumerate()
        .map(|(i, pos)| (i + 1, pos - 1))
        .collect();
    x.sort_by_key(|x| x.1);
    let mut ans = vec![0; n * n];
    let mut cur = 0;
    let mut q = VecDeque::new();
    for &(i, pos) in x.iter() {
        while cur < pos {
            if ans[cur] == 0 {
                q.push_back(cur);
            }
            cur += 1;
        }
        for _ in 0..(i - 1) {
            if let Some(ans_i) = q.pop_front() {
                assert_eq!(ans[ans_i], 0);
                ans[ans_i] = i;
            } else {
                println!("No");
                return;
            }
        }
        assert_eq!(cur, pos);
        ans[cur] = i;
        cur += 1;
    }

    let mut k_th_k = vec![false; n * n];
    for &(_, pos) in x.iter() {
        k_th_k[pos] = true;
    }

    let mut q = VecDeque::new();
    for i in (0..(n * n)).rev() {
        if k_th_k[i] {
            assert_ne!(ans[i], 0);
            let v = ans[i];
            let remain = n - v;
            for _ in 0..remain {
                if let Some(i) = q.pop_front() {
                    assert_eq!(ans[i], 0);
                    ans[i] = v;
                } else {
                    println!("No");
                    return;
                }
            }
        } else if ans[i] == 0 {
            q.push_front(i);
        }
    }

    println!("Yes");
    for i in 0..(n * n) {
        if i > 0 {
            print!(" ");
        }
        print!("{}", ans[i]);
    }
    println!();
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let x: Vec<usize> = (0..n).map(|_| read::<usize>() - 1).collect();
    let mut data: Vec<(usize, usize)> = vec![(0, 0); n];
    for i in 0..n {
        data[i] = (x[i], i);
    }
    data.sort();

    let mut check = true;
    let inf = 1 << 29;
    let mut ans: Vec<usize> = vec![inf; n * n];
    for i in 0..n {
        ans[data[i].0] = i;
    }
    let mut now = 0;
    let mut count = 0;
    let mut before = true;
    for i in 0..n * n {
        if ans[i] == inf {
            if before {
                if data[now].1 == 0 {
                    now += 1;
                    count = 0;
                }
                ans[i] = data[now].1;
                count += 1;
                if count >= data[now].1 {
                    if now == n - 1 || (now == n - 2 && data[now + 1].1 == 0) {
                        before = false;
                        now = 0;
                        count = data[now].1;
                    } else {
                        now += 1;
                        count = 0;
                    }
                }
            } else {
                if data[now].1 == n - 1 {
                    now += 1;
                    count = data[now].1;
                }
                ans[i] = data[now].1;
                count += 1;
                if count >= n - 1 {
                    now += 1;
                    if now < n {
                        count = data[now].1;
                    }
                }
            }
        } else {
            if (before && ((now < ans[i]) || (now == ans[i] && count < data[now].1)))
                || (!before && ((now > ans[i]) || (now == ans[i] && count > data[now].1)))
            {
                check = false;
                break;
            }
            ans[i] = data[ans[i]].1;
        }
    }

    if check {
        println!("Yes");
        for i in 0..n * n {
            if i != 0 {
                print!(" ");
            }
            print!("{}", ans[i] + 1);
        }
        println!();
    } else {
        println!("No");
    }
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

