fn main() {
    let n = read::<usize>();
    let x = read_vec::<usize>();
    let mut pairs = vec![];
    for (i, xnum) in x.into_iter().enumerate() {
        pairs.push((xnum - 1, i));
    }
    pairs.sort();
    let mut answers = vec![];
    let mut pointer = 0;

    let mut yobi = VecDeque::new();
    for i in 0..n {
        for _ in 0..i {
            yobi.push_back(i);
        }
    }

    let mut residual = VecDeque::new();
    for (xnum, i) in pairs {
        if pointer > xnum {
            println!("No");
            return;
        }
        while pointer < xnum {
            if let Some(top) = yobi.pop_front() {
                answers.push(top);
            } else if let Some(top) = residual.pop_front() {
                answers.push(top);
            } else {
                println!("No");
                return;
            }
            pointer += 1;
        }
        if !yobi.is_empty() && yobi[0] <= i {
            println!("No");
            return;
        }
        answers.push(i);
        pointer += 1;
        for _ in i + 1..n {
            residual.push_back(i);
        }
    }
    while let Some(top) = residual.pop_front() {
        answers.push(top);
        pointer += 1;
    }
    assert_eq!(pointer, n * n);
    assert_eq!(answers.len(), n * n);
    println!("Yes");
