fn main() {
    read!(n = usize);
    read!(xs = Vec<usize_>);
    let mut seq = vec![None; n*n];
    for (a, &x) in (0..).zip(&xs) {
        seq[x] = Some(a);
    }
    let mut pairs: Vec<(usize, usize)> = xs.iter().cloned().zip(0..).collect();
    pairs.sort();
    let aa: Vec<usize> = pairs.into_iter().map(|(_, a)| a).collect();
    let mut ls = Vec::new();
    for &a in &aa {
        for _ in 0..a {
            ls.push(a);
        }
    }
    ls.reverse();
    let mut l_exhausted = vec![false; n];
    l_exhausted[0] = true;
    let mut rs = Vec::new();
    for &a in &aa {
        for _ in 0..n-a-1 {
            rs.push(a);
        }
    }
    rs.reverse();
    let mut passed = vec![false; n];

    for i in 0..n*n {
        match seq[i] {
            None => {
                if !ls.is_empty() {
                    let a = ls.pop().unwrap();
                    if ls.last().map_or(true, |&next| next != a) {
                        l_exhausted[a] = true;
                    }
                    seq[i] = Some(a);
                } else {
                    let a = rs.pop().unwrap();
                    if !passed[a] {
                        exit("No");
                    }
                    seq[i] = Some(a);
                }
            },
            Some(a) => {
                if !l_exhausted[a] {
                    exit("No");
                }
                passed[a] = true;
            }
        }
    }
    println!("Yes");
    println!("{}", seq.into_iter().map(|x| x.unwrap() + 1).join(' '));
}

