fn solve(n: usize, x: Vec<usize>) -> Option<Vec<usize>> {
    let m = n*n;
    let mut a = vec![0; m];
    for i in 0..n {
        a[x[i]] = i+1;
    }
    let pa = a.clone();
    let mut free_bucket = VecDeque::new();
    for i in 0..n {
        for j in 0..i {
            free_bucket.push_back(i);
        }
    }

    let mut head = 0;
    for i in 0..m {
        if a[i] != 0 {
            let x = a[i];
            let mut need_to_prefill = x-1;
            while head < i && need_to_prefill >= 1 {
                if a[head] == 0 {
                    a[head] = x;
                    need_to_prefill -= 1;
                }
                head += 1;
            }
            if need_to_prefill != 0 {
                return None;
            }
        }
    }

    let mut postfill_queue = VecDeque::new();
    for i in 0..m {
        if pa[i] != 0 {
            for _ in pa[i]..n {
                postfill_queue.push_back(pa[i]);
            }
        } else if a[i] == 0 {
            if postfill_queue.len() >= 1 {
                a[i] = postfill_queue.pop_front().unwrap();
            } else {
                return None;
            }
        }
    }

    if postfill_queue.len() != 0 {
        return None;
    }
    for i in 0..m {
        if a[i] == 0 {
            return None;
        }
    }
    Some(a)
}

