fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut x = vec![];
    for i in 0..n {
        let a: usize = sc.read();
        x.push((a, i));
    }
    x.sort();

    let mut ans = vec![None; n * n];
    let mut hole_head = 0;
    let mut cur_sum = 0;
    for &(x, i) in x.iter() {
        let lower_count = i + 1;
        if cur_sum + lower_count > x {
            println!("No");
            return;
        }
        cur_sum += lower_count;
        ans[x - 1] = Some(i + 1);
        for _ in 1..lower_count {
            while ans[hole_head].is_some() {
                hole_head += 1;
                if hole_head >= n * n {
                    println!("No");
                    return;
                }
            }
            ans[hole_head] = Some(i + 1);
            hole_head += 1;
        }
    }

    let mut hole_tail = n * n - 1;
    let mut cur_sum = 0;
    for &(x, i) in x.iter().rev() {
        let upper_count = n - (i + 1);
        if cur_sum + upper_count > n * n - x {
            println!("No");
            return;
        }
        cur_sum += upper_count;
        for _ in 0..upper_count {
            while ans[hole_tail].is_some() {
                if hole_tail == 0 {
                    println!("No");
                    return;
                }
                hole_tail -= 1;
            }
            if hole_tail <= x - 1 {
                println!("No");
                return;
            }
            ans[hole_tail] = Some(i + 1);
        }
    }

    println!("Yes");
    for ans in ans.into_iter() {
        print!("{} ", ans.unwrap());
    }
    println!();
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

