fn main() {
    input! { n, x: [usize1; n] };
    let mut ans = vec![0; n * 3];
    for i in 0..n {
        ans[x[i]] = i + 1;
    }
    let mut idx = (0..n).collect::<Vec<_>>();
    idx.sort_by_key(|&i| x[i]);
    let mut i = 0;
    let mut j = 0;
    let mut need = (0..n).collect::<Vec<_>>();
    let mut free = vec![];
    while j < 3 * n {
        if ans[j] != 0 {
            free.extend((0..n - ans[j]).map(|_| ans[j]));
            j += 1;
            continue;
        }
        while i < n && need[idx[i]] == 0 {
            i += 1;
        }
        if i < n {
            ans[j] = idx[i] + 1;
            need[idx[i]] -= 1;
        } else if let Some(x) = free.pop() {
            ans[j] = x;
        } else {
            println!("No");
            return;
        }
        j += 1;
    }
    println!("Yes");
    for i in 0..n * 3 {
        print!("{} ", ans[i]);
    }
    println!("");
}

#![allow(unused_imports)]
#![allow(non_snake_case)]
use std::cmp::*;
use std::collections::*;
use std::io::Write;

#[allow(unused_macros)]
macro_rules! debug {
    ($($e:expr),*) => {
        #[cfg(debug_assertions)]
        $({
            let (e, mut err) = (stringify!($e), std::io::stderr());
            writeln!(err, "{} = {:?}", e, $e).unwrap()
        })*
    };
}

fn main() {
    let n = read::<usize>();
    let x = read_vec::<usize>();
    let mut pairs = vec![];
    for (i, xnum) in x.into_iter().enumerate() {
        pairs.push((xnum - 1, i));
    }
    pairs.sort();
    let mut answers = vec![];
    let mut pointer = 0;

    let mut yobi = VecDeque::new();
    for &(_, i) in pairs.iter() {
        for _ in 0..i {
            yobi.push_back(i);
        }
    }

    let mut residual = VecDeque::new();
    for (xnum, i) in pairs {
        if pointer > xnum {
            println!("No");
            return;
        }
        while pointer < xnum {
            if let Some(top) = yobi.pop_front() {
                answers.push(top);
            } else if let Some(top) = residual.pop_front() {
                answers.push(top);
            } else {
                println!("No");
                return;
            }
            pointer += 1;
        }
        if !yobi.is_empty() && yobi[0] <= i {
            println!("No");
            return;
        }
        answers.push(i);
        pointer += 1;
        for _ in i + 1..n {
            residual.push_back(i);
        }
    }
    while let Some(top) = residual.pop_front() {
        answers.push(top);
        pointer += 1;
    }
    assert_eq!(pointer, n * n);
    assert_eq!(answers.len(), n * n);
    println!("Yes");
    for ans in answers {
        print!("{} ", ans + 1);
    }
    println!("");
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

